// Generated by generators/create-events-file.ts — do not edit by hand.
import type { EventMapping } from '../generators/create-events-file'
export const EVENTS: EventMapping = {"battle-of-marathon":{"name":"Battle of Marathon","country":"GR","kind":"conflict","year":-490,"description":"Athens beat back the first Persian invasion of Greece on the plain of Marathon. The modern 42-kilometre race is named for the messenger legend that grew out of it.","image":"/events/battle-of-marathon.webp","credit":"John Steeple Davis","license":"Public domain"},"battle-of-thermopylae":{"name":"Battle of Thermopylae","country":"GR","kind":"conflict","year":-480,"description":"King Leonidas and his rearguard — the famous three hundred Spartans among them — held the mountain pass at Thermopylae for days against the vast Persian army before being wiped out.","image":"/events/battle-of-thermopylae.webp"},"death-of-alexander-the-great":{"name":"Death of Alexander the Great","country":"IQ","kind":"politics","year":-323,"description":"Alexander died in Babylon at thirty-two, ruler of an empire reaching from Greece to India. His generals immediately carved it apart.","image":"/events/death-of-alexander-the-great.webp","credit":"Urek Meniashvili","license":"CC BY-SA 3.0"},"qin-s-wars-of-unification":{"name":"China is unified under its First Emperor","country":"CN","kind":"nation","year":-221,"description":"The state of Qin swallowed the last of its rival kingdoms and its king proclaimed himself Qin Shi Huang — First Emperor. Standard script, currency and measures followed; so did the first Great Wall.","image":"/events/qin-s-wars-of-unification.webp"},"assassination-of-julius-caesar":{"name":"Assassination of Julius Caesar","country":"IT","kind":"politics","year":-44,"description":"Rome's dictator was stabbed by dozens of senators at a Senate meeting on the Ides of March. The republic they claimed to save died with him — his heir became the first emperor.","image":"/events/assassination-of-julius-caesar.webp","credit":"Vincenzo Camuccini","license":"Public domain"},"battle-of-actium":{"name":"Battle of Actium","country":"GR","kind":"conflict","year":-31,"description":"Octavian's fleet crushed Antony and Cleopatra off the west coast of Greece. Egypt fell, both lovers died by suicide, and Octavian ruled Rome alone as Augustus.","image":"/events/battle-of-actium.webp","credit":"Laureys a Castro","license":"Public domain"},"eruption-of-mount-vesuvius-in-79-ad":{"name":"Vesuvius buries Pompeii","country":"IT","kind":"disaster","year":79,"description":"Vesuvius erupted and buried Pompeii and Herculaneum under metres of ash, freezing two Roman towns mid-breath. They stayed sealed for over 1,500 years.","image":"/events/eruption-of-mount-vesuvius-in-79-ad.webp","credit":"Ivan Aivazovsky","license":"Public domain"},"edict-of-milan":{"name":"Edict of Milan","country":"IT","kind":"politics","year":313,"description":"Constantine and his co-emperor agreed to tolerate Christianity across the Roman Empire, ending centuries of persecution. Within a century it was the state religion.","image":"/events/edict-of-milan.webp","credit":"Marie-Lan Nguyen","license":"Public domain"},"fall-of-the-western-roman-empire":{"name":"Fall of the Western Roman Empire","country":"IT","kind":"nation","year":476,"description":"The Germanic commander Odoacer deposed the teenage emperor Romulus Augustulus and did not bother appointing another. The eastern half of the empire carried on from Constantinople for another thousand years.","image":"/events/fall-of-the-western-roman-empire.webp"},"hegira":{"name":"The Hegira — Muhammad leaves Mecca for Medina","country":"SA","kind":"culture","year":622,"description":"Muhammad and his followers left Mecca for Medina to escape persecution. The journey counts as year one of the Islamic calendar.","image":"/events/hegira.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"coronation-of-charlemagne":{"name":"Charlemagne is crowned emperor","country":"FR","kind":"politics","year":800,"description":"Pope Leo III crowned the Frankish king Charlemagne emperor in Rome on Christmas Day — the first western emperor in three centuries, and the seed of the Holy Roman Empire.","image":"/events/coronation-of-charlemagne.webp","credit":"Raphael","license":"Public domain"},"althing":{"name":"Iceland founds the Althing","country":"IS","kind":"culture","year":930,"description":"Icelandic chieftains began meeting each summer at Þingvellir in an assembly called the Althing. It still sits today — the world's oldest surviving parliament.","image":"/events/althing.webp","credit":"Bragi Thór Josefsson","license":"Public domain"},"christianization-of-kievan-rus":{"name":"Christianization of Kievan Rus'","country":"UA","kind":"culture","year":988,"description":"Grand Prince Vladimir of Kyiv had himself and his people baptised into Byzantine Christianity, mass-christening them in the Dnieper. Eastern Europe's religious map was drawn that day.","image":"/events/christianization-of-kievan-rus.webp","credit":"Klavdy Lebedev","license":"Public domain"},"east-west-schism":{"name":"The Great Schism splits Christianity","country":"VA","kind":"culture","year":1054,"description":"Rome and Constantinople excommunicated each other, splitting Christianity into Catholic and Orthodox halves. The mutual excommunications were only lifted in 1965.","image":"/events/east-west-schism.webp"},"battle-of-hastings":{"name":"Battle of Hastings","country":"GB","kind":"conflict","year":1066,"description":"William of Normandy killed King Harold and took England in a single October day. The conquest rewired the English language, law and aristocracy.","image":"/events/battle-of-hastings.webp","credit":"Myrabella","license":"Public domain"},"university-of-bologna":{"name":"The first university opens in Bologna","country":"IT","kind":"culture","year":1088,"description":"Law students in Bologna organised the institution now counted as the world's first university. The word universitas was coined for it.","image":"/events/university-of-bologna.webp","credit":"Utente:Mattia Barci","license":"CC BY-SA 4.0"},"siege-of-jerusalem-1099":{"name":"The First Crusade takes Jerusalem","country":"IL","kind":"conflict","year":1099,"description":"After a three-year march across Europe and Anatolia, the First Crusade stormed Jerusalem and massacred much of the city, founding a crusader kingdom that lasted not quite two centuries.","image":"/events/siege-of-jerusalem-1099.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"mongol-empire":{"name":"Genghis Khan founds the Mongol Empire","country":"MN","kind":"nation","year":1206,"description":"Temüjin united the feuding steppe tribes and took the title Genghis Khan. His descendants built the largest contiguous land empire in history.","image":"/events/mongol-empire.webp"},"magna-carta":{"name":"Magna Carta","country":"GB","kind":"politics","year":1215,"description":"Rebel barons cornered King John at Runnymede and made him seal a charter putting the king himself under the law. He repudiated it within weeks — but the idea never went away.","image":"/events/magna-carta.webp","license":"Public domain"},"ottoman-empire":{"name":"Osman founds the Ottoman state","country":"TR","kind":"nation","year":1299,"description":"A frontier warlord named Osman began carving a state out of crumbling Byzantine Anatolia. His house went on to rule an empire on three continents for six centuries.","image":"/events/ottoman-empire.webp"},"black-death":{"name":"The Black Death reaches Europe","country":"IT","kind":"disaster","year":1347,"description":"Plague arrived in Sicily aboard Genoese ships and burned through the continent, killing perhaps a third to a half of Europe within five years.","image":"/events/black-death.webp","credit":"Pierart dou Tielt (fl. 1340-1360)","license":"Public domain"},"kalmar-union":{"name":"Scandinavia unites under one crown","country":"DK","kind":"politics","year":1397,"description":"Denmark, Sweden and Norway were joined under a single monarch at Kalmar, run for most of its life from Copenhagen. Sweden fought its way out in 1523.","image":"/events/kalmar-union.webp"},"battle-of-grunwald":{"name":"Battle of Grunwald","country":"PL","kind":"conflict","year":1410,"description":"A combined Polish–Lithuanian army destroyed the Teutonic Knights in one of medieval Europe's largest battles, breaking the crusading order's power for good.","image":"/events/battle-of-grunwald.webp","credit":"Jan Matejko","license":"Public domain"},"ming-treasure-voyages":{"name":"Zheng He's treasure fleet sets sail","country":"CN","kind":"science","year":1405,"description":"The admiral Zheng He led enormous Ming fleets — some ships several times the size of anything in Europe — across the Indian Ocean as far as East Africa, decades before Columbus.","image":"/events/ming-treasure-voyages.webp","credit":"Photograph by Mike Peel (www.mikepeel.net).","license":"CC BY-SA 4.0"},"forbidden-city":{"name":"The Forbidden City is completed","country":"CN","kind":"engineering","year":1420,"description":"The Yongle Emperor moved the Ming capital to Beijing and into a brand-new walled palace of nearly a thousand buildings. Emperors ruled from it for the next five centuries.","image":"/events/forbidden-city.webp","credit":"N509FZ","license":"CC BY-SA 4.0"},"execution-of-joan-of-arc":{"name":"Joan of Arc is burned at the stake","country":"FR","kind":"conflict","year":1431,"description":"The nineteen-year-old who had turned the Hundred Years' War for France was burned as a heretic in English-held Rouen. A church court annulled the verdict 25 years later; she is now a saint.","image":"/events/execution-of-joan-of-arc.webp","credit":"François Chifflart","license":"Public domain"},"fall-of-constantinople":{"name":"Fall of Constantinople","country":"TR","kind":"conflict","year":1453,"description":"Mehmed II's cannon breached the walls that had held for a thousand years, ending the Byzantine Empire. Constantinople became the Ottoman capital.","image":"/events/fall-of-constantinople.webp","license":"Public domain"},"gutenberg-bible":{"name":"Gutenberg prints his Bible","country":"DE","kind":"science","year":1455,"description":"Johannes Gutenberg finished the first major book printed with movable metal type in Mainz. Printing made books cheap, and cheap books remade Europe.","image":"/events/gutenberg-bible.webp","credit":"Unknown authorUnknown author","license":"CC BY 4.0"},"granada-war":{"name":"Granada falls — the Reconquista ends","country":"ES","kind":"conflict","year":1492,"description":"The last Muslim emirate on the Iberian Peninsula surrendered to Ferdinand and Isabella, ending nearly eight centuries of Reconquista — months before the same monarchs funded Columbus.","image":"/events/granada-war.webp","credit":"Francisco Pradilla y Ortiz","license":"Public domain"},"first-voyage-of-christopher-columbus":{"name":"Columbus reaches the Americas","country":"BS","kind":"science","year":1492,"description":"Sailing west for Asia under the Spanish crown, Columbus made landfall in the Bahamas. He insisted to his death that he had reached the Indies.","image":"/events/first-voyage-of-christopher-columbus.webp","credit":"L. Prang &amp; Co., Boston","license":"Public domain"},"treaty-of-tordesillas":{"name":"Spain and Portugal divide the world","country":"ES","kind":"politics","year":1494,"description":"Spain and Portugal drew a meridian down the Atlantic and split all newly found lands between them. The line is why Brazil speaks Portuguese and most of Latin America Spanish.","image":"/events/treaty-of-tordesillas.webp"},"portuguese-discovery-of-the-sea-route-to-india":{"name":"Vasco da Gama reaches India by sea","country":"IN","kind":"science","year":1498,"description":"Vasco da Gama rounded Africa and anchored off Calicut, opening the first all-sea route between Europe and Asia and breaking the overland spice monopoly.","image":"/events/portuguese-discovery-of-the-sea-route-to-india.webp"},"ninety-five-theses":{"name":"Luther posts his Ninety-five Theses","country":"DE","kind":"culture","year":1517,"description":"Martin Luther published ninety-five arguments against the sale of indulgences in Wittenberg. The printing press did the rest — the Reformation split western Christianity.","image":"/events/ninety-five-theses.webp","credit":"Martin Luther","license":"Public domain"},"fall-of-tenochtitlan":{"name":"Fall of Tenochtitlan","country":"MX","kind":"conflict","year":1521,"description":"Cortés, his indigenous allies and a smallpox epidemic brought down the Aztec capital after a brutal siege. Mexico City rose on its ruins.","image":"/events/fall-of-tenochtitlan.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"magellan-expedition":{"name":"The first circumnavigation of the Earth","country":"ES","kind":"science","year":1522,"description":"Of the five ships and roughly 270 men who left Spain, one ship and 18 men returned three years later, having sailed all the way around the world. Magellan himself died in the Philippines.","image":"/events/magellan-expedition.webp","credit":"Abraham Ortelius","license":"Public domain"},"first-battle-of-panipat":{"name":"Babur founds the Mughal Empire","country":"IN","kind":"nation","year":1526,"description":"Babur's cannon and cavalry destroyed the Delhi Sultanate's much larger army at Panipat. The Mughal dynasty he founded ruled most of India into the era of the British.","image":"/events/first-battle-of-panipat.webp","credit":"1598 artist","license":"Public domain"},"battle-of-cajamarca":{"name":"Pizarro captures the Inca emperor","country":"PE","kind":"conflict","year":1532,"description":"Francisco Pizarro ambushed the emperor Atahualpa at Cajamarca with fewer than 200 men. A room full of gold was paid in ransom; Atahualpa was executed anyway, and the Inca Empire fell.","image":"/events/battle-of-cajamarca.webp","credit":"Juan Lepiani","license":"Public domain"},"de-revolutionibus-orbium-coelestium":{"name":"Copernicus puts the Sun at the centre","country":"PL","kind":"science","year":1543,"description":"Copernicus's book placing the Sun, not the Earth, at the centre of the universe was published as he lay dying. It took a century — and Galileo's trial — for the idea to win.","image":"/events/de-revolutionibus-orbium-coelestium.webp","credit":"Mikołaj Kopernik","license":"Public domain"},"great-siege-of-malta":{"name":"Great Siege of Malta","country":"MT","kind":"conflict","year":1565,"description":"A few thousand Knights of St John and Maltese defenders held the island against a massive Ottoman armada for four months. The capital Valletta was founded on the victory.","image":"/events/great-siege-of-malta.webp","credit":"Matteo Perez d'Aleccio","license":"Public domain"},"battle-of-lepanto":{"name":"Battle of Lepanto","country":"GR","kind":"conflict","year":1571,"description":"A Holy League fleet shattered the Ottoman navy off western Greece in the last great battle between rowed galleys. Cervantes lost the use of a hand there, years before writing Don Quixote.","image":"/events/battle-of-lepanto.webp","credit":"Unidentified painter","license":"Public domain"},"spanish-armada":{"name":"The Spanish Armada is defeated","country":"GB","kind":"conflict","year":1588,"description":"Philip II's invasion fleet was beaten in the Channel and wrecked by storms on the long way home around Scotland and Ireland. England stayed Protestant, and stayed uninvaded.","image":"/events/spanish-armada.webp","credit":"anonymous","license":"Public domain"},"battle-of-sekigahara":{"name":"Battle of Sekigahara","country":"JP","kind":"conflict","year":1600,"description":"Tokugawa Ieyasu won the decisive battle for control of Japan. The shogunate his victory founded kept the country at peace — and closed to most of the world — for over 250 years.","image":"/events/battle-of-sekigahara.webp","license":"Public domain"},"dutch-east-india-company":{"name":"The Dutch East India Company is founded","country":"NL","kind":"politics","year":1602,"description":"The Dutch merged their Asia traders into the VOC, the first company to issue shares to the public — armed with its own fleets, forts and colonies.","image":"/events/dutch-east-india-company.webp","credit":"McKarri","license":"CC BY-SA 3.0"},"jamestown":{"name":"Jamestown — England lands in America","country":"US","kind":"nation","year":1607,"description":"The first permanent English settlement in the Americas was planted on a Virginia river island. Two-thirds of the first colonists were dead within a year, but the foothold held.","image":"/events/jamestown.webp","credit":"Peter Vander (via Conway Whittle Sams)","license":"Public domain"},"second-defenestration-of-prague":{"name":"Prague throws its governors out the window","country":"CZ","kind":"conflict","year":1618,"description":"Protestant nobles hurled two imperial governors from a castle window in Prague — they survived the drop — and lit the fuse of the Thirty Years' War, which devastated Central Europe.","image":"/events/second-defenestration-of-prague.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"mayflower":{"name":"The Mayflower sails","country":"US","kind":"nation","year":1620,"description":"A hundred-odd settlers, the Pilgrims among them, crossed from England to Cape Cod aboard the Mayflower, signing a self-government compact before stepping ashore.","image":"/events/mayflower.webp","credit":"William Halsall","license":"Public domain"},"peace-of-westphalia":{"name":"Peace of Westphalia","country":"DE","kind":"politics","year":1648,"description":"The treaties ending the Thirty Years' War fixed the principle that each state is sovereign within its own borders — the operating system of international politics ever since.","image":"/events/peace-of-westphalia.webp","credit":"Gerard ter Borch","license":"Public domain"},"great-fire-of-london":{"name":"Great Fire of London","country":"GB","kind":"disaster","year":1666,"description":"A bakery fire on Pudding Lane burned four-fifths of the walled city over four days, destroying more than 13,000 houses and old St Paul's Cathedral — yet recorded deaths were few.","image":"/events/great-fire-of-london.webp","credit":"Unknown artistUnknown artist","license":"Public domain"},"battle-of-vienna":{"name":"The Ottomans are turned back at Vienna","country":"AT","kind":"conflict","year":1683,"description":"The second and last Ottoman siege of Vienna was broken by a relief army under the Polish king Jan Sobieski, whose winged hussars delivered one of history's largest cavalry charges.","image":"/events/battle-of-vienna.webp","credit":"Juliusz Kossak","license":"Public domain"},"philosophi-naturalis-principia-mathematica":{"name":"Newton publishes the Principia","country":"GB","kind":"science","year":1687,"description":"Newton's Principia set out the laws of motion and universal gravitation — one mathematics for a falling apple and an orbiting Moon.","image":"/events/philosophi-naturalis-principia-mathematica.webp","credit":"The original uploader was Zhaladshar at English Wikisource.","license":"Public domain"},"glorious-revolution":{"name":"Glorious Revolution","country":"GB","kind":"revolution","year":1688,"description":"Parliament's allies invited William of Orange to invade and King James II fled without a battle. The Bill of Rights that followed made the English crown answer to Parliament.","image":"/events/glorious-revolution.webp","credit":"Johan Herman Isings","license":"Public domain"},"saint-petersburg":{"name":"Peter the Great founds Saint Petersburg","country":"RU","kind":"nation","year":1703,"description":"Peter the Great founded a new capital on Baltic marshland seized from Sweden — his \"window to Europe\", built at enormous human cost and modelled on the West.","image":"/events/saint-petersburg.webp","credit":"Florstein (Telegram:WikiPhoto.Space)","license":"CC BY-SA 4.0"},"acts-of-union-1707":{"name":"England and Scotland become Great Britain","country":"GB","kind":"nation","year":1707,"description":"The English and Scottish parliaments voted themselves into a single Kingdom of Great Britain with one parliament at Westminster.","image":"/events/acts-of-union-1707.webp","credit":"Parliament of England","license":"Public domain"},"battle-of-poltava":{"name":"Battle of Poltava","country":"UA","kind":"conflict","year":1709,"description":"Peter the Great destroyed Charles XII's invading Swedish army deep in Ukraine. Sweden's run as a great power ended on that field; Russia's began.","image":"/events/battle-of-poltava.webp","credit":"Pierre-Denis Martin","license":"Public domain"},"1755-lisbon-earthquake":{"name":"An earthquake destroys Lisbon","country":"PT","kind":"disaster","year":1755,"description":"An earthquake, tsunami and days of fire destroyed most of Lisbon on All Saints' Day. The catastrophe shook European philosophy — Voltaire wrote Candide in its shadow.","image":"/events/1755-lisbon-earthquake.webp"},"battle-of-plassey":{"name":"The East India Company takes Bengal","country":"IN","kind":"conflict","year":1757,"description":"Robert Clive's small Company army — helped by a bought-off commander — defeated the Nawab of Bengal at Plassey. A trading company began ruling the richest province in India.","image":"/events/battle-of-plassey.webp","credit":"Francis Hayman","license":"Public domain"},"boston-tea-party":{"name":"Boston Tea Party","country":"US","kind":"revolution","year":1773,"description":"Colonists disguised as Mohawks dumped 342 chests of East India Company tea into Boston Harbor rather than pay Parliament's tax on it. Britain's crackdown pushed the colonies toward war.","image":"/events/boston-tea-party.webp","credit":"Nathaniel Currier","license":"Public domain"},"united-states-declaration-of-independence":{"name":"United States Declaration of Independence","country":"US","kind":"nation","year":1776,"description":"Thirteen British colonies declared themselves free and independent states, resting the claim on the self-evident truth that all men are created equal.","image":"/events/united-states-declaration-of-independence.webp","credit":"original: w:Second Continental Congress; reproduction: William Stone","license":"Public domain"},"sydney":{"name":"The First Fleet reaches Australia","country":"AU","kind":"nation","year":1788,"description":"Eleven British ships carrying around 1,400 people — most of them convicts — anchored at Sydney Cove to found a penal colony, beginning the European settlement of Australia.","image":"/events/sydney.webp","credit":"W. Bulach","license":"CC BY-SA 4.0"},"storming-of-the-bastille":{"name":"Storming of the Bastille","country":"FR","kind":"revolution","year":1789,"description":"A Paris crowd stormed the royal fortress-prison of the Bastille, found just seven prisoners, and started the French Revolution anyway. July 14 is still France's national day.","image":"/events/storming-of-the-bastille.webp","credit":"Jean-Pierre Houël","license":"Public domain"},"haitian-revolution":{"name":"Haitian Revolution","country":"HT","kind":"revolution","year":1791,"description":"The enslaved people of France's richest colony rose, defeated their enslavers and the armies of three empires, and by 1804 had founded Haiti — history's only successful slave revolution to birth a state.","image":"/events/haitian-revolution.webp","credit":"January Suchodolski","license":"Public domain"},"rosetta-stone":{"name":"The Rosetta Stone is found","country":"EG","kind":"science","year":1799,"description":"French soldiers rebuilding a fort in the Nile Delta dug up a slab carrying the same decree in three scripts. It became the key that unlocked Egyptian hieroglyphs.","image":"/events/rosetta-stone.webp","credit":"Awikimate","license":"CC BY-SA 4.0"},"coronation-of-napoleon-i":{"name":"Napoleon crowns himself emperor","country":"FR","kind":"politics","year":1804,"description":"In Notre-Dame, with the Pope watching, Napoleon took the crown and set it on his own head. The republic born of the Revolution had become an empire.","image":"/events/coronation-of-napoleon-i.webp","credit":"Jacques-Louis David","license":"Public domain"},"battle-of-trafalgar":{"name":"Battle of Trafalgar","country":"GB","kind":"conflict","year":1805,"description":"Nelson destroyed the combined French and Spanish fleets off Cape Trafalgar and died aboard Victory in the doing. Britain ruled the waves for the next century.","image":"/events/battle-of-trafalgar.webp","credit":"Nicholas Pocock","license":"Public domain"},"slave-trade-act-1807":{"name":"Britain abolishes the slave trade","country":"GB","kind":"politics","year":1807,"description":"Parliament outlawed the Atlantic slave trade across the British Empire, and the Royal Navy began intercepting slave ships. Slavery itself in the colonies lasted until 1833.","image":"/events/slave-trade-act-1807.webp"},"french-invasion-of-russia":{"name":"Napoleon marches on Moscow","country":"RU","kind":"conflict","year":1812,"description":"Napoleon led some 600,000 men into Russia and reached a burning, empty Moscow. Winter, hunger and Cossacks destroyed the Grande Armée on the way home — a tenth of it returned.","image":"/events/french-invasion-of-russia.webp","credit":"Blaue Max","license":"CC BY-SA 4.0"},"battle-of-waterloo":{"name":"Battle of Waterloo","country":"BE","kind":"conflict","year":1815,"description":"Escaped from Elba, Napoleon gambled everything on one battle in Belgium and lost it to Wellington and Blücher. He spent his last six years on Saint Helena in the South Atlantic.","image":"/events/battle-of-waterloo.webp","credit":"William Sadler","license":"Public domain"},"congress-of-vienna":{"name":"Congress of Vienna","country":"AT","kind":"politics","year":1815,"description":"Europe's powers redrew the map after Napoleon, restoring monarchs and balancing power. The settlement kept the continent free of a general war for nearly a century.","image":"/events/congress-of-vienna.webp","credit":"Thomas Ledl","license":"CC BY-SA 4.0"},"argentine-declaration-of-independence":{"name":"Argentine Declaration of Independence","country":"AR","kind":"nation","year":1816,"description":"Delegates meeting in Tucumán declared the Provinces of the Río de la Plata independent of Spain, formalising a revolution that had been fighting since 1810.","image":"/events/argentine-declaration-of-independence.webp","credit":"Argentina. Congreso de Tucumán.","license":"Public domain"},"battle-of-boyaca":{"name":"Bolívar frees New Granada","country":"CO","kind":"revolution","year":1819,"description":"Simón Bolívar surprised the Spanish after a brutal march over the Andes and broke their army at Boyacá, freeing Bogotá. Gran Colombia was proclaimed months later.","image":"/events/battle-of-boyaca.webp","credit":"Martin Tovar y Tovar","license":"Public domain"},"greek-war-of-independence":{"name":"Greek War of Independence","country":"GR","kind":"revolution","year":1821,"description":"Greece rose against four centuries of Ottoman rule. Europe's romantics rallied to the cause — Lord Byron died for it — and an independent Greek state emerged within a decade.","image":"/events/greek-war-of-independence.webp","credit":"Louis Dupré","license":"Public domain"},"mexican-war-of-independence":{"name":"Mexico wins independence","country":"MX","kind":"nation","year":1821,"description":"Eleven years after the priest Hidalgo's dawn call to revolt, the Army of the Three Guarantees rode into Mexico City and New Spain became independent Mexico.","image":"/events/mexican-war-of-independence.webp","credit":"Hpav7","license":"Public domain"},"independence-of-brazil":{"name":"Independence of Brazil","country":"BR","kind":"nation","year":1822,"description":"The Portuguese crown prince Pedro, ruling from Rio, declared \"Independence or death!\" on the banks of the Ipiranga and became Brazil's first emperor — independence via the royal family itself.","image":"/events/independence-of-brazil.webp","credit":"Pedro Américo","license":"Public domain"},"battle-of-ayacucho":{"name":"Spanish rule in South America ends","country":"PE","kind":"revolution","year":1824,"description":"Sucre's patriot army defeated the last Spanish royalist force in the Peruvian highlands at Ayacucho, sealing the independence of Spanish South America.","image":"/events/battle-of-ayacucho.webp","credit":"Martín Tovar y Tovar","license":"Public domain"},"stockton-and-darlington-railway":{"name":"The first public steam railway opens","country":"GB","kind":"engineering","year":1825,"description":"The Stockton and Darlington in northern England became the first public railway worked by steam locomotives. Within a generation, railways had shrunk the world.","image":"/events/stockton-and-darlington-railway.webp","credit":"John Dobbin","license":"Public domain"},"belgian-revolution":{"name":"Belgium breaks away","country":"BE","kind":"nation","year":1830,"description":"A revolt that began after an opera performance in Brussels drove out the Dutch and created an independent, neutral Belgium with its own king.","image":"/events/belgian-revolution.webp","credit":"Gustaaf Wappers","license":"Public domain"},"slavery-abolition-act-1833":{"name":"Britain abolishes slavery","country":"GB","kind":"politics","year":1833,"description":"Parliament abolished slavery across most of the British Empire, freeing some 800,000 people — while paying slave-owners, not the enslaved, £20 million in compensation.","image":"/events/slavery-abolition-act-1833.webp"},"first-opium-war":{"name":"First Opium War","country":"CN","kind":"conflict","year":1839,"description":"China's destruction of British opium stocks brought gunboats. Defeat forced open treaty ports and ceded Hong Kong — the start of what China calls its century of humiliation.","image":"/events/first-opium-war.webp","credit":"Edward Duncan","license":"Public domain"},"treaty-of-waitangi":{"name":"Treaty of Waitangi","country":"NZ","kind":"politics","year":1840,"description":"British officials and some 540 Māori chiefs signed New Zealand's founding document. Its English and Māori texts differ on the crucial word — sovereignty — and the argument continues today.","image":"/events/treaty-of-waitangi.webp","license":"Public domain"},"great-famine-ireland":{"name":"The Great Famine strikes Ireland","country":"IE","kind":"disaster","year":1845,"description":"Potato blight destroyed the crop that fed Ireland's poor. A million people died and over a million emigrated while food exports continued — the island's population has never recovered.","image":"/events/great-famine-ireland.webp","credit":"Illustrated London News, December 22, 1849","license":"Public domain"},"liberian-declaration-of-independence":{"name":"Liberia declares independence","country":"LR","kind":"nation","year":1847,"description":"The West African colony founded for freed Black Americans declared itself a republic — Africa's first — with a constitution and flag modelled on the United States.","image":"/events/liberian-declaration-of-independence.webp","credit":"Government of Liberia","license":"Public domain"},"revolutions-of-1848":{"name":"Revolutions sweep Europe","country":"FR","kind":"revolution","year":1848,"description":"Uprisings toppled the French king and shook thrones from Berlin to Vienna to Palermo in the most widespread revolutionary wave Europe has seen. Nearly all were crushed within a year.","image":"/events/revolutions-of-1848.webp","credit":"Horace Vernet","license":"Public domain"},"the-communist-manifesto":{"name":"The Communist Manifesto","country":"GB","kind":"culture","year":1848,"description":"Marx and Engels published their pamphlet in London weeks before revolution swept Europe. \"Workers of the world, unite!\" went on to reorganise half the planet.","image":"/events/the-communist-manifesto.webp","credit":"Friedrich Engels, Karl Marx","license":"Public domain"},"taiping-rebellion":{"name":"Taiping Rebellion","country":"CN","kind":"revolution","year":1850,"description":"A failed exam candidate who believed himself the younger brother of Jesus raised a rebel Heavenly Kingdom against the Qing. The fourteen-year civil war killed some twenty million people.","image":"/events/taiping-rebellion.webp"},"great-exhibition":{"name":"The Great Exhibition opens in the Crystal Palace","country":"GB","kind":"culture","year":1851,"description":"The first world's fair filled a vast prefabricated glass hall in Hyde Park with the machines and goods of the industrial age. Six million people came — a third of Britain's population.","image":"/events/great-exhibition.webp","credit":"Dickinson Brothers","license":"Public domain"},"crimean-war":{"name":"Crimean War","country":"UA","kind":"conflict","year":1853,"description":"Britain, France and the Ottomans fought Russia, mostly on the Crimean peninsula. It gave the world the Charge of the Light Brigade, war photography and Florence Nightingale's nursing reforms.","image":"/events/crimean-war.webp","credit":"British Army official photographer","license":"Public domain"},"indian-rebellion-of-1857":{"name":"The sepoys rise against the East India Company","country":"IN","kind":"revolution","year":1857,"description":"Sepoy regiments rose against the East India Company and the revolt spread across northern India. After its brutal suppression, the British Crown took direct rule of India from the Company.","image":"/events/indian-rebellion-of-1857.webp"},"on-the-origin-of-species":{"name":"Darwin publishes On the Origin of Species","country":"GB","kind":"science","year":1859,"description":"Darwin's book laid out evolution by natural selection after twenty years of hesitation. The first print run sold out to booksellers on day one.","image":"/events/on-the-origin-of-species.webp","credit":"John Murray, Publisher","license":"Public domain"},"kingdom-of-italy":{"name":"Italy is unified","country":"IT","kind":"nation","year":1861,"description":"After Garibaldi's thousand red-shirted volunteers took the south, the Kingdom of Italy was proclaimed under Victor Emmanuel II — the peninsula's first single state since Rome. Venice and Rome itself joined within a decade.","image":"/events/kingdom-of-italy.webp","credit":"F l a n k e r","license":"Public domain"},"american-civil-war":{"name":"American Civil War","country":"US","kind":"conflict","year":1861,"description":"Eleven slave states seceded and the Union fought them back over four years — the deadliest war in American history. It ended slavery by the Thirteenth Amendment.","image":"/events/american-civil-war.webp","credit":"Nathaniel Currier and James Merritt Ives","license":"Public domain"},"emancipation-reform-of-1861":{"name":"Russia frees the serfs","country":"RU","kind":"politics","year":1861,"description":"Tsar Alexander II emancipated more than twenty million serfs — bound peasants who could be bought and sold with the land. Freedom came with debts that kept most of them poor.","image":"/events/emancipation-reform-of-1861.webp","credit":"Boris Kustodiev","license":"Public domain"},"international-committee-of-the-red-cross":{"name":"The Red Cross is founded","country":"CH","kind":"politics","year":1863,"description":"Horrified by the untended wounded at Solferino, the Geneva businessman Henry Dunant founded the Red Cross. The first Geneva Convention followed a year later.","image":"/events/international-committee-of-the-red-cross.webp","credit":"Torbjorn Toby Jorgensen","license":"CC BY-SA 2.0"},"alaska-purchase":{"name":"The United States buys Alaska","country":"US","kind":"politics","year":1867,"description":"Russia sold Alaska to the United States for $7.2 million — about two cents an acre. Critics called it \"Seward's Folly\" until the gold and oil turned up.","image":"/events/alaska-purchase.webp","credit":"Edouard de Stoeckl and William H. Seward","license":"Public domain"},"canadian-confederation":{"name":"Canadian Confederation","country":"CA","kind":"nation","year":1867,"description":"Three British North American colonies federated into the Dominion of Canada — a country assembled by conference and statute rather than revolution.","image":"/events/canadian-confederation.webp"},"meiji-restoration":{"name":"Meiji Restoration","country":"JP","kind":"revolution","year":1868,"description":"Samurai from the southwest toppled the shogunate and restored the young Meiji emperor. Japan then industrialised at a sprint, going from feudal isolation to great power in one generation.","image":"/events/meiji-restoration.webp","credit":"Alfred Roussin","license":"Public domain"},"suez-canal":{"name":"The Suez Canal opens","country":"EG","kind":"engineering","year":1869,"description":"Ten years of digging joined the Mediterranean to the Red Sea, cutting the Europe–Asia voyage by weeks. Verdi's Aida was commissioned for the Cairo opera house that opened alongside it.","image":"/events/suez-canal.webp","credit":"Pierre Markuse from Hamm, Germany","license":"CC BY 2.0"},"first-transcontinental-railroad":{"name":"America's coasts are joined by rail","country":"US","kind":"engineering","year":1869,"description":"A golden spike at Promontory Summit, Utah joined the tracks built east from Sacramento and west from Omaha. A months-long wagon crossing became a week by train.","image":"/events/first-transcontinental-railroad.webp","credit":"Andrew J. Russell (1830-1902), photographer","license":"Public domain"},"paris-commune":{"name":"Paris Commune","country":"FR","kind":"revolution","year":1871,"description":"After France's defeat by Prussia, Paris rose and governed itself as a radical commune for 72 days before the army retook the city street by street, killing thousands in Bloody Week.","image":"/events/paris-commune.webp","credit":"Anonyme, photographe","license":"CC0"},"unification-of-germany":{"name":"Germany is unified","country":"DE","kind":"nation","year":1871,"description":"After Prussia's victory over France, the German Empire was proclaimed — pointedly — in the Hall of Mirrors at Versailles, with the Prussian king as Kaiser and Bismarck as chancellor.","image":"/events/unification-of-germany.webp","credit":"Anton von Werner","license":"Public domain"},"berlin-conference":{"name":"Europe carves up Africa","country":"DE","kind":"politics","year":1884,"description":"European powers met in Berlin to set the rules for claiming African territory — no African was at the table. Within two decades the continent was almost entirely colonised.","image":"/events/berlin-conference.webp","credit":"Adalbert von Roessler","license":"Public domain"},"1883-eruption-of-krakatoa":{"name":"Krakatoa blows itself apart","country":"ID","kind":"disaster","year":1883,"description":"The island volcano between Java and Sumatra blew itself apart with a blast heard 4,800 kilometres away. Its tsunamis killed tens of thousands, and its dust reddened sunsets worldwide for years.","image":"/events/1883-eruption-of-krakatoa.webp","credit":"AnonymousUnknown author","license":"Public domain"},"statue-of-liberty":{"name":"The Statue of Liberty is dedicated","country":"US","kind":"engineering","year":1886,"description":"France's copper colossus — designed by Bartholdi, engineered inside by Eiffel — was unveiled in New York Harbor, greeting the greatest wave of immigration in American history.","image":"/events/statue-of-liberty.webp","credit":"Christian David","license":"CC BY-SA 4.0"},"lei-aurea":{"name":"Brazil abolishes slavery","country":"BR","kind":"politics","year":1888,"description":"Princess Isabel signed the Golden Law, freeing Brazil's remaining enslaved people with a single sentence. Brazil was the last country in the Americas to abolish slavery.","image":"/events/lei-aurea.webp","credit":"Valter Campanato/Agência Brasil","license":"CC BY 2.0"},"eiffel-tower":{"name":"The Eiffel Tower opens","country":"FR","kind":"engineering","year":1889,"description":"Built as the entrance arch to a Paris World's Fair and meant to stand twenty years, it was then the tallest structure on Earth. The city's artists petitioned furiously against it.","image":"/events/eiffel-tower.webp","credit":"Benh LIEU SONG","license":"Public domain"},"battle-of-adwa":{"name":"Ethiopia defeats an invading empire","country":"ET","kind":"conflict","year":1896,"description":"Emperor Menelik II's army routed the invading Italians at Adwa. Ethiopia became the great exception of the colonial age — an African state that beat a European power and kept its independence.","image":"/events/battle-of-adwa.webp","license":"CC BY-SA 3.0"},"1896-summer-olympics":{"name":"The first modern Olympics","country":"GR","kind":"culture","year":1896,"description":"The Olympic Games returned after fifteen centuries, staged in Athens with 14 nations. A Greek water-carrier, Spyridon Louis, won the first marathon and became a national hero.","image":"/events/1896-summer-olympics.webp","credit":"Docpix","license":"Public domain"},"klondike-gold-rush":{"name":"Klondike Gold Rush","country":"CA","kind":"culture","year":1896,"description":"Gold found in a Yukon creek sent a hundred thousand stampeders over frozen mountain passes toward Dawson City. Most arrived to find the good claims long staked.","image":"/events/klondike-gold-rush.webp","credit":"Eric A. Hegg","license":"Public domain"},"spanish-american-war":{"name":"Spanish–American War","country":"CU","kind":"conflict","year":1898,"description":"A ten-week war fought over Cuba ended Spain's empire in the Americas and the Pacific. The United States emerged with Puerto Rico, Guam and the Philippines — a colonial power itself.","image":"/events/spanish-american-war.webp","credit":"Barbudo Barbudo and TEP","license":"CC BY-SA 4.0"},"second-boer-war":{"name":"Second Boer War","country":"ZA","kind":"conflict","year":1899,"description":"Britain fought the Boer republics for three years over southern Africa and its gold. The war introduced the world to the term \"concentration camp\", where tens of thousands died.","image":"/events/second-boer-war.webp","credit":"Reinhold Thiele","license":"Public domain"},"boxer-rebellion":{"name":"Boxer Rebellion","country":"CN","kind":"revolution","year":1900,"description":"An anti-foreign uprising besieged Beijing's diplomatic quarter for 55 days until an eight-nation army marched on the capital. The indemnities imposed helped bring down the Qing a decade later.","image":"/events/boxer-rebellion.webp"},"federation-of-australia":{"name":"Federation of Australia","country":"AU","kind":"nation","year":1901,"description":"Six self-governing British colonies federated into the Commonwealth of Australia on the first day of the new century — nationhood by referendum rather than revolution.","image":"/events/federation-of-australia.webp"},"nobel-prize":{"name":"The first Nobel Prizes are awarded","country":"SE","kind":"culture","year":1901,"description":"The fortune of Alfred Nobel — the inventor of dynamite — funded the first prizes for physics, chemistry, medicine, literature and peace, awarded in Stockholm and Oslo.","image":"/events/nobel-prize.webp","credit":"Nobel Foundation, diploma by Sofia Gisberg[1]","license":"Public domain"},"wright-flyer":{"name":"The Wright brothers fly","country":"US","kind":"science","year":1903,"description":"On a North Carolina beach, the Wright brothers made the first controlled, powered aeroplane flights. The longest of the day covered 260 metres — less than a modern jet's wingspan-to-tail walk.","image":"/events/wright-flyer.webp","credit":"John T. Daniels","license":"Public domain"},"russo-japanese-war":{"name":"Russo-Japanese War","country":"JP","kind":"conflict","year":1904,"description":"Japan fought Russia over Korea and Manchuria and won on land and at sea, annihilating the Baltic Fleet at Tsushima — the first modern defeat of a European great power by an Asian one.","image":"/events/russo-japanese-war.webp","credit":"Original uploader and author was Dustandshadow at en.wikipedia","license":"Public domain"},"dissolution-of-the-union-between-norway-and-sweden":{"name":"Norway leaves its union with Sweden","country":"NO","kind":"nation","year":1905,"description":"Norway voted itself out of the union with Sweden — 368,208 for, 184 against — and both sides let it happen peacefully. A Danish prince became King Haakon VII.","image":"/events/dissolution-of-the-union-between-norway-and-sweden.webp"},"1906-san-francisco-earthquake":{"name":"San Francisco burns after the earthquake","country":"US","kind":"disaster","year":1906,"description":"The earthquake and the three days of fire that followed destroyed most of San Francisco, leaving over half the city's population homeless.","image":"/events/1906-san-francisco-earthquake.webp","credit":"Chadwick, H. D","license":"Public domain"},"young-turk-revolution":{"name":"Young Turk Revolution","country":"TR","kind":"revolution","year":1908,"description":"Army officers of the Young Turk movement forced the sultan to restore the constitution and parliament, beginning the Ottoman Empire's last, turbulent decade.","image":"/events/young-turk-revolution.webp"},"mexican-revolution":{"name":"Mexican Revolution","country":"MX","kind":"revolution","year":1910,"description":"What began as a revolt against the thirty-year rule of Porfirio Díaz became a decade of civil war — Zapata and Villa among its generals — that killed perhaps a million Mexicans.","image":"/events/mexican-revolution.webp"},"amundsen-s-south-pole-expedition":{"name":"Amundsen reaches the South Pole","country":"NO","kind":"science","year":1911,"description":"Roald Amundsen's ski-and-dog-sled team reached the South Pole five weeks ahead of Robert Scott, whose entire party died on the return march.","image":"/events/amundsen-s-south-pole-expedition.webp"},"xinhai-revolution":{"name":"China's last dynasty falls","country":"CN","kind":"revolution","year":1911,"description":"A mutiny at Wuchang cascaded into national revolution, and within months the six-year-old Puyi abdicated. Two thousand years of imperial rule ended; the Republic of China began.","image":"/events/xinhai-revolution.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"sinking-of-the-titanic":{"name":"Sinking of the Titanic","country":"GB","kind":"disaster","year":1912,"description":"The largest ship afloat, promoted as practically unsinkable, struck an iceberg on her maiden voyage and sank with around 1,500 people — lifeboats had seats for barely half of those aboard.","image":"/events/sinking-of-the-titanic.webp"},"panama-canal":{"name":"The Panama Canal opens","country":"PA","kind":"engineering","year":1914,"description":"The canal cut through the isthmus joined the Atlantic and Pacific, sparing ships the 13,000-kilometre voyage around Cape Horn. France had tried first and lost some 20,000 workers to disease.","image":"/events/panama-canal.webp","credit":"User:Stan Shebs","license":"CC BY-SA 3.0"},"assassination-of-archduke-franz-ferdinand":{"name":"Shots at Sarajevo — the spark of WWI","country":"BA","kind":"conflict","year":1914,"description":"A Bosnian Serb student shot the Austro-Hungarian heir and his wife in Sarajevo. Five weeks of ultimatums and mobilisations later, most of Europe was at war.","image":"/events/assassination-of-archduke-franz-ferdinand.webp","credit":"Achille Beltrame","license":"Public domain"},"gallipoli-campaign":{"name":"Gallipoli campaign","country":"TR","kind":"conflict","year":1915,"description":"The Allied attempt to force the Dardanelles and take Constantinople died on the Gallipoli beaches. The defence made Mustafa Kemal's name; the landings are founding memory for Australia and New Zealand.","image":"/events/gallipoli-campaign.webp"},"armenian-genocide":{"name":"Armenian genocide","country":"AM","kind":"conflict","year":1915,"description":"The Ottoman government deported the empire's Armenians into the Syrian desert through massacre and death march, killing perhaps a million or more. The word \"genocide\" was later coined largely for it.","image":"/events/armenian-genocide.webp","credit":"Henry Morgenthau","license":"Public domain"},"easter-rising":{"name":"Easter Rising","country":"IE","kind":"revolution","year":1916,"description":"Irish republicans seized central Dublin and proclaimed a republic from the General Post Office. The rising was crushed in six days, but the execution of its leaders turned the country against British rule.","image":"/events/easter-rising.webp","credit":"Miller, James Martin &amp; H.S. Canfield.","license":"Public domain"},"october-revolution":{"name":"October Revolution","country":"RU","kind":"revolution","year":1917,"description":"Lenin's Bolsheviks seized Petrograd's key points and the Winter Palace in a nearly bloodless coup, eight months after the tsar had fallen. The world's first communist state followed.","image":"/events/october-revolution.webp","credit":"Pyotr Novitsky","license":"Public domain"},"finnish-declaration-of-independence":{"name":"Finland declares independence","country":"FI","kind":"nation","year":1917,"description":"As revolutionary Russia collapsed, Finland's parliament declared independence after a century as a Russian grand duchy — recognised, remarkably, by Lenin's new government within a month.","image":"/events/finnish-declaration-of-independence.webp","credit":"Senate of Finland","license":"Public domain"},"armistice-of-11-november-1918":{"name":"The Armistice ends the First World War","country":"FR","kind":"conflict","year":1918,"description":"In a railway carriage in the forest of Compiègne, the guns of the First World War fell silent at the eleventh hour of the eleventh day of the eleventh month. Some 17 million people were dead.","image":"/events/armistice-of-11-november-1918.webp","credit":"Maurice Pillard Verneuil","license":"Public domain"},"spanish-flu":{"name":"The great flu pandemic sweeps the world","country":"US","kind":"disaster","year":1918,"description":"The influenza pandemic at the close of the Great War infected a third of humanity and killed at least 50 million — more than the war it rode in on. It was called \"Spanish\" only because Spain's uncensored press reported it first.","image":"/events/spanish-flu.webp","credit":"Otis Historical Archives, National Museum of Health and Medicine","license":"Public domain"},"treaty-of-versailles":{"name":"Treaty of Versailles","country":"FR","kind":"politics","year":1919,"description":"The peace signed in the Hall of Mirrors stripped Germany of territory and empire and billed it for the war. Its \"war guilt\" terms became tinder for the next one.","image":"/events/treaty-of-versailles.webp","credit":"David Lloyd George, Woodrow Wilson and Georges Clemenceau","license":"Public domain"},"jallianwala-bagh-massacre":{"name":"Jallianwala Bagh massacre","country":"IN","kind":"conflict","year":1919,"description":"British troops fired without warning into a trapped crowd in a walled garden in Amritsar, killing hundreds. The massacre broke Indian faith in the empire and swelled the independence movement.","image":"/events/jallianwala-bagh-massacre.webp","credit":"PP Yoonus (ppyoonus@yahoo.co.in)","license":"Public domain"},"league-of-nations":{"name":"The League of Nations convenes","country":"CH","kind":"politics","year":1920,"description":"The first world organisation for collective security assembled in Geneva — without the United States, whose Senate refused to join the body its own president had championed.","image":"/events/league-of-nations.webp"},"anglo-irish-treaty":{"name":"The Irish Free State is born","country":"IE","kind":"nation","year":1921,"description":"The treaty ending the Irish War of Independence created a self-governing Free State of 26 counties, with six remaining British. The split over its terms led straight into civil war.","image":"/events/anglo-irish-treaty.webp"},"march-on-rome":{"name":"Mussolini takes power","country":"IT","kind":"revolution","year":1922,"description":"Mussolini's blackshirts converged on the capital and the king, rather than order the army to stop them, invited the Fascist leader to form a government. Europe had its first fascist state.","image":"/events/march-on-rome.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"tomb-of-tutankhamun":{"name":"Tutankhamun's tomb is opened","country":"EG","kind":"science","year":1922,"description":"Howard Carter found the one royal tomb in the Valley of the Kings that robbers had barely touched. Asked if he could see anything through the breach, he answered: \"Yes, wonderful things.\"","image":"/events/tomb-of-tutankhamun.webp","credit":"EditorfromMars","license":"CC BY-SA 4.0"},"soviet-union":{"name":"The Soviet Union is formed","country":"RU","kind":"nation","year":1922,"description":"Russia, Ukraine, Belarus and the Transcaucasus signed themselves into the Union of Soviet Socialist Republics — on paper a federation, in practice ruled from Moscow. It lasted 69 years.","image":"/events/soviet-union.webp","credit":"Cmapm","license":"CC BY-SA 3.0"},"1923-great-kanto-earthquake":{"name":"The Great Kantō earthquake levels Tokyo","country":"JP","kind":"disaster","year":1923,"description":"The earthquake and firestorms that followed destroyed Tokyo and Yokohama, killing over 100,000 people — Japan's deadliest disaster, struck at lunchtime while the city's stoves were lit.","image":"/events/1923-great-kanto-earthquake.webp","license":"Public domain"},"republic-of-turkiye":{"name":"Atatürk proclaims the Turkish republic","country":"TR","kind":"nation","year":1923,"description":"From the Ottoman Empire's ruins, Mustafa Kemal — later Atatürk, \"father of the Turks\" — proclaimed a republic with its capital at Ankara, then remade alphabet, dress and law at speed.","image":"/events/republic-of-turkiye.webp","credit":"Jorge Franganillo from Barcelona, Spain","license":"CC BY 2.0"},"discovery-of-penicillin":{"name":"Fleming discovers penicillin","country":"GB","kind":"science","year":1928,"description":"Alexander Fleming returned from holiday to find mould killing the bacteria on a neglected culture plate. The antibiotic age it opened has saved hundreds of millions of lives.","image":"/events/discovery-of-penicillin.webp"},"wall-street-crash-of-1929":{"name":"Wall Street crashes","country":"US","kind":"disaster","year":1929,"description":"The New York stock market collapsed over a handful of October days, erasing fortunes and confidence together. The Great Depression that followed put a quarter of Americans out of work.","image":"/events/wall-street-crash-of-1929.webp","credit":"US-gov","license":"Public domain"},"salt-march":{"name":"Gandhi marches to the sea for salt","country":"IN","kind":"revolution","year":1930,"description":"Gandhi walked 385 kilometres to the sea and picked up a handful of salt, breaking the British monopoly law. The gesture ignited mass civil disobedience across India.","image":"/events/salt-march.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"1930-fifa-world-cup":{"name":"The first football World Cup","country":"UY","kind":"culture","year":1930,"description":"Uruguay hosted and won the first World Cup, beating Argentina 4–2 in Montevideo. Only thirteen teams came — every European entrant had to be talked into the boat journey.","image":"/events/1930-fifa-world-cup.webp"},"empire-state-building":{"name":"The Empire State Building opens","country":"US","kind":"engineering","year":1931,"description":"Built in a Depression-defying 13 months, the 102-storey tower took the title of world's tallest building and held it for four decades.","image":"/events/empire-state-building.webp","credit":"Sam Valadi","license":"Public domain"},"siamese-revolution-of-1932":{"name":"Siam ends absolute monarchy","country":"TH","kind":"revolution","year":1932,"description":"A bloodless dawn coup by young officers and officials ended seven centuries of absolute monarchy in Siam, forcing the king to accept a constitution.","image":"/events/siamese-revolution-of-1932.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"machtergreifung":{"name":"Hitler comes to power","country":"DE","kind":"revolution","year":1933,"description":"Hitler was appointed chancellor by President Hindenburg, and within months the Nazis had burned out the Reichstag opposition, banned rival parties and ruled by decree.","image":"/events/machtergreifung.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"long-march":{"name":"Long March","country":"CN","kind":"conflict","year":1934,"description":"Encircled by Nationalist armies, the Chinese communists broke out and marched thousands of kilometres over mountains and rivers to a new base at Yan'an. Mao emerged from it as the party's leader.","image":"/events/long-march.webp"},"second-italo-ethiopian-war":{"name":"Italy invades Ethiopia","country":"ET","kind":"conflict","year":1935,"description":"Mussolini invaded Ethiopia with tanks, bombers and poison gas, avenging Adwa forty years on. The League of Nations' failure to stop it exposed collective security as a dead letter.","image":"/events/second-italo-ethiopian-war.webp","credit":"Achille Beltrame","license":"Public domain"},"spanish-civil-war":{"name":"Spanish Civil War","country":"ES","kind":"conflict","year":1936,"description":"A generals' rising against the republic tore Spain apart for three years, with Hitler and Mussolini arming Franco and volunteers from fifty countries fighting for the other side. Franco's dictatorship lasted until 1975.","image":"/events/spanish-civil-war.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"golden-gate-bridge":{"name":"The Golden Gate Bridge opens","country":"US","kind":"engineering","year":1937,"description":"The longest suspension span yet built crossed the fog-swept strait at the mouth of San Francisco Bay. Its \"international orange\" paint was meant to be temporary.","image":"/events/golden-gate-bridge.webp","credit":"Rich Niewiroski Jr.","license":"CC BY 2.5"},"hindenburg-disaster":{"name":"Hindenburg disaster","country":"US","kind":"disaster","year":1937,"description":"The hydrogen-filled German airship burst into flames while landing in New Jersey, killing 36 — with newsreel cameras rolling. The age of the great passenger airships ended in that minute.","image":"/events/hindenburg-disaster.webp","credit":"Sam Shere","license":"Public domain"},"nanjing-massacre":{"name":"Nanjing Massacre","country":"CN","kind":"conflict","year":1937,"description":"After the fall of China's capital, Japanese troops spent weeks massacring prisoners and civilians and raping tens of thousands. The death toll is contested; the horror is not.","image":"/events/nanjing-massacre.webp","credit":"Originally Moriyasu Murase, 村瀬守保","license":"Public domain"},"kristallnacht":{"name":"Kristallnacht","country":"DE","kind":"conflict","year":1938,"description":"In a single organised November night, Nazi mobs burned over a thousand synagogues and smashed Jewish shops and homes across Germany and Austria. The name mocks the broken glass in the streets.","image":"/events/kristallnacht.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"invasion-of-poland":{"name":"The Second World War begins","country":"PL","kind":"conflict","year":1939,"description":"Germany invaded Poland from the west; the Soviet Union followed from the east under their secret pact. Britain and France declared war on Germany two days in — the Second World War had begun.","image":"/events/invasion-of-poland.webp","license":"Public domain"},"battle-of-britain":{"name":"Battle of Britain","country":"GB","kind":"conflict","year":1940,"description":"The Luftwaffe spent a summer trying to break the RAF as the prelude to invasion, and failed — the war's first check on Germany. \"Never was so much owed by so many to so few.\"","image":"/events/battle-of-britain.webp","credit":"German Air Force photographer","license":"Public domain"},"attack-on-pearl-harbor":{"name":"Attack on Pearl Harbor","country":"US","kind":"conflict","year":1941,"description":"Japanese carrier aircraft struck the US Pacific Fleet at anchor in Hawaii on a Sunday morning, sinking battleships and killing over 2,400 Americans. The United States entered the war the next day.","image":"/events/attack-on-pearl-harbor.webp","credit":"Unknown navy photographer","license":"Public domain"},"battle-of-stalingrad":{"name":"Battle of Stalingrad","country":"RU","kind":"conflict","year":1942,"description":"The Wehrmacht bled out in five months of street fighting on the Volga, and the encircled Sixth Army surrendered in the ruins. It was the turning point of the war in Europe.","image":"/events/battle-of-stalingrad.webp","credit":"Abram Krichevsky (Q4241405) / TASS (Q223799)","license":"Public domain"},"normandy-landings":{"name":"D-Day — the Allies land in Normandy","country":"FR","kind":"conflict","year":1944,"description":"On the sixth of June, some 156,000 Allied troops crossed the Channel onto five Normandy beaches in history's largest seaborne invasion. Paris was free within three months.","image":"/events/normandy-landings.webp","credit":"Chief Photographer's Mate (CPHoM) Robert F. Sargent","license":"Public domain"},"bretton-woods-conference":{"name":"Bretton Woods Conference","country":"US","kind":"politics","year":1944,"description":"Delegates from 44 Allied nations, meeting at a New Hampshire resort hotel, designed the postwar money system — fixed exchange rates, the IMF and the World Bank.","image":"/events/bretton-woods-conference.webp","credit":"Barry Livingstone","license":"CC BY-SA 3.0"},"iceland":{"name":"Iceland becomes a republic","country":"IS","kind":"nation","year":1944,"description":"With Denmark under German occupation, Icelanders voted almost unanimously to dissolve the union with the Danish crown and founded a republic at Þingvellir, seat of their thousand-year-old assembly.","image":"/events/iceland.webp","credit":"European Space Agency","license":"Attribution"},"atomic-bombings-of-hiroshima-and-nagasaki":{"name":"Atomic bombs fall on Japan","country":"JP","kind":"conflict","year":1945,"description":"The first nuclear weapons used in war destroyed Hiroshima and, three days later, Nagasaki, killing well over a hundred thousand people by year's end. Japan surrendered within a week of the second bomb.","image":"/events/atomic-bombings-of-hiroshima-and-nagasaki.webp","credit":"George R. Caron / Charles Levy","license":"Public domain"},"united-nations":{"name":"The United Nations is founded","country":"US","kind":"politics","year":1945,"description":"Fifty-one nations signed the UN Charter in San Francisco, determined — its opening words say — \"to save succeeding generations from the scourge of war\".","image":"/events/united-nations.webp","credit":"U.S. Department of State from United States","license":"Public domain"},"nuremberg-trials":{"name":"Nuremberg trials","country":"DE","kind":"politics","year":1945,"description":"The surviving Nazi leadership was tried by an international tribunal in Nuremberg for crimes against humanity — the founding precedent that following orders is no defence.","image":"/events/nuremberg-trials.webp","credit":"Raymond D’Addario","license":"Public domain"},"treaty-of-manila-1946":{"name":"The Philippines becomes independent","country":"PH","kind":"nation","year":1946,"description":"The United States recognised Philippine independence on 4 July 1946, closing nearly half a century of American rule that had followed three centuries of Spanish rule.","image":"/events/treaty-of-manila-1946.webp"},"partition-of-india":{"name":"India and Pakistan are born","country":"IN","kind":"nation","year":1947,"description":"British India was split at midnight into independent India and Pakistan. The partition uprooted some 15 million people along hastily drawn lines and killed perhaps a million in the violence.","image":"/events/partition-of-india.webp"},"marshall-plan":{"name":"Marshall Plan","country":"US","kind":"politics","year":1948,"description":"The United States poured about $13 billion into rebuilding Western Europe's shattered economies — and binding them to the West as the Cold War hardened.","image":"/events/marshall-plan.webp"},"assassination-of-mahatma-gandhi":{"name":"Assassination of Mahatma Gandhi","country":"IN","kind":"politics","year":1948,"description":"Five months into independence, Gandhi was shot dead at his evening prayer meeting in Delhi by a Hindu nationalist who blamed him for partition and for conciliating Muslims.","image":"/events/assassination-of-mahatma-gandhi.webp","credit":"Wilson Loo Kok Wee","license":"CC BY-SA 2.0"},"israeli-declaration-of-independence":{"name":"The State of Israel is declared","country":"IL","kind":"nation","year":1948,"description":"David Ben-Gurion proclaimed the State of Israel in Tel Aviv as the British mandate expired. Five Arab armies crossed the borders the next day; the war's displacements shape the region still.","image":"/events/israeli-declaration-of-independence.webp","credit":"Rudi Weissenstein","license":"Public domain"},"berlin-blockade":{"name":"The Berlin Airlift begins","country":"DE","kind":"conflict","year":1948,"description":"The Soviets cut every road and rail line into West Berlin, and the Western allies fed two million people by air for eleven months — a plane landing roughly every minute at the peak.","image":"/events/berlin-blockade.webp","credit":"Heilig, Walter","license":"CC BY-SA 3.0 de"},"universal-declaration-of-human-rights":{"name":"Universal Declaration of Human Rights","country":"FR","kind":"politics","year":1948,"description":"The UN General Assembly, meeting in Paris, adopted thirty articles of rights belonging to every human being — drafted by a committee chaired by Eleanor Roosevelt.","image":"/events/universal-declaration-of-human-rights.webp","credit":"FDR Presidential Library &amp; Museum","license":"CC BY 2.0"},"nato":{"name":"NATO is founded","country":"US","kind":"politics","year":1949,"description":"Twelve North Atlantic nations signed a treaty in Washington making an attack on one an attack on all. Article 5 has been invoked once — after September 11.","image":"/events/nato.webp","credit":"Влада на Република Северна Македонија","license":"Public domain"},"proclamation-of-the-people-s-republic-of-china":{"name":"Proclamation of the People's Republic of China","country":"CN","kind":"nation","year":1949,"description":"From the Tiananmen gate, Mao proclaimed the People's Republic after the communists' civil-war victory. The defeated Nationalists withdrew to Taiwan — both governments still claim to be China.","image":"/events/proclamation-of-the-people-s-republic-of-china.webp","credit":"Orihara1","license":"Public domain"},"korean-war":{"name":"Korean War","country":"KR","kind":"conflict","year":1950,"description":"North Korea invaded the South and a UN force led by the United States fought it — and then China — to a stalemate near where the war began. An armistice, never a peace treaty, holds the line today.","image":"/events/korean-war.webp","credit":"All photographs are works of the United States federal government.","license":"Public domain"},"egyptian-revolution-of-1952":{"name":"The Free Officers topple Egypt's king","country":"EG","kind":"revolution","year":1952,"description":"Army officers led by Nasser and Naguib deposed King Farouk in a night, ending the monarchy and British-era rule. Nasser's Egypt became the pole star of Arab nationalism.","image":"/events/egyptian-revolution-of-1952.webp"},"1953-british-mount-everest-expedition":{"name":"Everest is climbed","country":"NP","kind":"science","year":1953,"description":"Edmund Hillary and Tenzing Norgay stood on the summit of Everest on 29 May 1953 — the first people on the highest point on Earth. News reached London on Coronation morning.","image":"/events/1953-british-mount-everest-expedition.webp","credit":"after George Mallory","license":"Public domain"},"molecular-structure-of-nucleic-acids-a-structure-for-deoxyribose-nucleic-acid":{"name":"The DNA double helix is revealed","country":"GB","kind":"science","year":1953,"description":"Watson and Crick published DNA's double-helix structure, built on Rosalind Franklin's X-ray images. The paper's closing understatement — the structure \"suggests a possible copying mechanism\" — opened modern genetics.","image":"/events/molecular-structure-of-nucleic-acids-a-structure-for-deoxyribose-nucleic-acid.webp"},"battle-of-dien-bien-phu":{"name":"France falls at Dien Bien Phu","country":"VN","kind":"conflict","year":1954,"description":"The Viet Minh dragged artillery up jungle mountains and crushed the French garrison in its valley fortress. French Indochina ended at the conference table weeks later, with Vietnam divided at the 17th parallel.","image":"/events/battle-of-dien-bien-phu.webp","credit":"Vietnam People's Army","license":"Public domain"},"warsaw-pact":{"name":"Warsaw Pact","country":"PL","kind":"politics","year":1955,"description":"The Soviet Union bound its Eastern European satellites into a military alliance answering NATO. Its only joint invasion was of one of its own members — Czechoslovakia, 1968.","image":"/events/warsaw-pact.webp","credit":"愛喝奶茶","license":"CC BY-SA 4.0"},"montgomery-bus-boycott":{"name":"Rosa Parks keeps her seat","country":"US","kind":"culture","year":1955,"description":"Rosa Parks was arrested for refusing to give up her bus seat, and Black Montgomery walked for 381 days until the buses were desegregated. The boycott's young spokesman was Martin Luther King Jr.","image":"/events/montgomery-bus-boycott.webp","credit":"Rmhermen","license":"CC BY-SA 3.0"},"bandung-conference":{"name":"Bandung Conference","country":"ID","kind":"politics","year":1955,"description":"Twenty-nine newly independent Asian and African states met in Bandung to chart a course between the Cold War blocs — the seedbed of the Non-Aligned Movement.","image":"/events/bandung-conference.webp","credit":"Foreign Ministry of the Republic of Indonesia","license":"Public domain"},"hungarian-revolution-of-1956":{"name":"Budapest rises against Soviet rule","country":"HU","kind":"revolution","year":1956,"description":"Budapest rose against Soviet rule and for a few days Hungary was free — until the tanks returned. Thousands died and 200,000 fled west while the world watched.","image":"/events/hungarian-revolution-of-1956.webp","credit":"Atoljaka","license":"CC BY 4.0"},"suez-crisis":{"name":"Suez Crisis","country":"EG","kind":"conflict","year":1956,"description":"When Nasser nationalised the Suez Canal, Britain, France and Israel invaded — and were forced out by American and Soviet pressure. The end of empire had a date on it after Suez.","image":"/events/suez-crisis.webp","credit":"United States Army Heritage and Education Center","license":"Public domain"},"independence-of-ghana":{"name":"Ghana leads Africa to independence","country":"GH","kind":"nation","year":1957,"description":"The Gold Coast became Ghana under Kwame Nkrumah — the first sub-Saharan colony to win independence. \"Our independence is meaningless,\" he said that night, \"unless it is linked up with the total liberation of Africa.\"","image":"/events/independence-of-ghana.webp","credit":"The National Archives UK - Flickr account","license":"OGL v1.0"},"treaty-of-rome":{"name":"Six nations found the Common Market","country":"IT","kind":"politics","year":1957,"description":"France, West Germany, Italy and the Benelux countries signed the Treaty of Rome, creating the European Economic Community — the six-member seed of today's European Union.","image":"/events/treaty-of-rome.webp"},"sputnik-1":{"name":"Sputnik opens the Space Age","country":"RU","kind":"science","year":1957,"description":"The Soviet Union lofted a beeping 58-centimetre metal sphere into orbit — the first artificial satellite. Its radio signal, audible to amateurs worldwide, started the space race.","image":"/events/sputnik-1.webp","credit":"Andrey Butko","license":"CC BY-SA 3.0"},"malayan-declaration-of-independence":{"name":"Malaya becomes independent","country":"MY","kind":"nation","year":1957,"description":"At midnight in Kuala Lumpur's Merdeka Stadium, the Federation of Malaya became independent of Britain to shouts of \"Merdeka!\" — freedom. Malaysia was formed six years later.","image":"/events/malayan-declaration-of-independence.webp","credit":"Orhanghazi","license":"CC BY-SA 4.0"},"cuban-revolution":{"name":"Cuban Revolution","country":"CU","kind":"revolution","year":1959,"description":"Fidel Castro's guerrillas came down from the Sierra Maestra and took Havana on New Year's Day as Batista fled. Within two years Cuba was a communist state ninety miles from Florida.","image":"/events/cuban-revolution.webp","license":"Public domain"},"independence-of-nigeria":{"name":"Nigeria becomes independent","country":"NG","kind":"nation","year":1960,"description":"Africa's most populous country took independence from Britain in the \"Year of Africa\", when seventeen African nations raised new flags.","image":"/events/independence-of-nigeria.webp"},"independence-of-the-democratic-republic-of-the-congo":{"name":"The Congo becomes independent","country":"CD","kind":"nation","year":1960,"description":"Belgium handed over the Congo at two weeks' organised notice after decades of brutal rule. Within months the army mutinied, Katanga seceded and Prime Minister Lumumba was murdered.","image":"/events/independence-of-the-democratic-republic-of-the-congo.webp"},"vostok-1":{"name":"Gagarin — the first human in space","country":"RU","kind":"science","year":1961,"description":"Yuri Gagarin orbited the Earth once in 108 minutes aboard Vostok 1 and landed by parachute a national hero. He was 27, and the first human being to see the planet whole.","image":"/events/vostok-1.webp","credit":"Tempe","license":"Public domain"},"berlin-wall":{"name":"The Berlin Wall goes up","country":"DE","kind":"conflict","year":1961,"description":"East Germany sealed West Berlin overnight with barbed wire that hardened into a concrete wall, to stop the exodus of its own citizens — about one in six had already left. It stood for 28 years.","image":"/events/berlin-wall.webp","credit":"Edward Valachovic https://www.flickr.com/people/fauxaddress/","license":"CC BY-SA 2.0"},"evian-accords":{"name":"Algeria wins independence","country":"DZ","kind":"nation","year":1962,"description":"The accords signed at Évian ended an eight-year war that had killed hundreds of thousands and brought down France's Fourth Republic. A million French settlers left Algeria within months.","image":"/events/evian-accords.webp"},"cuban-missile-crisis":{"name":"Cuban Missile Crisis","country":"CU","kind":"conflict","year":1962,"description":"For thirteen October days the superpowers stood at the edge of nuclear war over Soviet missiles in Cuba, until Khrushchev withdrew them — and the US quietly pulled its own from Turkey.","image":"/events/cuban-missile-crisis.webp","credit":"Central Intelligence Agency","license":"Public domain"},"independence-of-jamaica":{"name":"Jamaica becomes independent","country":"JM","kind":"nation","year":1962,"description":"Jamaica left the failed West Indies Federation and took full independence from Britain, the first of the anglophone Caribbean islands to do so.","image":"/events/independence-of-jamaica.webp"},"assassination-of-john-f-kennedy":{"name":"Assassination of John F. Kennedy","country":"US","kind":"politics","year":1963,"description":"President Kennedy was shot dead in an open car in Dallas. The murder, caught on a bystander's home-movie camera, has fed six decades of grief and conspiracy alike.","image":"/events/assassination-of-john-f-kennedy.webp","credit":"Walt Cisco, Dallas Morning News","license":"Public domain"},"march-on-washington-for-jobs-and-freedom":{"name":"\"I Have a Dream\" — the March on Washington","country":"US","kind":"culture","year":1963,"description":"A quarter of a million people filled the Mall to demand civil rights, and Martin Luther King Jr. told them his dream from the Lincoln Memorial steps. The Civil Rights Act passed the next year.","image":"/events/march-on-washington-for-jobs-and-freedom.webp","credit":"Center for Jewish History, NYC","license":"Public domain"},"independence-of-singapore":{"name":"Singapore goes it alone","country":"SG","kind":"nation","year":1965,"description":"Expelled from Malaysia after two years, Singapore became a sovereign city-state against its own wishes — Lee Kuan Yew wept announcing it. It became one of the world's richest places anyway.","image":"/events/independence-of-singapore.webp"},"six-day-war":{"name":"Six-Day War","country":"IL","kind":"conflict","year":1967,"description":"Israel destroyed the Egyptian air force on the ground in the war's opening hours and in six days took Sinai, Gaza, the West Bank, East Jerusalem and the Golan — territories at the heart of the conflict since.","image":"/events/six-day-war.webp"},"first-heart-transplant":{"name":"The first human heart transplant","country":"ZA","kind":"science","year":1967,"description":"Christiaan Barnard's team at Cape Town's Groote Schuur Hospital transplanted a human heart for the first time. The patient lived 18 days; the operation changed what surgery believed possible.","image":"/events/first-heart-transplant.webp"},"prague-spring":{"name":"Prague Spring","country":"CZ","kind":"revolution","year":1968,"description":"Czechoslovakia's reform communists promised \"socialism with a human face\" — until half a million Warsaw Pact troops arrived in August to shut it down. The thaw was over in a night.","image":"/events/prague-spring.webp","credit":"The Central Intelligence Agency","license":"Public domain"},"assassination-of-martin-luther-king-jr":{"name":"Assassination of Martin Luther King Jr.","country":"US","kind":"politics","year":1968,"description":"King was shot on a Memphis motel balcony at 39, in town to support striking sanitation workers. Riots broke out in over a hundred American cities in the week that followed.","image":"/events/assassination-of-martin-luther-king-jr.webp","credit":"Dick DeMarsico","license":"Public domain"},"apollo-11":{"name":"Apollo 11 — humans walk on the Moon","country":"US","kind":"science","year":1969,"description":"Armstrong and Aldrin landed on the Sea of Tranquility with about 25 seconds of fuel to spare while some 600 million people watched. Twelve people have walked the Moon; the last left three years later, and no one has been back.","image":"/events/apollo-11.webp","credit":"NASA","license":"Public domain"},"woodstock":{"name":"Woodstock","country":"US","kind":"culture","year":1969,"description":"Some 400,000 people descended on a dairy farm in upstate New York for three days of music and rain. The festival lost money, ran out of everything, and became the emblem of a generation.","image":"/events/woodstock.webp","credit":"Derek Redmond and Paul Campbell","license":"CC BY-SA 3.0"},"concorde":{"name":"Concorde's first flight","country":"FR","kind":"engineering","year":1969,"description":"The Anglo-French supersonic airliner flew for the first time from Toulouse. It crossed the Atlantic in under three and a half hours for 27 years — no passenger aircraft has gone supersonic since 2003.","image":"/events/concorde.webp","credit":"Eduard Marmet","license":"CC BY-SA 3.0"},"aswan-dam":{"name":"Work begins on the Aswan High Dam","country":"EG","kind":"engineering","year":1960,"description":"A decade in the building, the Soviet-financed dam tamed the Nile's ancient flood and lit Egypt — while drowning Nubian homelands and forcing the block-by-block rescue of the Abu Simbel temples.","image":"/events/aswan-dam.webp","credit":"شرف الدين","license":"CC BY-SA 3.0"},"bangladesh-liberation-war":{"name":"Bangladesh is born","country":"BD","kind":"nation","year":1971,"description":"East Pakistan broke from the West in a nine-month war marked by genocide and ten million refugees. With India's intervention it ended in the birth of Bangladesh.","image":"/events/bangladesh-liberation-war.webp"},"1971-ugandan-coup-d-etat":{"name":"Idi Amin seizes Uganda","country":"UG","kind":"revolution","year":1971,"description":"General Idi Amin took Uganda while the president was abroad. His eight years killed perhaps 300,000 people and expelled the country's entire Asian community on ninety days' notice.","image":"/events/1971-ugandan-coup-d-etat.webp"},"munich-massacre":{"name":"Munich massacre","country":"DE","kind":"conflict","year":1972,"description":"Palestinian gunmen took the Israeli team hostage at the Munich Olympics; eleven athletes and coaches died, most in a botched rescue at the airport. The Games controversially went on.","image":"/events/munich-massacre.webp","credit":"AP Photo/Kurt Strumpf (? – 2014)","license":"Public domain"},"sydney-opera-house":{"name":"The Sydney Opera House opens","country":"AU","kind":"engineering","year":1973,"description":"Jørn Utzon's sail-roofed masterpiece opened ten years late and fourteen times over budget — its Danish architect had resigned and never returned to see it finished.","image":"/events/sydney-opera-house.webp","license":"CC BY-SA 3.0"},"1973-chilean-coup-d-etat":{"name":"Pinochet's coup in Chile","country":"CL","kind":"revolution","year":1973,"description":"The armed forces bombed the presidential palace, President Allende died there, and General Pinochet's junta ruled for 17 years — thousands were executed, tortured or disappeared.","image":"/events/1973-chilean-coup-d-etat.webp","credit":"Biblioteca del Congreso Nacional de Chile","license":"CC BY 3.0 cl"},"1973-oil-crisis":{"name":"The oil embargo quadruples the price of crude","country":"SA","kind":"politics","year":1973,"description":"Arab oil producers embargoed the West over the October war with Israel and prices quadrupled in months — queues at petrol pumps, speed limits, and the end of the postwar boom.","image":"/events/1973-oil-crisis.webp","credit":"Warren K. Leffler, U.S. News &amp; World Report Magazine","license":"Public domain"},"carnation-revolution":{"name":"Carnation Revolution","country":"PT","kind":"revolution","year":1974,"description":"Junior officers toppled Europe's oldest dictatorship in a day, signalled by songs on the radio, and crowds put carnations in the soldiers' rifle barrels. Portugal's African colonies were free within two years.","image":"/events/carnation-revolution.webp"},"turkish-invasion-of-cyprus":{"name":"Cyprus is divided","country":"CY","kind":"conflict","year":1974,"description":"After a Greek-backed coup aimed at union with Greece, Turkey invaded and took the island's north. A UN buffer zone has split Cyprus — and its capital Nicosia — ever since.","image":"/events/turkish-invasion-of-cyprus.webp"},"fall-of-saigon":{"name":"The Vietnam War ends","country":"VN","kind":"conflict","year":1975,"description":"North Vietnamese tanks broke through the gates of Saigon's Presidential Palace as the last Americans left by helicopter from an embassy roof. Vietnam was reunified after thirty years of war.","image":"/events/fall-of-saigon.webp"},"independence-of-angola":{"name":"Angola becomes independent","country":"AO","kind":"nation","year":1975,"description":"Angola took independence as Portugal's empire collapsed after the Carnation Revolution — and slid straight into a superpower-fuelled civil war that ran, with pauses, until 2002.","image":"/events/independence-of-angola.webp"},"death-of-francisco-franco":{"name":"Franco dies — Spain turns to democracy","country":"ES","kind":"politics","year":1975,"description":"Franco died after 36 years of dictatorship, and the king he had groomed, Juan Carlos, steered Spain instead to parliamentary democracy within three years.","image":"/events/death-of-francisco-franco.webp"},"soweto-uprising":{"name":"Soweto uprising","country":"ZA","kind":"revolution","year":1976,"description":"Soweto's schoolchildren marched against being taught in Afrikaans and the police opened fire. Hundreds died in the months that followed, and a generation was radicalised against apartheid.","image":"/events/soweto-uprising.webp","credit":"Sam Nzima","license":"Public domain"},"1976-tangshan-earthquake":{"name":"An earthquake flattens Tangshan","country":"CN","kind":"disaster","year":1976,"description":"An earthquake flattened the industrial city of Tangshan before dawn, killing at least 240,000 people by official count — the deadliest earthquake of the twentieth century.","image":"/events/1976-tangshan-earthquake.webp","credit":"the National Oceanic and Atmospheric Administration","license":"Public domain"},"voyager-1":{"name":"Voyager 1 leaves for the outer planets","country":"US","kind":"science","year":1977,"description":"Launched to fly past Jupiter and Saturn, Voyager 1 kept going — now the most distant human-made object, carrying a golden record of Earth's sounds, and still calling home from interstellar space.","image":"/events/voyager-1.webp","credit":"NASA/JPL","license":"Public domain"},"camp-david-accords":{"name":"Camp David Accords","country":"EG","kind":"politics","year":1978,"description":"Thirteen secret days at the US presidential retreat produced a framework for peace between Egypt and Israel — the first Arab state to recognise Israel. Sadat paid for it with his life three years later.","image":"/events/camp-david-accords.webp","credit":"Fitz-Patrick, Bill, photographer","license":"Public domain"},"iranian-revolution":{"name":"Iranian Revolution","country":"IR","kind":"revolution","year":1979,"description":"Mass protests drove out the Shah, and Ayatollah Khomeini returned from exile to found an Islamic republic. The US embassy hostage crisis began within the year.","image":"/events/iranian-revolution.webp","credit":"Unknown authorUnknown author","license":"GFDL"},"soviet-afghan-war":{"name":"The Soviets invade Afghanistan","country":"AF","kind":"conflict","year":1979,"description":"Soviet troops took Kabul in the last week of the year and stayed nine more, fighting US-armed mujahideen. The war helped exhaust the USSR — and seeded the conflicts that followed.","image":"/events/soviet-afghan-war.webp","credit":"LLs","license":"CC BY-SA 4.0"},"independence-of-zimbabwe":{"name":"Zimbabwe becomes independent","country":"ZW","kind":"nation","year":1980,"description":"White-ruled Rhodesia became independent Zimbabwe after a long guerrilla war and the Lancaster House settlement. Robert Mugabe won the first elections — and held power for 37 years.","image":"/events/independence-of-zimbabwe.webp"},"solidarity-polish-trade-union":{"name":"Solidarity is born in the Gdańsk shipyard","country":"PL","kind":"revolution","year":1980,"description":"Striking Gdańsk shipyard workers led by Lech Wałęsa forced the communist state to accept the Soviet bloc's first independent trade union. Ten million Poles joined within a year.","image":"/events/solidarity-polish-trade-union.webp","credit":"Zenon Mirota","license":"CC BY-SA 3.0 pl"},"iran-iraq-war":{"name":"Iran–Iraq War","country":"IQ","kind":"conflict","year":1980,"description":"Saddam Hussein invaded revolutionary Iran expecting a quick win and got eight years of trench warfare, poison gas and perhaps half a million dead — borders ending where they began.","image":"/events/iran-iraq-war.webp","credit":"Mahmoud Badrfar","license":"GFDL"},"falklands-war":{"name":"Falklands War","country":"AR","kind":"conflict","year":1982,"description":"Argentina's junta seized the Falkland Islands and Britain took them back in a ten-week war fought 13,000 kilometres from home. Defeat brought down the junta within a year.","image":"/events/falklands-war.webp"},"bhopal-disaster":{"name":"Bhopal disaster","country":"IN","kind":"disaster","year":1984,"description":"A Union Carbide pesticide plant leaked toxic gas over sleeping Bhopal, killing thousands within days and injuring hundreds of thousands — the world's deadliest industrial disaster.","image":"/events/bhopal-disaster.webp","credit":"Bhopal Medical Appeal, Martin Stott","license":"CC BY-SA 2.0"},"live-aid":{"name":"Live Aid","country":"GB","kind":"culture","year":1985,"description":"Twin concerts at Wembley and Philadelphia — sixteen hours, broadcast to well over a billion people — raised over £100 million for Ethiopia's famine. Queen's twenty minutes became rock legend.","image":"/events/live-aid.webp","credit":"Squelle","license":"CC BY-SA 3.0"},"1985-mexico-city-earthquake":{"name":"An earthquake collapses Mexico City","country":"MX","kind":"disaster","year":1985,"description":"A magnitude-8 earthquake collapsed hundreds of buildings in Mexico City, killing at least ten thousand people. Citizen rescue brigades, organised where the state failed, reshaped Mexican civil society.","image":"/events/1985-mexico-city-earthquake.webp","credit":"United States Geological Survey","license":"Public domain"},"chernobyl-disaster":{"name":"Chernobyl disaster","country":"UA","kind":"disaster","year":1986,"description":"Reactor 4 exploded during a botched safety test, spreading fallout across Europe while Moscow stayed silent for days. Gorbachev later called it a true cause of the Soviet collapse.","image":"/events/chernobyl-disaster.webp","credit":"IAEA Imagebank","license":"CC BY-SA 2.0"},"space-shuttle-challenger-disaster":{"name":"Space Shuttle Challenger disaster","country":"US","kind":"disaster","year":1986,"description":"Challenger broke apart 73 seconds after liftoff, killing all seven aboard — including the teacher Christa McAuliffe, with schoolchildren across America watching live. A frozen rubber O-ring was to blame.","image":"/events/space-shuttle-challenger-disaster.webp","credit":"Kennedy Space Center","license":"Public domain"},"people-power-revolution":{"name":"People Power Revolution","country":"PH","kind":"revolution","year":1986,"description":"Millions of Filipinos filled Manila's EDSA highway, nuns kneeling in front of tanks, until Ferdinand Marcos fled after a stolen election. Corazon Aquino — a slain rival's widow — became president.","image":"/events/people-power-revolution.webp"},"world-wide-web":{"name":"The World Wide Web is invented","country":"CH","kind":"science","year":1989,"description":"At CERN, Tim Berners-Lee proposed a hypertext system for sharing physics papers; his manager pencilled \"vague, but exciting\". He gave the Web away patent-free.","image":"/events/world-wide-web.webp","credit":"Ck_mpk","license":"Public domain"},"baltic-way":{"name":"Two million join hands across the Baltics","country":"LT","kind":"revolution","year":1989,"description":"Some two million Estonians, Latvians and Lithuanians joined hands in an unbroken 675-kilometre chain to demand independence, fifty years to the day after the pact that had handed them to Stalin.","image":"/events/baltic-way.webp","credit":"Kusurija","license":"CC BY-SA 3.0"},"1989-tiananmen-square-protests-and-massacre":{"name":"Tiananmen Square","country":"CN","kind":"revolution","year":1989,"description":"Weeks of student-led protests for reform filled Tiananmen Square until the army cleared Beijing with tanks and live fire, killing hundreds at least. The lone \"Tank Man\" photo endures where the count is censored.","image":"/events/1989-tiananmen-square-protests-and-massacre.webp"},"fall-of-the-berlin-wall":{"name":"Fall of the Berlin Wall","country":"DE","kind":"revolution","year":1989,"description":"A fumbled press conference answer — travel is free, \"immediately, without delay\" — sent East Berliners to the checkpoints that night, and the guards stood aside. The Cold War's symbol fell to hands and hammers.","image":"/events/fall-of-the-berlin-wall.webp","credit":"Sue Ream, photographer (San Francisco, California)","license":"CC BY 3.0"},"velvet-revolution":{"name":"Velvet Revolution","country":"CZ","kind":"revolution","year":1989,"description":"Ten days of swelling, entirely peaceful protests ended communist rule in Czechoslovakia. By the year's end the dissident playwright Václav Havel — in prison that spring — was president.","image":"/events/velvet-revolution.webp","credit":"RobbieIanMorrison","license":"CC BY 4.0"},"romanian-revolution":{"name":"Romanian Revolution","country":"RO","kind":"revolution","year":1989,"description":"The only violent fall in Eastern Europe's year of revolutions: a week of fighting ended with the Ceaușescus tried by a drumhead court and shot on Christmas Day.","image":"/events/romanian-revolution.webp","credit":"Not credited","license":"Attribution"},"1995-rugby-world-cup":{"name":"The Rainbow Nation wins the Rugby World Cup","country":"ZA","kind":"culture","year":1995,"description":"A year into democracy, South Africa hosted the tournament and won it — and Nelson Mandela handed François Pienaar the trophy wearing the Springboks' jersey, apartheid's old symbol turned unifier.","image":"/events/1995-rugby-world-cup.webp","credit":"Roman.b","license":"FAL"},"german-reunification":{"name":"German reunification","country":"DE","kind":"nation","year":1990,"description":"Less than a year after the Wall fell, East Germany's five states acceded to the Federal Republic and Germany was one country again — 3 October is now its national day.","image":"/events/german-reunification.webp","credit":"Peer Grimm","license":"CC BY-SA 3.0 de"},"independence-of-namibia":{"name":"Namibia becomes independent","country":"NA","kind":"nation","year":1990,"description":"Africa's last colony became independent from South African rule after a decades-long liberation war and a UN-supervised transition — one of the closing acts of both empire and Cold War.","image":"/events/independence-of-namibia.webp"},"hubble-space-telescope":{"name":"Hubble is launched","country":"US","kind":"science","year":1990,"description":"The first great space telescope launched with a flawed mirror — corrected by spacewalking astronauts three years later. Its deep-field images showed thousands of galaxies in a patch of \"empty\" sky.","image":"/events/hubble-space-telescope.webp","credit":"NASA","license":"Public domain"},"gulf-war":{"name":"Iraq invades Kuwait — the Gulf War","country":"KW","kind":"conflict","year":1990,"description":"Saddam Hussein swallowed Kuwait in a day; a 35-nation coalition threw him out in a six-week air war and a hundred-hour ground campaign, watched live on satellite news.","image":"/events/gulf-war.webp","credit":"US Air Force","license":"Public domain"},"croatian-war-of-independence":{"name":"Yugoslavia begins to break apart","country":"HR","kind":"conflict","year":1991,"description":"Croatia's declaration of independence brought war with the Yugoslav army and Serb militias — the siege of Vukovar, the shelling of Dubrovnik — as the federation tore apart piece by piece.","image":"/events/croatian-war-of-independence.webp","license":"CC BY-SA 3.0"},"dissolution-of-the-soviet-union":{"name":"Dissolution of the Soviet Union","country":"RU","kind":"nation","year":1991,"description":"After a failed hardline coup, the republics walked away and Gorbachev resigned on Christmas Day as the red flag came down from the Kremlin. Fifteen states stood where the superpower had been.","image":"/events/dissolution-of-the-soviet-union.webp","credit":"Yuriy Kuydin / Юрий Куйдин","license":"CC BY-SA 3.0"},"maastricht-treaty":{"name":"The European Union is created","country":"NL","kind":"politics","year":1992,"description":"Signed in the Dutch city of Maastricht, the treaty turned the Community into the European Union, created EU citizenship and set the path to a single currency.","image":"/events/maastricht-treaty.webp","credit":"User:Mateus2019","license":"CC BY 2.0 de"},"dissolution-of-czechoslovakia":{"name":"The Velvet Divorce","country":"SK","kind":"nation","year":1993,"description":"Czechoslovakia split into the Czech Republic and Slovakia at midnight on New Year's Eve — negotiated by two prime ministers, without a referendum and without a shot.","image":"/events/dissolution-of-czechoslovakia.webp"},"oslo-i-accord":{"name":"The Oslo Accords","country":"IL","kind":"politics","year":1993,"description":"Negotiated secretly in Norway and sealed with a Rabin–Arafat handshake on the White House lawn, the accords brought mutual recognition and Palestinian self-rule in parts of the territories — but no final peace.","image":"/events/oslo-i-accord.webp","credit":"Vince Musi / The White House","license":"Public domain"},"independence-of-eritrea":{"name":"Eritrea becomes independent","country":"ER","kind":"nation","year":1993,"description":"After a thirty-year war against Ethiopia — Africa's longest independence struggle — Eritreans voted almost unanimously for statehood in a UN-supervised referendum.","image":"/events/independence-of-eritrea.webp"},"rwandan-genocide":{"name":"Rwandan genocide","country":"RW","kind":"conflict","year":1994,"description":"In roughly one hundred days, Hutu extremists murdered around 800,000 Tutsi and moderate Hutu — much of it by machete, neighbour against neighbour — while the world declined to intervene.","image":"/events/rwandan-genocide.webp","credit":"Fanny Schertzer","license":"CC BY-SA 3.0"},"1994-south-african-general-election":{"name":"Apartheid ends at the ballot box","country":"ZA","kind":"nation","year":1994,"description":"South Africans of all races voted together for the first time, queueing for hours in lines visible from the air. Nelson Mandela was inaugurated president two weeks later.","image":"/events/1994-south-african-general-election.webp"},"channel-tunnel":{"name":"The Channel Tunnel opens","country":"GB","kind":"engineering","year":1994,"description":"Two centuries after the idea was first floated, a 50-kilometre rail tunnel — 38 of them under the seabed — joined Britain to the European mainland for the first time since the Ice Age.","image":"/events/channel-tunnel.webp","credit":"Billy69150 (voir les conditions d'utilisation / see licensing below)","license":"CC BY-SA 4.0"},"dayton-agreement":{"name":"The Bosnian War ends at Dayton","country":"BA","kind":"politics","year":1995,"description":"Three years of siege and ethnic cleansing — including genocide at Srebrenica that summer — ended with a peace hammered out at a US airbase in Ohio, freezing Bosnia into two entities under one roof.","image":"/events/dayton-agreement.webp","credit":"U.S. Air Force/Staff Sgt. Brian Schlumbohm","license":"Public domain"},"dolly-the-sheep":{"name":"Dolly the sheep is cloned","country":"GB","kind":"science","year":1996,"description":"Scientists near Edinburgh cloned a sheep from a single adult udder cell — the first cloned mammal, named after Dolly Parton for exactly the reason you suspect.","image":"/events/dolly-the-sheep.webp","credit":"Toni Barros from São Paulo, Brasil","license":"CC BY-SA 2.0"},"handover-of-hong-kong":{"name":"Handover of Hong Kong","country":"CN","kind":"politics","year":1997,"description":"Britain returned Hong Kong to China at midnight in a rain-soaked ceremony, ending 156 years of colonial rule under a promise of \"one country, two systems\" for fifty years.","image":"/events/handover-of-hong-kong.webp","credit":"Dan Lundberg","license":"CC BY-SA 2.0"},"1997-asian-financial-crisis":{"name":"The Asian financial crisis breaks the tigers","country":"TH","kind":"disaster","year":1997,"description":"Thailand's forced float of the baht set off a contagion that crashed currencies and economies from Jakarta to Seoul, humbling the \"Asian tigers\" and toppling Indonesia's Suharto.","image":"/events/1997-asian-financial-crisis.webp","license":"Public domain"},"good-friday-agreement":{"name":"Good Friday Agreement","country":"GB","kind":"politics","year":1998,"description":"Signed in Belfast on Good Friday, the agreement largely ended thirty years of the Troubles — power-sharing, paramilitary disarmament, and an open border on the island of Ireland.","image":"/events/good-friday-agreement.webp"},"international-space-station":{"name":"The International Space Station begins","country":"US","kind":"science","year":1998,"description":"A Russian module launched from Baikonur and an American one joined it weeks later, beginning the largest structure ever assembled in space. It has been continuously inhabited for over two decades.","image":"/events/international-space-station.webp","credit":"NASA","license":"Public domain"},"euro":{"name":"The euro is born","country":"DE","kind":"politics","year":1999,"description":"Eleven EU countries locked their currencies into the euro; notes and coins followed three years later, retiring the franc, mark, lira and peseta. It is now money for over 340 million people.","image":"/events/euro.webp"},"torrijos-carter-treaties":{"name":"America promises the canal to Panama","country":"PA","kind":"politics","year":1977,"description":"Carter and Panama's Torrijos signed the treaties returning the canal — the handover itself came at noon on the last day of 1999, ending nearly a century of American control.","image":"/events/torrijos-carter-treaties.webp","credit":"White House photo","license":"Public domain"},"september-11-attacks":{"name":"September 11 attacks","country":"US","kind":"conflict","year":2001,"description":"Al-Qaeda hijackers flew airliners into the World Trade Center and the Pentagon, killing nearly 3,000 people. The wars that answered it ran for two decades.","image":"/events/september-11-attacks.webp","credit":"Robert on Flickr","license":"CC BY-SA 2.0"},"wikipedia":{"name":"Wikipedia launches","country":"US","kind":"culture","year":2001,"description":"An encyclopedia anyone could edit sounded like a joke and became one of the most visited sites on Earth — millions of articles in hundreds of languages, written free by volunteers.","image":"/events/wikipedia.webp","credit":"最終編集","license":"CC BY-SA 4.0"},"east-timor":{"name":"East Timor becomes independent","country":"TL","kind":"nation","year":2002,"description":"The first new state of the century rose from a quarter-century of brutal Indonesian occupation and a UN-run transition, after its people voted overwhelmingly for freedom in a UN ballot.","image":"/events/east-timor.webp"},"iraq-war":{"name":"Iraq War","country":"IQ","kind":"conflict","year":2003,"description":"A US-led coalition invaded to seize weapons of mass destruction that were never found. Saddam fell in three weeks; the insurgency and civil war that followed lasted years.","image":"/events/iraq-war.webp","credit":"Technical Sergeant John L. Houghton, Jr., United States Air Force","license":"Public domain"},"human-genome-project":{"name":"The human genome is sequenced","country":"US","kind":"science","year":2003,"description":"The thirteen-year international project to read all three billion letters of human DNA was declared complete — the book of the species, open source.","image":"/events/human-genome-project.webp","credit":"U.S. Department of Energy, Human Genome Project","license":"Public domain"},"2004-indian-ocean-earthquake-and-tsunami":{"name":"A tsunami crosses the Indian Ocean","country":"ID","kind":"disaster","year":2004,"description":"A magnitude-9 earthquake off Sumatra sent tsunamis across the whole ocean, killing some 230,000 people in fourteen countries on a single morning — many with no warning at all.","image":"/events/2004-indian-ocean-earthquake-and-tsunami.webp","credit":"David Rydevik (email: david.rydevikgmail.com), Stockholm, Sweden.","license":"Public domain"},"2004-enlargement-of-the-european-union":{"name":"The EU takes in ten new members","country":"PL","kind":"politics","year":2004,"description":"Ten countries — eight of them from behind the old Iron Curtain — joined the EU in its largest single expansion, stitching the continent's Cold War halves together.","image":"/events/2004-enlargement-of-the-european-union.webp","license":"Public domain"},"orange-revolution":{"name":"Orange Revolution","country":"UA","kind":"revolution","year":2004,"description":"A rigged presidential run-off brought hundreds of thousands into a frozen Kyiv's Independence Square for weeks, until the courts ordered a re-vote — which the opposition won.","image":"/events/orange-revolution.webp","credit":"Serhiy","license":"CC BY-SA 3.0"},"hurricane-katrina":{"name":"Hurricane Katrina","country":"US","kind":"disaster","year":2005,"description":"Katrina's surge broke New Orleans' levees and drowned four-fifths of the city. Some 1,400 died, and the images of Americans stranded on rooftops indicted every level of government.","image":"/events/hurricane-katrina.webp","credit":"NASA","license":"Public domain"},"2006-montenegrin-independence-referendum":{"name":"Montenegro votes for independence","country":"ME","kind":"nation","year":2006,"description":"Montenegro voted to leave its union with Serbia — clearing the 55% bar by half a point — and the last piece of the old Yugoslavia went its own way.","image":"/events/2006-montenegrin-independence-referendum.webp","credit":"User:Terfili","license":"Public domain"},"iphone-1st-generation":{"name":"The iPhone arrives","country":"US","kind":"culture","year":2007,"description":"Steve Jobs introduced \"an iPod, a phone and an internet communicator\" — one device. The smartphone it defined put the internet in most of humanity's pockets within a decade.","image":"/events/iphone-1st-generation.webp"},"2008-kosovo-declaration-of-independence":{"name":"Kosovo declares independence","country":"XK","kind":"nation","year":2008,"description":"Nine years after the NATO intervention, Kosovo's assembly declared independence from Serbia. About half the world's states recognise it; Serbia and Russia do not.","image":"/events/2008-kosovo-declaration-of-independence.webp","credit":"Ensar.koshi","license":"CC BY-SA 3.0"},"bankruptcy-of-lehman-brothers":{"name":"Lehman falls — the global financial crisis","country":"US","kind":"disaster","year":2008,"description":"The 158-year-old investment bank filed the largest bankruptcy in US history and the global financial system seized. The Great Recession that followed cost millions their homes and jobs.","image":"/events/bankruptcy-of-lehman-brothers.webp","credit":"David Shankbone","license":"CC BY-SA 3.0"},"russo-georgian-war":{"name":"Russo-Georgian War","country":"GE","kind":"conflict","year":2008,"description":"A five-day August war over South Ossetia ended with Russian troops deep in Georgia and two breakaway regions under de facto Russian control — Europe's first invasion of the century.","image":"/events/russo-georgian-war.webp","credit":"Yana Amelina (Амелина Я. А.)","license":"CC BY-SA 3.0"},"first-inauguration-of-barack-obama":{"name":"America inaugurates its first Black president","country":"US","kind":"politics","year":2009,"description":"Barack Obama took the oath before a record crowd on the National Mall, 45 years after the March on Washington filled the same ground.","image":"/events/first-inauguration-of-barack-obama.webp","credit":"Master Sgt. Cecilio Ricardo, U.S. Air Force","license":"Public domain"},"2010-haiti-earthquake":{"name":"An earthquake devastates Port-au-Prince","country":"HT","kind":"disaster","year":2010,"description":"A magnitude-7 earthquake struck just outside Port-au-Prince, killing well over 100,000 people and flattening much of the capital of the hemisphere's poorest country.","image":"/events/2010-haiti-earthquake.webp","credit":"Trocaire from Ireland","license":"CC BY 2.0"},"burj-khalifa":{"name":"The Burj Khalifa opens","country":"AE","kind":"engineering","year":2010,"description":"Dubai opened the tallest structure humans have ever built — 828 metres, nearly twice the old record holder Taipei 101 — renamed at the last minute for the Abu Dhabi ruler whose bailout saved it.","image":"/events/burj-khalifa.webp","credit":"Tim.Reckmann","license":"CC BY-SA 3.0"},"tunisian-revolution":{"name":"The Arab Spring begins in Tunisia","country":"TN","kind":"revolution","year":2010,"description":"A street vendor's self-immolation in a provincial town lit protests that drove out Tunisia's president in 28 days — and spread revolt across the Arab world within weeks.","image":"/events/tunisian-revolution.webp","credit":"M.Rais","license":"CC0"},"2011-tohoku-earthquake-and-tsunami":{"name":"The tsunami and Fukushima","country":"JP","kind":"disaster","year":2011,"description":"Japan's strongest recorded earthquake sent a tsunami over the sea walls, killing nearly 20,000 people and triggering meltdowns at the Fukushima Daiichi nuclear plant — the worst since Chernobyl.","image":"/events/2011-tohoku-earthquake-and-tsunami.webp","credit":"U.S. Navy photo","license":"Public domain"},"independence-of-south-sudan":{"name":"South Sudan — the world's newest country","country":"SS","kind":"nation","year":2011,"description":"After decades of civil war and a near-unanimous referendum, South Sudan became the world's newest country. Civil war within it followed two years later.","image":"/events/independence-of-south-sudan.webp"},"syrian-civil-war":{"name":"Syrian civil war","country":"SY","kind":"conflict","year":2011,"description":"The Arab Spring's Syrian protests met bullets and spiralled into a war that has killed hundreds of thousands and displaced half the country — the largest refugee crisis of the era.","image":"/events/syrian-civil-war.webp"},"higgs-boson":{"name":"The Higgs boson is found","country":"CH","kind":"science","year":2012,"description":"CERN's Large Hadron Collider found the particle predicted 48 years earlier to explain why matter has mass. Peter Higgs, in the audience, wiped away tears; the Nobel came the next year.","image":"/events/higgs-boson.webp","credit":"Lucas Taylor / CERN","license":"CC BY-SA 3.0"},"2013-papal-conclave":{"name":"The first pope from the Americas","country":"VA","kind":"culture","year":2013,"description":"After the first papal resignation in six centuries, the conclave chose Buenos Aires's Jorge Bergoglio — the first pope from the Americas, the southern hemisphere, or the Jesuits. He took the name Francis.","image":"/events/2013-papal-conclave.webp","credit":"Casa Rosada","license":"CC BY-SA 2.0"},"annexation-of-crimea-by-the-russian-federation":{"name":"Russia annexes Crimea","country":"UA","kind":"conflict","year":2014,"description":"Unmarked Russian troops — the \"little green men\" — seized Crimea weeks after Ukraine's revolution, and Moscow annexed it after a referendum recognised almost nowhere. Europe's borders had been redrawn by force.","image":"/events/annexation-of-crimea-by-the-russian-federation.webp"},"western-african-ebola-virus-epidemic":{"name":"The West African Ebola epidemic","country":"GN","kind":"disaster","year":2014,"description":"From a single village in Guinea, Ebola spread through Liberia and Sierra Leone in the worst outbreak of the disease ever — over 11,000 dead before it was contained.","image":"/events/western-african-ebola-virus-epidemic.webp"},"paris-agreement":{"name":"Paris Agreement","country":"FR","kind":"politics","year":2015,"description":"Nearly every nation on Earth agreed in Paris to keep global warming well below 2°C. Delegates wept and cheered when the gavel fell — the treaty's test has been every year since.","image":"/events/paris-agreement.webp"},"2016-united-kingdom-european-union-membership-referendum":{"name":"Brexit — Britain votes to leave","country":"GB","kind":"politics","year":2016,"description":"Britain voted 52–48 to leave the European Union, the first member ever to go. The prime minister resigned the next morning; the leaving took four and a half more years.","image":"/events/2016-united-kingdom-european-union-membership-referendum.webp","credit":"The Electoral Commission","license":"Public domain"},"colombian-peace-agreement":{"name":"Colombia signs peace with the FARC","country":"CO","kind":"politics","year":2016,"description":"The government and the FARC guerrillas signed an end to the western hemisphere's longest war — half a century, 260,000 dead. Voters rejected the first draft; a revised deal passed weeks later.","image":"/events/colombian-peace-agreement.webp"},"notre-dame-fire":{"name":"Notre-Dame burns","country":"FR","kind":"disaster","year":2019,"description":"Fire took the roof and spire of the 850-year-old cathedral as Paris watched from the bridges, singing hymns. The towers and the rose windows survived; it reopened five years later.","image":"/events/notre-dame-fire.webp","credit":"LeLaisserPasserA38","license":"CC BY-SA 4.0"},"covid-19-pandemic":{"name":"COVID-19 pandemic","country":"CN","kind":"disaster","year":2020,"description":"A novel coronavirus first reported in Wuhan closed borders, schools and cities across the planet within months — millions dead, and vaccines developed at record speed inside a year.","image":"/events/covid-19-pandemic.webp","credit":"Gustavo Basso","license":"CC BY-SA 4.0"},"2020-beirut-explosion":{"name":"The Beirut port explosion","country":"LB","kind":"disaster","year":2020,"description":"Some 2,750 tonnes of ammonium nitrate, stored for six years in a port warehouse, detonated in one of the largest non-nuclear blasts ever recorded — over 200 dead and 300,000 homeless in seconds.","image":"/events/2020-beirut-explosion.webp","credit":"Mahdi Shojaeian","license":"CC BY 4.0"},"fall-of-kabul":{"name":"The Taliban retake Kabul","country":"AF","kind":"conflict","year":2021,"description":"As the twenty-year Western mission ended, the Afghan government collapsed in days and the Taliban entered Kabul without a fight. The desperate airlift from the airport closed America's longest war.","image":"/events/fall-of-kabul.webp","credit":"VOA","license":"Public domain"},"james-webb-space-telescope":{"name":"The James Webb Space Telescope launches","country":"US","kind":"science","year":2021,"description":"The long-delayed successor to Hubble launched on Christmas Day and unfolded itself perfectly a million miles out. Its infrared eyes see the first galaxies forming.","image":"/events/james-webb-space-telescope.webp","credit":"NASA","license":"Public domain"},"russian-invasion-of-ukraine":{"name":"Russian invasion of Ukraine","country":"UA","kind":"conflict","year":2022,"description":"Russia launched a full-scale invasion of Ukraine from the north, east and south, expecting Kyiv to fall in days. It did not — and Europe's largest war since 1945 began.","image":"/events/russian-invasion-of-ukraine.webp","credit":"Arrikel","license":"CC BY-SA 4.0"},"death-and-state-funeral-of-elizabeth-ii":{"name":"Elizabeth II dies","country":"GB","kind":"culture","year":2022,"description":"Britain's longest-reigning monarch died at Balmoral after seventy years on the throne. The queue to pass her coffin in Westminster Hall ran for kilometres along the Thames, day and night.","image":"/events/death-and-state-funeral-of-elizabeth-ii.webp"},"2022-fifa-world-cup":{"name":"The Qatar World Cup final","country":"QA","kind":"culture","year":2022,"description":"The first World Cup in the Arab world, played in winter, ended with what many call the greatest final ever — Messi's Argentina beating Mbappé's France on penalties after 3–3.","image":"/events/2022-fifa-world-cup.webp"},"2023-turkey-syria-earthquakes":{"name":"Earthquakes flatten cities across Türkiye and Syria","country":"TR","kind":"disaster","year":2023,"description":"Two huge earthquakes hours apart flattened cities across southern Türkiye and northern Syria in the winter cold, killing nearly 60,000 people — Türkiye's worst disaster of the modern era.","image":"/events/2023-turkey-syria-earthquakes.webp","credit":"Adem","license":"CC BY-SA 4.0"},"1990-mongolian-revolution":{"name":"Mongolia turns democratic","country":"MN","kind":"revolution","year":1990,"description":"Hunger strikes and mass protests in freezing Ulaanbaatar persuaded the communist politburo to resign en masse — a peaceful exit, and Asia's first post-Soviet democracy.","image":"/events/1990-mongolian-revolution.webp","credit":"Монгол Улсын Их Хурал","license":"CC BY 4.0"},"kyoto-protocol":{"name":"Kyoto Protocol","country":"JP","kind":"politics","year":1997,"description":"The first treaty binding industrialised countries to cut greenhouse-gas emissions was adopted in Kyoto — the ancestor, through years of argument, of the Paris Agreement.","image":"/events/kyoto-protocol.webp"},"battle-of-zama":{"name":"Rome breaks Carthage at Zama","country":"TN","kind":"conflict","year":-202,"description":"Scipio defeated Hannibal himself on Carthage's home ground, ending the Second Punic War. Rome never again faced a rival for the western Mediterranean.","image":"/events/battle-of-zama.webp","credit":"anonymous","license":"Public domain"},"battle-of-the-teutoburg-forest":{"name":"Battle of the Teutoburg Forest","country":"DE","kind":"conflict","year":9,"description":"Germanic tribes under Arminius annihilated three Roman legions in the forests east of the Rhine. Rome kept the river as its frontier for the next four centuries.","image":"/events/battle-of-the-teutoburg-forest.webp"},"plague-of-justinian":{"name":"Plague of Justinian","country":"TR","kind":"disaster","year":541,"description":"The first recorded plague pandemic reached Constantinople along the grain routes and hollowed out Justinian's empire — a rehearsal, eight centuries early, for the Black Death.","image":"/events/plague-of-justinian.webp","credit":"Josse Lieferinxe","license":"Public domain"},"battle-of-tours":{"name":"Battle of Tours","country":"FR","kind":"conflict","year":732,"description":"Charles Martel's Franks turned back an Umayyad raiding army between Tours and Poitiers — the high-water mark of the Arab advance into Western Europe.","image":"/events/battle-of-tours.webp","credit":"Charles de Steuben","license":"Public domain"},"baghdad":{"name":"Baghdad is founded","country":"IQ","kind":"nation","year":762,"description":"The Abbasid caliph al-Mansur laid out a brand-new round city on the Tigris. Within a century it was the largest city in the world and the heart of a golden age of learning.","image":"/events/baghdad.webp","credit":"Aurelio de Sandoval","license":"CC BY 3.0"},"treaty-of-verdun":{"name":"Charlemagne's empire is split in three","country":"FR","kind":"politics","year":843,"description":"Charlemagne's three grandsons partitioned his empire at Verdun. The western and eastern kingdoms it drew would grow, roughly, into France and Germany.","image":"/events/treaty-of-verdun.webp","credit":"AnonymousUnknown author","license":"Public domain"},"battle-of-manzikert":{"name":"Battle of Manzikert","country":"TR","kind":"conflict","year":1071,"description":"The Seljuk Turks captured the Byzantine emperor and broke his army in eastern Anatolia. The empire never recovered its heartland — and its call for help seeded the Crusades.","image":"/events/battle-of-manzikert.webp","credit":"Rohan Master","license":"Public domain"},"domesday-book":{"name":"Domesday Book","country":"GB","kind":"politics","year":1086,"description":"Twenty years after Hastings, William the Conqueror had every manor, mill and pig in England surveyed and written down — a census so final the English named it after Judgement Day.","image":"/events/domesday-book.webp","credit":"Andrews, William","license":"Public domain"},"siege-of-jerusalem-1187":{"name":"Saladin retakes Jerusalem","country":"IL","kind":"conflict","year":1187,"description":"After crushing the crusader army at Hattin, Saladin took Jerusalem back for Islam after 88 years — and, pointedly, without the massacre that had marked its capture.","image":"/events/siege-of-jerusalem-1187.webp","credit":"Alphonse de Neuville","license":"Public domain"},"sack-of-constantinople":{"name":"Crusaders sack Constantinople","country":"TR","kind":"conflict","year":1204,"description":"The Fourth Crusade never reached the Holy Land — diverted by debts and Venetian politics, it stormed and looted Christian Constantinople instead. Byzantium never truly recovered.","image":"/events/sack-of-constantinople.webp","credit":"Palma Le Jeune (1544–1620)","license":"Public domain"},"battle-of-ain-jalut":{"name":"The Mongol advance is stopped at Ain Jalut","country":"IL","kind":"conflict","year":1260,"description":"Egypt's Mamluks met the Mongols in Galilee and beat them — the first major defeat the Mongol Empire could not avenge, and the end of its westward expansion.","image":"/events/battle-of-ain-jalut.webp"},"battle-of-bannockburn":{"name":"Battle of Bannockburn","country":"GB","kind":"conflict","year":1314,"description":"Robert the Bruce's spearmen routed a far larger English army in the marshes below Stirling Castle, securing Scotland's independence for the next three centuries.","image":"/events/battle-of-bannockburn.webp","credit":"Edmund Blair Leighton","license":"Public domain"},"hundred-years-war":{"name":"The Hundred Years' War begins","country":"FR","kind":"conflict","year":1337,"description":"The English king's claim to the French crown opened a war that ran, with pauses, for 116 years — long enough to see knights give way to longbows and then to cannon.","image":"/events/hundred-years-war.webp","credit":"Loyset Liédet","license":"Public domain"},"battle-of-agincourt":{"name":"Battle of Agincourt","country":"FR","kind":"conflict","year":1415,"description":"Henry V's exhausted, outnumbered army destroyed the flower of French chivalry in the mud of Agincourt — the longbow's most famous hour, remembered ever after via Shakespeare.","image":"/events/battle-of-agincourt.webp","license":"Public domain"},"great-stand-on-the-ugra-river":{"name":"Russia faces down the Horde on the Ugra","country":"RU","kind":"conflict","year":1480,"description":"Ivan III's army faced the Great Horde across the Ugra river until the Horde simply turned for home — the bloodless moment counted as the end of two and a half centuries of Mongol overlordship.","image":"/events/great-stand-on-the-ugra-river.webp","license":"Public domain"},"safavid-iran":{"name":"The Safavids take Iran","country":"IR","kind":"nation","year":1501,"description":"The young Shah Ismail took Tabriz and founded the Safavid dynasty, making Shia Islam the state religion — the decision that still shapes Iran five centuries on.","image":"/events/safavid-iran.webp"},"mona-lisa":{"name":"Leonardo begins the Mona Lisa","country":"IT","kind":"culture","year":1503,"description":"Leonardo da Vinci began a portrait of a Florentine merchant's wife and kept refining it for years, carrying it with him to France — where it never left.","image":"/events/mona-lisa.webp","credit":"Leonardo da Vinci","license":"Public domain"},"sistine-chapel-ceiling":{"name":"Michelangelo begins the Sistine ceiling","country":"VA","kind":"culture","year":1508,"description":"Michelangelo — a sculptor, protesting he was no painter — spent four years on his back over the Sistine Chapel, and produced the most famous ceiling on Earth.","image":"/events/sistine-chapel-ceiling.webp","credit":"Michelangelo","license":"CC BY-SA 3.0"},"potosi":{"name":"Silver is struck at Potosí","country":"BO","kind":"culture","year":1545,"description":"A mountain of silver discovered in the high Andes became the largest source of wealth in the Spanish Empire — mined at a terrible cost in forced labour, and minting the world's first global currency.","image":"/events/potosi.webp","credit":"Parallelepiped09","license":"CC BY-SA 4.0"},"gregorian-calendar":{"name":"The Gregorian calendar is introduced","country":"VA","kind":"science","year":1582,"description":"Pope Gregory XIII deleted ten days from October to fix the drifting Julian calendar. Catholic Europe switched at once; Britain held out until 1752, Russia until 1918.","image":"/events/gregorian-calendar.webp"},"tulip-mania":{"name":"Tulip mania","country":"NL","kind":"culture","year":1637,"description":"At the peak of the Dutch tulip craze single bulbs traded for the price of a canal house — then the market collapsed in weeks. It remains the byword for a speculative bubble.","image":"/events/tulip-mania.webp","credit":"Unknown, 1637","license":"Public domain"},"battle-of-shanhai-pass":{"name":"The Qing take Beijing","country":"CN","kind":"conflict","year":1644,"description":"A Ming general opened the Great Wall's eastern gate to the Manchus, who swept in to claim a collapsing empire. Their Qing dynasty ruled China until 1912.","image":"/events/battle-of-shanhai-pass.webp"},"salem-witch-trials":{"name":"Salem witch trials","country":"US","kind":"culture","year":1692,"description":"A wave of accusations in a small Massachusetts town saw twenty people executed for witchcraft before the panic burned out — and became the permanent shorthand for one.","image":"/events/salem-witch-trials.webp","credit":"unattributed","license":"Public domain"},"seven-years-war":{"name":"The Seven Years' War begins","country":"DE","kind":"conflict","year":1756,"description":"Fought in Europe, the Americas, India and at sea, it has a claim to being the first world war. Britain emerged with Canada and India; France with the debts that fed its revolution.","image":"/events/seven-years-war.webp"},"constitution-of-the-united-states":{"name":"The US Constitution is signed","country":"US","kind":"politics","year":1787,"description":"A summer of closed-door argument in Philadelphia produced the oldest written national constitution still in force — beginning, boldly, \"We the People\".","image":"/events/constitution-of-the-united-states.webp","credit":"Constitutional Convention","license":"Public domain"},"louisiana-purchase":{"name":"Louisiana Purchase","country":"US","kind":"politics","year":1803,"description":"Napoleon, needing war money, sold France's vast Louisiana territory for $15 million. The United States doubled in size overnight at about three cents an acre.","image":"/events/louisiana-purchase.webp","credit":"Matysik","license":"CC0"},"second-voyage-of-hms-beagle":{"name":"The Beagle sails, Darwin aboard","country":"EC","kind":"science","year":1831,"description":"A five-year survey voyage carried the young Charles Darwin around South America and to the Galápagos Islands, whose finches and tortoises seeded the theory of evolution.","image":"/events/second-voyage-of-hms-beagle.webp","credit":"Conrad Martens (1801 - 21 August 1878)","license":"Public domain"},"battle-of-carabobo":{"name":"Venezuela wins its freedom at Carabobo","country":"VE","kind":"revolution","year":1821,"description":"Bolívar's decisive victory at Carabobo effectively ended Spanish rule in Venezuela — June 24 is still the army's day of days.","image":"/events/battle-of-carabobo.webp","license":"Public domain"},"view-from-the-window-at-le-gras":{"name":"The first photograph is taken","country":"FR","kind":"science","year":1826,"description":"Nicéphore Niépce pointed a pewter plate out of his workroom window in Burgundy and exposed it for hours — the oldest surviving photograph of the real world.","image":"/events/view-from-the-window-at-le-gras.webp","credit":"Nicéphore Niépce","license":"Public domain"},"neptune":{"name":"Neptune is discovered by mathematics","country":"DE","kind":"science","year":1846,"description":"Astronomers in Berlin found Neptune within a degree of where the Frenchman Le Verrier's calculations said an unseen planet must be — discovered by pen before telescope.","image":"/events/neptune.webp","credit":"NASA / Voyager 2 / PDS / OPUS / Ardenau4","license":"CC0"},"dynamite":{"name":"Nobel invents dynamite","country":"SE","kind":"science","year":1867,"description":"Alfred Nobel tamed nitroglycerine into a stable stick and made a fortune remaking mining, construction — and war. The prizes in his name were his answer to that legacy.","image":"/events/dynamite.webp","credit":"Olecrab","license":"CC BY 3.0"},"brooklyn-bridge":{"name":"The Brooklyn Bridge opens","country":"US","kind":"engineering","year":1883,"description":"The longest suspension bridge of its day crossed the East River on steel cables — finished by Emily Roebling, who ran the project after her engineer husband was paralysed.","image":"/events/brooklyn-bridge.webp","credit":"Christian David","license":"CC BY-SA 4.0"},"benz-patent-motorwagen":{"name":"Karl Benz patents the automobile","country":"DE","kind":"engineering","year":1886,"description":"Karl Benz patented a three-wheeled carriage driven by a petrol engine — the first true automobile. His wife Bertha made the first road trip in it, without telling him.","image":"/events/benz-patent-motorwagen.webp","credit":"DaimlerChrysler AG","license":"CC BY-SA 3.0"},"workers-leaving-the-lumiere-factory":{"name":"The Lumières screen the first films","country":"FR","kind":"culture","year":1895,"description":"The Lumière brothers filmed their own workers streaming out of the factory gates in Lyon and projected it to paying audiences — cinema's founding minute of footage.","image":"/events/workers-leaving-the-lumiere-factory.webp"},"radium":{"name":"The Curies discover radium","country":"FR","kind":"science","year":1898,"description":"Marie and Pierre Curie boiled down tonnes of pitchblende in a Paris shed to isolate a new, faintly glowing element. Marie became the first person to win two Nobel Prizes.","image":"/events/radium.webp","credit":"grenadier","license":"CC BY 3.0"},"1903-tour-de-france":{"name":"The first Tour de France","country":"FR","kind":"culture","year":1903,"description":"A newspaper circulation stunt sent sixty riders around France over 2,428 kilometres. The survivors made it the biggest annual sporting event on Earth.","image":"/events/1903-tour-de-france.webp","credit":"Jules Beau","license":"Public domain"},"annus-mirabilis-papers":{"name":"Einstein's miracle year","country":"CH","kind":"science","year":1905,"description":"In one year, a 26-year-old patent clerk in Bern published four papers — on light quanta, Brownian motion, special relativity and E=mc² — and physics was never the same.","image":"/events/annus-mirabilis-papers.webp","license":"Public domain"},"great-mosque-of-djenne":{"name":"The Great Mosque of Djenné is raised","country":"ML","kind":"engineering","year":1907,"description":"The largest mud-brick building in the world rose on the site of a 13th-century mosque in Mali. The whole town replasters it by hand at an annual festival.","image":"/events/great-mosque-of-djenne.webp","credit":"Andy Gilham","license":"CC BY-SA 3.0"},"ford-model-t":{"name":"The Model T rolls out","country":"US","kind":"engineering","year":1908,"description":"Ford's simple, rugged Model T — soon built on a moving assembly line that cut its price year after year — put the world's middle class on wheels. Half the cars on Earth were once Model Ts.","image":"/events/ford-model-t.webp","credit":"Jon Sullivan","license":"Public domain"},"african-national-congress":{"name":"The ANC is founded","country":"ZA","kind":"politics","year":1912,"description":"Chiefs, lawyers and churchmen met in Bloemfontein to resist the new Union of South Africa's colour bar — the movement that would, 82 years later, win the country's first free election.","image":"/events/african-national-congress.webp","credit":"Unknown photographer","license":"Public domain"},"balfour-declaration":{"name":"Balfour Declaration","country":"GB","kind":"politics","year":1917,"description":"A 67-word letter from Britain's foreign secretary promised support for \"a national home for the Jewish people\" in Palestine — a sentence whose consequences are still being argued.","image":"/events/balfour-declaration.webp","credit":"United Kingdom Government signed by Arthur Balfour","license":"Public domain"},"prohibition-in-the-united-states":{"name":"America goes dry","country":"US","kind":"politics","year":1920,"description":"The Eighteenth Amendment banned the making and selling of alcohol nationwide. Thirteen years of speakeasies and Al Capone later, it became the only amendment ever repealed.","image":"/events/prohibition-in-the-united-states.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"1924-winter-olympics":{"name":"The first Winter Olympics","country":"FR","kind":"culture","year":1924,"description":"Sixteen nations met at Chamonix under Mont Blanc for an \"International Winter Sports Week\" — retroactively crowned the first Winter Olympic Games.","image":"/events/1924-winter-olympics.webp","credit":"Auguste Couttet / BnF","license":"Public domain"},"spirit-of-st-louis":{"name":"Lindbergh flies the Atlantic alone","country":"US","kind":"science","year":1927,"description":"Charles Lindbergh flew 33½ hours from New York to Paris, alone and without radio, in a single-engine plane with a fuel tank where the windscreen should be. A crowd of 100,000 mobbed the field.","image":"/events/spirit-of-st-louis.webp","license":"CC BY-SA 3.0"},"hoover-dam":{"name":"The Hoover Dam is completed","country":"US","kind":"engineering","year":1936,"description":"A Depression mega-project higher than a 60-storey building corked the Colorado River, creating the largest reservoir in the United States and lighting the Southwest.","image":"/events/hoover-dam.webp","credit":"Christian David","license":"CC BY-SA 4.0"},"1936-summer-olympics":{"name":"Jesse Owens spoils Hitler's Olympics","country":"DE","kind":"culture","year":1936,"description":"The Nazis staged the Berlin Games as a showcase of Aryan supremacy — and the Black American sprinter Jesse Owens won four gold medals in front of them.","image":"/events/1936-summer-olympics.webp"},"winter-war":{"name":"Finland stands alone in the Winter War","country":"FI","kind":"conflict","year":1939,"description":"The Soviet Union invaded Finland expecting weeks; ski troops in white held the Red Army through a brutal winter for three and a half months. Finland lost territory but kept its independence.","image":"/events/winter-war.webp","credit":"Unknown author.","license":"Public domain"},"warsaw-ghetto-uprising":{"name":"Warsaw Ghetto Uprising","country":"PL","kind":"conflict","year":1943,"description":"Facing final deportation to the death camps, the young Jews of the Warsaw Ghetto fought the SS with smuggled pistols and petrol bombs for nearly a month — the largest Jewish revolt of the Holocaust.","image":"/events/warsaw-ghetto-uprising.webp","license":"Public domain"},"colossus-computer":{"name":"Colossus — the first electronic computer","country":"GB","kind":"science","year":1943,"description":"Built in secret at Bletchley Park to break German cipher traffic, Colossus was the first programmable electronic digital computer. Churchill ordered it smashed after the war; the secret held for 30 years.","image":"/events/colossus-computer.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"eniac":{"name":"ENIAC is unveiled","country":"US","kind":"science","year":1946,"description":"Thirty tonnes and 18,000 vacuum tubes, built for artillery tables — the first general-purpose electronic computer, programmed by six women history took decades to credit.","image":"/events/eniac.webp","credit":"Unidentified U.S. Army photographer","license":"Public domain"},"the-diary-of-a-young-girl":{"name":"Anne Frank's diary is published","country":"NL","kind":"culture","year":1947,"description":"Two years after Anne Frank died in Bergen-Belsen at fifteen, her father published the diary she kept in the Amsterdam hiding place. It has been read in some seventy languages.","image":"/events/the-diary-of-a-young-girl.webp","credit":"Gonzalort1","license":"CC BY-SA 3.0"},"kon-tiki-expedition":{"name":"Kon-Tiki crosses the Pacific","country":"NO","kind":"science","year":1947,"description":"Thor Heyerdahl and five companions drifted 8,000 kilometres from Peru to Polynesia on a balsa-wood raft to prove such a voyage was possible. Science disagreed; the world was enchanted.","image":"/events/kon-tiki-expedition.webp","credit":"Kon-Tiki Museet - link","license":"CC BY 3.0"},"dominion-of-ceylon":{"name":"Ceylon becomes independent","country":"LK","kind":"nation","year":1948,"description":"The island of Ceylon took independence from Britain in the same post-war wave as India and Burma, and in 1972 renamed itself Sri Lanka.","image":"/events/dominion-of-ceylon.webp","credit":"Zscout370","license":"Public domain"},"myanmar":{"name":"Burma becomes independent","country":"MM","kind":"nation","year":1948,"description":"Burma left the British Empire outright — declining even Commonwealth membership — months after independence hero Aung San was assassinated with most of his cabinet.","image":"/events/myanmar.webp","credit":"Wine Su11","license":"CC BY-SA 4.0"},"cambodia":{"name":"Cambodia becomes independent","country":"KH","kind":"nation","year":1953,"description":"King Norodom Sihanouk talked France out of its protectorate without a war — his self-styled 'royal crusade for independence'.","image":"/events/cambodia.webp","credit":"Manfred Werner (talk · contribs)","license":"CC BY-SA 3.0"},"mau-mau-rebellion":{"name":"The Mau Mau uprising begins","country":"KE","kind":"revolution","year":1952,"description":"A land-and-freedom revolt among the Kikuyu drove Britain to declare an eight-year emergency in Kenya, detaining tens of thousands in camps. Independence followed within a decade.","image":"/events/mau-mau-rebellion.webp","credit":"Ministry of Defence POST-1945 OFFICIAL COLLECTION","license":"Public domain"},"eurovision-song-contest-1956":{"name":"The first Eurovision Song Contest","country":"CH","kind":"culture","year":1956,"description":"Seven countries sent songs to a Swiss casino theatre in a television experiment for the new European Broadcasting Union. The host nation won; the contest never stopped growing.","image":"/events/eurovision-song-contest-1956.webp"},"laser":{"name":"The first laser fires","country":"US","kind":"science","year":1960,"description":"Theodore Maiman coaxed a synthetic ruby into emitting the first laser light — a solution famously 'looking for a problem' that ended up in everything from surgery to supermarkets.","image":"/events/laser.webp","credit":"彭嘉傑","license":"CC BY 2.5"},"the-beatles":{"name":"The Beatles form in Liverpool","country":"GB","kind":"culture","year":1960,"description":"Four Liverpool teenagers settled on a name and went to play the Hamburg clubs. Within four years they were the biggest band on Earth; popular music still lives in their wake.","image":"/events/the-beatles.webp","credit":"Dezo Hoffmann, Distributed by Capitol Records","license":"Public domain"},"vostok-6":{"name":"The first woman in space","country":"RU","kind":"science","year":1963,"description":"Valentina Tereshkova, a 26-year-old former textile worker and amateur parachutist, orbited the Earth 48 times — more than every American astronaut to that date combined.","image":"/events/vostok-6.webp","credit":"Alexander Mokletsov / Александр Моклецов","license":"CC BY-SA 3.0"},"tokaido-shinkansen":{"name":"The bullet train debuts","country":"JP","kind":"engineering","year":1964,"description":"Nine days before the Tokyo Olympics opened, the first Shinkansen slid out for Osaka at 210 km/h — the fastest railway on Earth, in a country written off as war-broken twenty years before.","image":"/events/tokaido-shinkansen.webp","credit":"MaedaAkihiko","license":"CC BY-SA 4.0"},"boeing-747":{"name":"The 747 takes flight","country":"US","kind":"engineering","year":1969,"description":"The first jumbo jet — two and a half times bigger than anything before it — made flying cheap enough for ordinary families. It kept the \"Queen of the Skies\" title for half a century.","image":"/events/boeing-747.webp","credit":"Iberia Airlines","license":"CC BY 2.0"},"intel-4004":{"name":"The first microprocessor","country":"US","kind":"science","year":1971,"description":"Intel squeezed a computer's entire processor onto one fingernail-sized chip, built for a Japanese calculator. Everything with a brain today descends from that bargain.","image":"/events/intel-4004.webp","credit":"the Science Museum","license":"CC BY 4.0"},"watergate-scandal":{"name":"The Watergate break-in","country":"US","kind":"politics","year":1972,"description":"A bungled burglary at the Democratic headquarters unravelled, over two years of reporting and tapes, into the only resignation of a US president.","image":"/events/watergate-scandal.webp","credit":"Farragutful","license":"CC BY-SA 3.0"},"rubik-s-cube":{"name":"Rubik's Cube is invented","country":"HU","kind":"culture","year":1974,"description":"A Budapest architecture lecturer built a twisting cube to teach spatial thinking — then spent a month working out how to solve his own puzzle. It became the best-selling toy in history.","image":"/events/rubik-s-cube.webp"},"apple-inc":{"name":"Apple is founded in a garage","country":"US","kind":"culture","year":1976,"description":"Two Steves — Jobs selling, Wozniak soldering — founded a computer company in a Silicon Valley garage on April Fools' Day. It became the most valuable company in the world.","image":"/events/apple-inc.webp","credit":"Arne Müseler","license":"CC BY-SA 3.0 de"},"star-wars":{"name":"Star Wars opens","country":"US","kind":"culture","year":1977,"description":"A space fantasy the studio barely believed in opened in 32 cinemas and rewired popular culture — the blockbuster, the franchise and the summer movie all date from it.","image":"/events/star-wars.webp","credit":"File by User:KAMiKAZOW, original logo by Suzy Rice","license":"Public domain"},"premiership-of-margaret-thatcher":{"name":"Britain's first woman prime minister","country":"GB","kind":"politics","year":1979,"description":"Margaret Thatcher entered Downing Street as Britain's first female prime minister and held it for eleven years, remaking — and dividing — the country.","image":"/events/premiership-of-margaret-thatcher.webp","credit":"Israel Press and Photo Agency","license":"CC BY 4.0"},"walkman":{"name":"The Walkman starts the soundtrack age","country":"JP","kind":"culture","year":1979,"description":"Sony's pocket cassette player, built because a founder wanted opera on long flights, put private soundtracks into public space — the ancestor of every earbud on the street.","image":"/events/walkman.webp","credit":"Birmingham Museums Trust","license":"CC BY-SA 4.0"},"ibm-personal-computer":{"name":"The IBM PC arrives","country":"US","kind":"science","year":1981,"description":"IBM's rushed, open-parts personal computer became the standard everyone cloned — and made the fortune of the small company that supplied its operating system: Microsoft.","image":"/events/ibm-personal-computer.webp","credit":"Rama &amp; Musée Bolo","license":"CC BY-SA 2.0 fr"},"schengen-agreement":{"name":"Europe agrees to drop its borders","country":"LU","kind":"politics","year":1985,"description":"Five countries signed on a river boat moored at Schengen, a Luxembourg village where France and Germany meet, to abolish their border checks — passport-free travel now spans most of Europe.","image":"/events/schengen-agreement.webp","credit":"Zinneke","license":"CC BY-SA 3.0"},"1986-fifa-world-cup":{"name":"Maradona's World Cup","country":"MX","kind":"culture","year":1986,"description":"Mexico hosted at five weeks' notice after Colombia withdrew, and Diego Maradona decided the tournament almost alone — scoring the infamous \"Hand of God\" and the Goal of the Century four minutes apart.","image":"/events/1986-fifa-world-cup.webp","credit":"Carlo Fumagalli","license":"Public domain"},"libya":{"name":"Libya becomes independent","country":"LY","kind":"nation","year":1951,"description":"The first country created by the United Nations: the former Italian colony became an independent kingdom under King Idris, years before oil turned up beneath it.","image":"/events/libya.webp","credit":"Sanadalahlafi","license":"CC BY-SA 4.0"},"1954-guatemalan-coup-d-etat":{"name":"A CIA coup topples Guatemala's president","country":"GT","kind":"revolution","year":1954,"description":"The elected president Árbenz, whose land reform threatened the United Fruit Company, was overthrown in a CIA-organised coup — a template, and a warning, for the whole Cold War hemisphere.","image":"/events/1954-guatemalan-coup-d-etat.webp"},"sudan":{"name":"Sudan becomes independent","country":"SD","kind":"nation","year":1956,"description":"Africa's largest country left joint British-Egyptian rule on a New Year's Day — already carrying the north–south divide that would bring two long civil wars.","image":"/events/sudan.webp","credit":"walter callens","license":"CC BY 2.0"},"somalia":{"name":"Somalia becomes independent","country":"SO","kind":"nation","year":1960,"description":"British Somaliland and Italian Somalia became independent within a week of each other and merged into a single Somali Republic.","image":"/events/somalia.webp","credit":"Marco Gualazzini","license":"CC BY-SA 4.0"},"madagascar":{"name":"Madagascar becomes independent","country":"MG","kind":"nation","year":1960,"description":"The world's fourth-largest island took its independence from France in the Year of Africa, thirteen years after a rising that French forces had crushed at terrible cost.","image":"/events/madagascar.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"tanzania":{"name":"Tanganyika and Zanzibar become Tanzania","country":"TZ","kind":"nation","year":1964,"description":"Mainland Tanganyika and the island of Zanzibar united into one republic under Julius Nyerere — the rare African union that held.","image":"/events/tanzania.webp","license":"Public domain"},"zambia":{"name":"Zambia becomes independent","country":"ZM","kind":"nation","year":1964,"description":"Northern Rhodesia became Zambia under Kenneth Kaunda, taking its name from the Zambezi — and inheriting an economy built almost entirely on copper.","image":"/events/zambia.webp","credit":"Gabriel Ellison","license":"Public domain"},"botswana":{"name":"Botswana becomes independent","country":"BW","kind":"nation","year":1966,"description":"One of the poorest countries on Earth at independence, Botswana found diamonds within a year — and managed them into one of Africa's steadiest democracies and economies.","image":"/events/botswana.webp","credit":"Joachim Huber from Switzerland","license":"CC BY-SA 2.0"},"fiji":{"name":"Fiji becomes independent","country":"FJ","kind":"nation","year":1970,"description":"Fiji ended 96 years as a British colony, taking independence with a population almost evenly split between indigenous Fijians and Indian-descended islanders.","image":"/events/fiji.webp","credit":"Виктор Пинчук","license":"CC BY-SA 4.0"},"papua-new-guinea":{"name":"Papua New Guinea becomes independent","country":"PG","kind":"nation","year":1975,"description":"The most linguistically diverse country on Earth — some 840 languages — took independence from Australia peacefully, without a war of liberation.","image":"/events/papua-new-guinea.webp","credit":"User:Nightstallion","license":"Public domain"},"suriname":{"name":"Suriname becomes independent","country":"SR","kind":"nation","year":1975,"description":"The Netherlands' South American colony became independent; within five years almost a third of its people had emigrated to the country it left.","image":"/events/suriname.webp","credit":"See File history below for details.","license":"Public domain"},"green-march":{"name":"Green March","country":"MA","kind":"politics","year":1975,"description":"Morocco sent 350,000 unarmed civilians walking into Spanish Sahara behind flags and Qurans. Spain withdrew — and the status of Western Sahara has been disputed ever since.","image":"/events/green-march.webp"},"nicaraguan-revolution":{"name":"The Sandinistas take Managua","country":"NI","kind":"revolution","year":1979,"description":"The Sandinista guerrillas toppled the Somoza family after 43 years of dynastic rule. The US-backed Contra war against the new government defined the region's next decade.","image":"/events/nicaraguan-revolution.webp","credit":"Puskechina","license":"CC BY-SA 4.0"},"dakar-rally":{"name":"The first Paris–Dakar rally sets off","country":"SN","kind":"culture","year":1978,"description":"A racer who had gotten lost in the Libyan desert decided everyone should: some 180 vehicles left Paris for Dakar across the Sahara. Fewer than half arrived.","image":"/events/dakar-rally.webp","credit":"Rally Dakar 2006 9.jpg: Dakar organization derivative work: Lošmi (talk)","license":"Public domain"},"1989-paraguayan-coup-d-etat":{"name":"Stroessner falls after 35 years","country":"PY","kind":"revolution","year":1989,"description":"General Stroessner — the hemisphere's longest-ruling dictator — was toppled by his own son-in-law's faction in a night of fighting in Asunción, opening Paraguay's slow turn to elections.","image":"/events/1989-paraguayan-coup-d-etat.webp","credit":"Casa Fotográfica Resck","license":"Public domain"},"kazakhstan":{"name":"Kazakhstan becomes independent","country":"KZ","kind":"nation","year":1991,"description":"The last Soviet republic to declare independence — five days before the USSR itself dissolved — inherited the world's ninth-largest territory and its main spaceport, Baikonur.","image":"/events/kazakhstan.webp","credit":"Dmitry A. Mottl","license":"CC BY-SA 3.0"},"chapultepec-peace-accords":{"name":"El Salvador's war ends at Chapultepec","country":"SV","kind":"politics","year":1992,"description":"Government and FMLN guerrillas signed away twelve years of civil war — 75,000 dead — in Mexico City's Chapultepec Castle, folding the guerrillas into electoral politics.","image":"/events/chapultepec-peace-accords.webp","credit":"Jorge Montenegro (www.jmontenegro.com.sv)","license":"Public domain"},"barbados":{"name":"Barbados becomes independent","country":"BB","kind":"nation","year":1966,"description":"Barbados took independence from Britain after three centuries as a sugar colony — and in 2021 completed the journey, replacing the Queen with a Barbadian president.","image":"/events/barbados.webp","credit":"Patdoy at en.wikipedia","license":"CC BY-SA 3.0"},"2008-bhutanese-national-assembly-election":{"name":"Bhutan votes for the first time","country":"BT","kind":"politics","year":2008,"description":"The Himalayan kingdom famous for measuring Gross National Happiness held its first general election — a democracy introduced from the throne, at the king's own insistence.","image":"/events/2008-bhutanese-national-assembly-election.webp","credit":"Election Commission of India","license":"GODL-India"},"playstation":{"name":"The PlayStation launches","country":"JP","kind":"culture","year":1994,"description":"Born from a Nintendo partnership that collapsed, Sony's grey box took video games from the children's bedroom to the living room — the first console to sell 100 million.","image":"/events/playstation.webp","credit":"Evan-Amos","license":"Public domain"},"deep-blue-versus-garry-kasparov":{"name":"Deep Blue beats the world champion","country":"US","kind":"science","year":1997,"description":"IBM's chess machine beat world champion Garry Kasparov over six games — the first defeat of a reigning champion by a computer, and a line quietly crossed for everyone.","image":"/events/deep-blue-versus-garry-kasparov.webp"},"google":{"name":"Google is founded","country":"US","kind":"culture","year":1998,"description":"Two Stanford students incorporated their search project in a rented garage. Its name became the verb for finding anything out.","image":"/events/google.webp","credit":"Asoundd","license":"CC BY-SA 4.0"},"shenzhou-5":{"name":"China puts a person in space","country":"CN","kind":"science","year":2003,"description":"Yang Liwei orbited the Earth fourteen times aboard Shenzhou 5, making China the third nation — forty-two years after the first two — to launch a human into space on its own.","image":"/events/shenzhou-5.webp","credit":"中国新闻社","license":"CC BY 3.0"},"facebook":{"name":"Facebook goes online","country":"US","kind":"culture","year":2004,"description":"A student directory coded in a Harvard dorm room grew into the network holding a third of humanity — and into the era's hardest arguments about privacy and truth.","image":"/events/facebook.webp"},"iau-definition-of-planet":{"name":"Pluto is demoted","country":"CZ","kind":"science","year":2006,"description":"Astronomers meeting in Prague voted a formal definition of \"planet\" — and Pluto, beloved ninth planet for 76 years, became a dwarf planet by show of hands.","image":"/events/iau-definition-of-planet.webp"},"2010-eruptions-of-eyjafjallajokull":{"name":"An Icelandic volcano grounds Europe","country":"IS","kind":"disaster","year":2010,"description":"Ash from an unpronounceable Icelandic volcano closed most of Europe's airspace for nearly a week — the largest air-traffic shutdown since the Second World War, without a single casualty.","image":"/events/2010-eruptions-of-eyjafjallajokull.webp","credit":"Árni Friðriksson","license":"CC BY-SA 3.0"},"2010-copiapo-mining-accident":{"name":"The 33 Chilean miners surface","country":"CL","kind":"disaster","year":2010,"description":"Thirty-three miners survived 69 days seven hundred metres underground in the Atacama, and a billion people watched the capsule winch every one of them back to daylight.","image":"/events/2010-copiapo-mining-accident.webp","credit":"desierto_atacama","license":"CC BY-SA 2.0"},"first-observation-of-gravitational-waves":{"name":"Gravitational waves are heard","country":"US","kind":"science","year":2015,"description":"Twin LIGO detectors caught the spacetime ripple of two black holes colliding a billion light-years away — the confirmation Einstein predicted but thought undetectable.","image":"/events/first-observation-of-gravitational-waves.webp"},"alphago-versus-lee-sedol":{"name":"AlphaGo beats Lee Sedol","country":"KR","kind":"science","year":2016,"description":"DeepMind's AlphaGo beat the great Lee Sedol four games to one at Go, a game thought safe from machines for decades — its \"move 37\" was so alien commentators assumed a mistake.","image":"/events/alphago-versus-lee-sedol.webp","credit":"Alzinous","license":"CC BY-SA 4.0"},"tham-luang-cave-rescue":{"name":"The Thai cave rescue","country":"TH","kind":"culture","year":2018,"description":"Twelve boys and their football coach, trapped ten days deep in a flooding cave, were sedated and dived out one by one by an improvised international team — all thirteen survived.","image":"/events/tham-luang-cave-rescue.webp","credit":"NBT","license":"CC BY 3.0"},"school-strike-for-climate":{"name":"A school strike goes global","country":"SE","kind":"culture","year":2018,"description":"Fifteen-year-old Greta Thunberg sat down outside Sweden's parliament with a hand-painted sign instead of going to school. Within a year, millions were striking with her.","image":"/events/school-strike-for-climate.webp","credit":"Leonhard Lenz","license":"CC0"},"2021-suez-canal-obstruction":{"name":"One ship blocks world trade","country":"EG","kind":"culture","year":2021,"description":"The 400-metre container ship Ever Given wedged itself across the Suez Canal for six days, holding up billions in trade daily — and becoming the internet's favourite metaphor.","image":"/events/2021-suez-canal-obstruction.webp","credit":"Contains modified Copernicus Sentinel data [2021], processed by Pierre Markuse","license":"CC BY 2.0"},"chandrayaan-3":{"name":"India lands at the lunar south pole","country":"IN","kind":"science","year":2023,"description":"India became the fourth country to soft-land on the Moon and the first to reach its south polar region — days after a Russian attempt crashed, and on a famously lean budget.","image":"/events/chandrayaan-3.webp","credit":"Indian Space Research Organisation","license":"GODL-India"},"first-voyage-of-james-cook":{"name":"Cook charts the Pacific","country":"AU","kind":"science","year":1770,"description":"Sent to Tahiti to watch Venus cross the Sun, James Cook's Endeavour sailed on to circle New Zealand and chart Australia's east coast, claiming it for Britain at Botany Bay.","image":"/events/first-voyage-of-james-cook.webp","credit":"E. Phillips Fox","license":"Public domain"},"lewis-and-clark-expedition":{"name":"Lewis and Clark head west","country":"US","kind":"science","year":1804,"description":"Jefferson sent Meriwether Lewis and William Clark up the Missouri to find a route to the Pacific. With the Shoshone guide Sacagawea they crossed the continent and back in two and a half years.","image":"/events/lewis-and-clark-expedition.webp","credit":"Charles Marion Russell","license":"Public domain"},"challenger-expedition":{"name":"The Challenger expedition sails","country":"GB","kind":"science","year":1872,"description":"HMS Challenger left Portsmouth to spend four years sounding the oceans — the voyage that founded oceanography, catalogued thousands of new species, and first plumbed the deep that now carries its name.","image":"/events/challenger-expedition.webp","credit":"http://www.zamboanga.com/history/histor8.jpg","license":"Public domain"},"imperial-trans-antarctic-expedition":{"name":"Shackleton's Endurance is crushed","country":"GB","kind":"science","year":1915,"description":"Shackleton's ship Endurance was squeezed to splinters by Antarctic pack ice. His crew drifted on ice floes, sailed an open boat 1,300 km to South Georgia — and every one of the 28 men survived.","image":"/events/imperial-trans-antarctic-expedition.webp","credit":"Frank Hurley","license":"Public domain"},"bathyscaphe-trieste":{"name":"The deepest dive on Earth","country":"CH","kind":"science","year":1960,"description":"Jacques Piccard and Don Walsh rode the Swiss-built Trieste eleven kilometres down into the Mariana Trench — the deepest point of any ocean. No one returned for over fifty years.","image":"/events/bathyscaphe-trieste.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"luna-2":{"name":"The first craft reaches the Moon","country":"RU","kind":"science","year":1959,"description":"The Soviet probe Luna 2 crashed into the Moon by design — the first human-made object to touch another world, scattering Soviet pennants across the surface.","image":"/events/luna-2.webp","credit":"NASA/NSSDCA (public domain)","license":"Public domain"},"voskhod-2":{"name":"The first spacewalk","country":"RU","kind":"science","year":1965,"description":"Alexei Leonov floated out of Voskhod 2 on a five-metre tether for twelve minutes. His suit ballooned so badly in the vacuum that he barely squeezed back through the airlock — a detail kept secret for years.","image":"/events/voskhod-2.webp","credit":"USSR Post","license":"Public domain"},"apollo-8":{"name":"First humans around the Moon","country":"US","kind":"science","year":1968,"description":"Apollo 8 carried the first people beyond Earth orbit, looping the Moon on Christmas Eve. Its crew brought home Earthrise — the photograph of our planet rising over a grey horizon.","image":"/events/apollo-8.webp","credit":"NASA","license":"Public domain"},"apollo-13":{"name":"Apollo 13's safe return","country":"US","kind":"science","year":1970,"description":"An oxygen tank exploded 320,000 km from Earth, and a Moon landing became a rescue: the crew rode their freezing lunar module around the Moon and home — the \"successful failure\".","image":"/events/apollo-13.webp","credit":"NASA","license":"Public domain"},"salyut-1":{"name":"The first space station","country":"RU","kind":"science","year":1971,"description":"The Soviet Union orbited Salyut 1, the first station humans lived aboard in space. Its first crew stayed 23 days — then died on re-entry when their capsule lost its air.","image":"/events/salyut-1.webp","credit":"USSR Post","license":"Public domain"},"apollo-soyuz":{"name":"A handshake in orbit","country":"US","kind":"science","year":1975,"description":"An American Apollo and a Soviet Soyuz docked nose to nose, and their commanders shook hands through the hatch — the Cold War rivals' first joint flight, and the symbolic close of the space race.","image":"/events/apollo-soyuz.webp","credit":"R. Bruneau","license":"Public domain"},"viking-1":{"name":"Viking 1 lands on Mars","country":"US","kind":"science","year":1976,"description":"NASA's Viking 1 made the first fully successful landing on Mars and worked its patch of red desert for six years, sending home the first photographs taken on the planet's surface.","image":"/events/viking-1.webp","credit":"NASA","license":"Public domain"},"mir-space-station":{"name":"Mir goes up","country":"RU","kind":"science","year":1986,"description":"The Soviet Union launched the core of Mir, the first station assembled in orbit module by module. It hosted crews for fifteen years — one cosmonaut stayed aboard 437 days without a break.","image":"/events/mir-space-station.webp","credit":"Original image: NASA/Crew of STS-91Retouched image: Thegreenj","license":"Public domain"},"mars-pathfinder":{"name":"A rover rolls onto Mars","country":"US","kind":"science","year":1997,"description":"Pathfinder bounced onto Mars wrapped in airbags and released Sojourner, a rover the size of a microwave oven — the first wheels ever to turn on another planet.","image":"/events/mars-pathfinder.webp","credit":"NASA","license":"Public domain"},"rosetta-spacecraft":{"name":"Rosetta sets off to catch a comet","country":"DE","kind":"science","year":2004,"description":"Europe's Rosetta probe left on a ten-year chase to orbit a comet, and in 2014 dropped its lander Philae onto the surface — the first controlled landing on a comet.","image":"/events/rosetta-spacecraft.webp","credit":"ESA/ATG medialab","license":"CC BY-SA 2.0"},"curiosity-rover":{"name":"Curiosity lands on Mars","country":"US","kind":"science","year":2012,"description":"The car-sized rover Curiosity was lowered onto Mars by a hovering rocket crane — \"seven minutes of terror\" executed perfectly — and found the chemistry of an ancient habitable lake.","image":"/events/curiosity-rover.webp","credit":"NASA/JPL-Caltech/MSSS","license":"Public domain"},"falcon-9-flight-20":{"name":"A rocket lands itself","country":"US","kind":"engineering","year":2015,"description":"SpaceX's Falcon 9 delivered its satellites, then flew its first stage back to Cape Canaveral and set it down upright — the trick that made rockets reusable and launch costs collapse.","image":"/events/falcon-9-flight-20.webp","credit":"SpaceX Photos","license":"CC0"},"ingenuity-helicopter":{"name":"First flight on another planet","country":"US","kind":"science","year":2021,"description":"The little helicopter Ingenuity spun its blades in air a hundredth as thick as Earth's and lifted off over Mars — the first powered flight on another planet, carrying a scrap of the Wright Flyer's wing.","image":"/events/ingenuity-helicopter.webp","credit":"NASA/JPL-Caltech","license":"Public domain"},"smallpox-vaccine":{"name":"Jenner develops the smallpox vaccine","country":"GB","kind":"science","year":1798,"description":"Edward Jenner scratched cowpox into a boy's arm and proved it protected against smallpox — the first vaccine, named for the cow. The disease it beat is the only human one ever eradicated.","image":"/events/smallpox-vaccine.webp","credit":"Photo Credit: James Gathany Content Providers(s): CDC","license":"Public domain"},"experiments-on-plant-hybridization":{"name":"Mendel publishes his pea experiments","country":"CZ","kind":"science","year":1866,"description":"The monk Gregor Mendel, counting traits across thousands of pea plants in his monastery garden in Brno, worked out the laws of inheritance — then was ignored for thirty-four years.","image":"/events/experiments-on-plant-hybridization.webp","credit":"Gregor Mendel","license":"Public domain"},"periodic-table":{"name":"Mendeleev arranges the elements","country":"RU","kind":"science","year":1869,"description":"Dmitri Mendeleev laid the elements out by weight and saw their properties repeat in periods — and left gaps for elements not yet discovered, predicting what would fill them. It did.","image":"/events/periodic-table.webp","license":"CC BY-SA 4.0"},"x-ray":{"name":"Röntgen discovers X-rays","country":"DE","kind":"science","year":1895,"description":"Wilhelm Röntgen chased a mysterious ray that made a screen glow across his darkened lab, and within weeks photographed the bones of his wife's hand. He refused to patent it; medicine changed overnight.","image":"/events/x-ray.webp","credit":"Wilhelm Röntgen","license":"Public domain"},"electron":{"name":"The electron is discovered","country":"GB","kind":"science","year":1897,"description":"J. J. Thomson showed cathode rays were streams of particles nearly two thousand times lighter than the lightest atom — the first piece of the atom found, and the carrier every electronic device runs on.","image":"/events/electron.webp","credit":"Geek3","license":"CC BY-SA 4.0"},"general-relativity":{"name":"Einstein presents general relativity","country":"DE","kind":"science","year":1915,"description":"Einstein told the Prussian Academy that gravity is not a force but the curving of space and time. An eclipse four years later showed starlight bending around the Sun — and made him world-famous.","image":"/events/general-relativity.webp","license":"CC BY-SA 4.0"},"pluto":{"name":"Pluto is discovered","country":"US","kind":"science","year":1930,"description":"Clyde Tombaugh, a 24-year-old farm boy hired to compare photographs of the night sky, spotted a moving speck from an Arizona observatory — the ninth planet, until its 2006 demotion.","image":"/events/pluto.webp","license":"Public domain"},"lascaux":{"name":"The Lascaux cave paintings are found","country":"FR","kind":"science","year":1940,"description":"Four teenagers following their dog into a hole in the Dordogne found galleries of bulls and horses painted some 17,000 years earlier — among the finest prehistoric art ever discovered.","image":"/events/lascaux.webp","credit":"EU","license":"Public domain"},"cosmic-microwave-background":{"name":"The Big Bang's afterglow is found","country":"US","kind":"science","year":1964,"description":"Two radio astronomers could not silence a faint hiss in their antenna — not even after evicting its pigeons. It was the cooled glow of the Big Bang itself, and it won them the Nobel Prize.","image":"/events/cosmic-microwave-background.webp","credit":"NASA / WMAP Science Team","license":"Public domain"},"lucy-australopithecus":{"name":"Lucy is unearthed","country":"ET","kind":"science","year":1974,"description":"In Ethiopia's Afar desert, palaeontologists dug up a 3.2-million-year-old skeleton that had walked upright — and named her Lucy, after the Beatles song playing in camp that night.","image":"/events/lucy-australopithecus.webp","credit":"120","license":"CC BY 2.5"},"terracotta-army":{"name":"The Terracotta Army is found","country":"CN","kind":"science","year":1974,"description":"Farmers digging a well near Xi'an struck the buried bodyguard of China's First Emperor: thousands of life-sized clay soldiers, no two faces alike, standing in ranks for 2,200 years.","image":"/events/terracotta-army.webp","credit":"xiquinhosilva","license":"CC BY 2.0"},"51-pegasi-b":{"name":"A planet around another sun","country":"CH","kind":"science","year":1995,"description":"Two Swiss astronomers caught a star fifty light-years away wobbling under the pull of an unseen companion — the first planet found orbiting a Sun-like star. Thousands more followed.","image":"/events/51-pegasi-b.webp","credit":"ESO/M. Kornmesser/Nick Risinger (skysurvey.org)","license":"CC BY 4.0"},"dandy-horse":{"name":"The first bicycle rolls out","country":"DE","kind":"engineering","year":1817,"description":"Karl von Drais pushed his two-wheeled \"running machine\" along the Mannheim road — no pedals yet, but the bicycle was born, invented partly because a failed harvest had left horses scarce.","image":"/events/dandy-horse.webp","credit":"Gun Powder Ma","license":"CC BY-SA 3.0"},"transatlantic-telegraph-cable":{"name":"A cable crosses the Atlantic","country":"GB","kind":"engineering","year":1858,"description":"A telegraph cable laid across the ocean floor let Queen Victoria wire the US president in minutes instead of ten days by ship. The first cable died within weeks — but the world had shrunk for good.","image":"/events/transatlantic-telegraph-cable.webp","credit":"Robert Charles Dudley","license":"Public domain"},"london-underground":{"name":"The first underground railway opens","country":"GB","kind":"engineering","year":1863,"description":"The Metropolitan Railway carried some 38,000 Londoners underground on its opening day, behind steam engines that filled the tunnels with smoke — the world's first metro, and the reason many still call it the Tube.","image":"/events/london-underground.webp","credit":"tompagenet (Tom Page)","license":"CC BY-SA 2.0"},"telephone":{"name":"Bell patents the telephone","country":"US","kind":"engineering","year":1876,"description":"Alexander Graham Bell patented the telephone hours ahead of a rival inventor, and days later spoke the first words down a wire: \"Mr. Watson, come here — I want to see you.\"","image":"/events/telephone.webp","credit":"Berthold Werner","license":"CC BY-SA 3.0"},"phonograph":{"name":"Edison records sound","country":"US","kind":"engineering","year":1877,"description":"Thomas Edison shouted \"Mary had a little lamb\" at a tinfoil cylinder and played his own voice back — the first machine that could both record and reproduce sound. He was as startled as anyone.","image":"/events/phonograph.webp","credit":"Levin C. Handy (per http://hdl.loc.gov/loc.pnp/cwpbh.04326)","license":"Public domain"},"zeppelin-lz-1":{"name":"The first Zeppelin flies","country":"DE","kind":"engineering","year":1900,"description":"Count Zeppelin's 128-metre airship rose over Lake Constance for eighteen minutes — three years before the Wright brothers. For a generation, the future of flight looked like this.","image":"/events/zeppelin-lz-1.webp","credit":"Peter Scherer","license":"Public domain"},"heinkel-he-178":{"name":"The first jet aircraft flies","country":"DE","kind":"engineering","year":1939,"description":"Days before the Second World War began, the Heinkel He 178 made the first flight powered by a turbojet — the engine, designed by Hans von Ohain, that every airliner descends from.","image":"/events/heinkel-he-178.webp","credit":"Heinkel","license":"Public domain"},"transistor":{"name":"The transistor is invented","country":"US","kind":"engineering","year":1947,"description":"Three Bell Labs physicists made a sliver of germanium amplify a current — the transistor, replacement for the hot, fragile vacuum tube. Billions of them now sit in every phone.","image":"/events/transistor.webp","credit":"ArnoldReinhold","license":"CC BY-SA 3.0"},"arpanet":{"name":"The internet sends its first message","country":"US","kind":"engineering","year":1969,"description":"A computer at UCLA tried to send \"LOGIN\" to Stanford and crashed after two letters — \"LO\". ARPANET grew from those two machines into the internet.","image":"/events/arpanet.webp","credit":"ARPANET","license":"Public domain"},"compact-disc":{"name":"The compact disc arrives","country":"NL","kind":"engineering","year":1982,"description":"Philips and Sony launched the compact disc, music read by laser with no needle and no hiss. Legend has it the 74-minute length was chosen to hold Beethoven's Ninth uninterrupted.","image":"/events/compact-disc.webp","credit":"User Black and White on en.wikipedia","license":"CC BY-SA 3.0"},"don-quixote":{"name":"Don Quixote is published","country":"ES","kind":"culture","year":1605,"description":"Cervantes published his tale of a country gentleman driven mad by chivalry books, tilting at windmills beside his squire Sancho Panza — often called the first modern novel, and still among the most printed.","image":"/events/don-quixote.webp","credit":"Juan de la Cuesta","license":"Public domain"},"l-orfeo":{"name":"Opera is born with L'Orfeo","country":"IT","kind":"culture","year":1607,"description":"Monteverdi's L'Orfeo, staged for the duke of Mantua, told the Orpheus myth entirely through music — the earliest opera still regularly performed, four centuries on.","image":"/events/l-orfeo.webp","credit":"Bernardo Strozzi","license":"Public domain"},"first-folio":{"name":"Shakespeare's First Folio is printed","country":"GB","kind":"culture","year":1623,"description":"Seven years after Shakespeare died, two fellow actors gathered 36 of his plays into one volume. Half of them — Macbeth among them — had never been printed and would otherwise be lost.","image":"/events/first-folio.webp","credit":"William Shakespeare","license":"Public domain"},"la-scala":{"name":"La Scala opens in Milan","country":"IT","kind":"culture","year":1778,"description":"Milan's opera house rose in two years on the site of a burned theatre, paid for by its box-holders. Verdi, Puccini and Maria Callas made its stage the most famous in opera.","image":"/events/la-scala.webp","credit":"Jakub Hałun","license":"CC BY-SA 4.0"},"symphony-no-9-beethoven":{"name":"Beethoven's Ninth premieres","country":"AT","kind":"culture","year":1824,"description":"Beethoven, by then completely deaf, stood beside the conductor at the Vienna premiere of his Ninth — and had to be turned around to see the applause he could not hear. Its Ode to Joy is now Europe's anthem.","image":"/events/symphony-no-9-beethoven.webp","credit":"Carl Offterdinger","license":"Public domain"},"1877-wimbledon-championship":{"name":"The first Wimbledon","country":"GB","kind":"culture","year":1877,"description":"The All England Croquet Club held a lawn-tennis tournament to raise money for a broken roller — 22 gentlemen, a 25-guinea trophy, and the oldest tennis championship in the world.","image":"/events/1877-wimbledon-championship.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"the-starry-night":{"name":"Van Gogh paints The Starry Night","country":"NL","kind":"culture","year":1889,"description":"From his asylum window in Saint-Rémy, Vincent van Gogh painted the night sky boiling with stars. He thought little of it; it became one of the most recognised paintings on Earth.","image":"/events/the-starry-night.webp","credit":"Vincent van Gogh","license":"Public domain"},"the-scream":{"name":"Munch paints The Scream","country":"NO","kind":"culture","year":1893,"description":"Walking at sunset above Oslo, Edvard Munch felt \"an infinite scream passing through nature\" — and painted the swirling, hollow-faced figure that became the modern face of anxiety.","image":"/events/the-scream.webp","credit":"Edvard Munch","license":"Public domain"},"raja-harishchandra":{"name":"India's first feature film","country":"IN","kind":"culture","year":1913,"description":"Dadasaheb Phalke wrote, produced and directed Raja Harishchandra, India's first full-length feature — with men in the women's roles, since no actress would join. Indian cinema counts its history from it.","image":"/events/raja-harishchandra.webp","credit":"Dadasaheb Phalke","license":"Public domain"},"steamboat-willie":{"name":"Mickey Mouse whistles into view","country":"US","kind":"culture","year":1928,"description":"Disney's Steamboat Willie was among the first cartoons with fully synchronised sound — a whistling mouse at a ship's wheel who became the most famous character ever drawn.","image":"/events/steamboat-willie.webp","credit":"Ub Iwerks","license":"Public domain"},"1st-academy-awards":{"name":"The first Oscars","country":"US","kind":"culture","year":1929,"description":"Hollywood's first Academy Awards took fifteen minutes to hand out, at a private dinner where the winners had been announced three months in advance. The statuette's nickname — Oscar — came later.","image":"/events/1st-academy-awards.webp","credit":"Academy of Motion Picture Arts and Sciences","license":"Public domain"},"snow-white-and-the-seven-dwarfs-1937-film":{"name":"The first feature-length cartoon","country":"US","kind":"culture","year":1937,"description":"The press called it \"Disney's Folly\" — surely no one would sit through 83 minutes of animation. Snow White became the highest-grossing film of its day and invented the animated feature.","image":"/events/snow-white-and-the-seven-dwarfs-1937-film.webp","license":"Public domain"},"guernica-picasso":{"name":"Picasso paints Guernica","country":"ES","kind":"culture","year":1937,"description":"Weeks after German bombers flattened the Basque town of Gernika, Picasso answered with a canvas eight metres wide of screaming horses and grieving mothers — the century's defining image of war.","image":"/events/guernica-picasso.webp","credit":"Jules Verne Times Two","license":"CC BY-SA 4.0"},"the-lord-of-the-rings":{"name":"The Lord of the Rings is published","country":"GB","kind":"culture","year":1954,"description":"Tolkien's \"new Hobbit\" had swollen into a three-volume epic, twelve years in the writing. The Fellowship of the Ring appeared first and founded modern fantasy almost single-handed.","image":"/events/the-lord-of-the-rings.webp","credit":"Zanastardust","license":"CC BY 2.0"},"disneyland":{"name":"Disneyland opens its gates","country":"US","kind":"culture","year":1955,"description":"Walt Disney opened his park in a former Anaheim orange grove on a chaotic day of broken rides, gate-crashers and softening asphalt — and created the template every theme park since has copied.","image":"/events/disneyland.webp","credit":"HarshLight from San Jose, CA, USA","license":"CC BY 2.0"},"one-hundred-years-of-solitude":{"name":"García Márquez conjures Macondo","country":"CO","kind":"culture","year":1967,"description":"Gabriel García Márquez pawned household goods to post the manuscript of One Hundred Years of Solitude to his publisher. The chronicle of the Buendía family made magical realism world literature.","image":"/events/one-hundred-years-of-solitude.webp","credit":"Gorup de Besanez","license":"CC BY-SA 4.0"},"thriller-album":{"name":"Thriller takes over the world","country":"US","kind":"culture","year":1982,"description":"Michael Jackson released Thriller, and its zombie-dance title video turned the music album into cinema. It remains the best-selling album ever recorded.","image":"/events/thriller-album.webp","credit":"Aurelio Jose Barrera","license":"CC BY 4.0"},"tetris":{"name":"Tetris escapes Moscow","country":"RU","kind":"culture","year":1984,"description":"Alexey Pajitnov, a researcher at the Soviet Academy of Sciences, wrote a falling-blocks puzzle on a machine with no graphics — its bricks drawn from text characters. It became the most ported game in history.","image":"/events/tetris.webp","credit":"Vincent Diamante from Los Angeles, CA, USA","license":"CC BY-SA 2.0"},"game-boy":{"name":"The Game Boy launches","country":"JP","kind":"culture","year":1989,"description":"Nintendo's grey brick with a green screen was mocked beside its full-colour rivals — and outsold them all on battery life and Tetris, putting video games in every pocket.","image":"/events/game-boy.webp","credit":"Evan-Amos","license":"Public domain"},"harry-potter-and-the-philosopher-s-stone":{"name":"Harry Potter arrives","country":"GB","kind":"culture","year":1997,"description":"Turned down by a dozen publishers, J. K. Rowling's boy wizard appeared in a first print run of 500 copies. The series went on to sell more than half a billion books and revive children's reading worldwide.","image":"/events/harry-potter-and-the-philosopher-s-stone.webp","credit":"Cygomezm","license":"CC BY-SA 4.0"},"youtube":{"name":"YouTube uploads its first video","country":"US","kind":"culture","year":2005,"description":"Three former PayPal employees launched a site for sharing home videos; the first upload was nineteen seconds at the zoo. Within two years the world watched more video there than on any TV network.","image":"/events/youtube.webp","credit":"Smile and Learn - English, Rockin Robin Cooks, Nicky's Kitchen","license":"Public domain"},"death-of-napoleon":{"name":"Napoleon dies on Saint Helena","country":"FR","kind":"politics","year":1821,"description":"Six years after Waterloo, the exiled emperor died in British custody on Saint Helena, one of the remotest islands on Earth. His body came home to Paris nineteen years later to a hero's tomb.","image":"/events/death-of-napoleon.webp","credit":"Charles de Steuben","license":"Public domain"},"das-kapital":{"name":"Marx publishes Das Kapital","country":"DE","kind":"culture","year":1867,"description":"Marx published the first volume of his critique of capitalism in Hamburg, after long years in the British Museum's reading room. The remaining volumes appeared only after his death, edited by Engels.","image":"/events/das-kapital.webp","credit":"Zentralbibliothek Zürich","license":"Public domain"},"war-and-peace":{"name":"Tolstoy finishes War and Peace","country":"RU","kind":"culture","year":1869,"description":"Tolstoy completed his vast chronicle of Russia in the Napoleonic wars, following five families through invasion and peace. He insisted it was not a novel at all — genres, he said, could not hold it.","image":"/events/war-and-peace.webp","credit":"Leo Tolstoy","license":"Public domain"},"fountain-duchamp":{"name":"A urinal splits art history","country":"FR","kind":"culture","year":1917,"description":"Duchamp signed a porcelain urinal 'R. Mutt' and submitted it to a New York exhibition that had promised to refuse nothing — it was refused anyway. After that gesture, an artwork could be an idea.","image":"/events/fountain-duchamp.webp","credit":"Marcel Duchamp","license":"Public domain"},"ulysses":{"name":"Ulysses is published in Paris","country":"IE","kind":"culture","year":1922,"description":"Sylvia Beach's Paris bookshop published Joyce's banned epic of a single Dublin day — June the sixteenth — after serial instalments had been prosecuted for obscenity. Fans still retrace the day each year as Bloomsday.","image":"/events/ulysses.webp","license":"Public domain"},"space-shuttle-columbia-disaster":{"name":"Columbia breaks up on re-entry","country":"US","kind":"disaster","year":2003,"description":"Columbia broke apart over Texas minutes from landing, killing her crew of seven — a chunk of foam had holed a wing at launch a fortnight before. The shuttle fleet never fully recovered.","image":"/events/space-shuttle-columbia-disaster.webp","credit":"NASA","license":"Public domain"},"taipei-101":{"name":"Taipei 101 opens as the tallest building on Earth","country":"TW","kind":"engineering","year":2004,"description":"The bamboo-shaped tower opened as the tallest building in the world, with a giant golden pendulum swinging inside to steady it against typhoons and earthquakes.","image":"/events/taipei-101.webp","credit":"User:Sinsyuan","license":"CC BY-SA 4.0"},"joint-comprehensive-plan-of-action":{"name":"The Iran nuclear deal is signed","country":"IR","kind":"politics","year":2015,"description":"After marathon talks in Vienna, Iran agreed with six world powers to shrink its nuclear programme in exchange for sanctions relief. Three years on, the United States walked out and the deal unravelled.","image":"/events/joint-comprehensive-plan-of-action.webp","credit":"Bundesministerium für Europa, Integration und Äusseres","license":"CC BY 2.0"},"squid-game":{"name":"Squid Game sweeps the world","country":"KR","kind":"culture","year":2021,"description":"A Korean survival drama of debtors playing deadly children's games became the most-watched series launch in Netflix history, its tracksuits and masked guards a global Halloween uniform within weeks.","image":"/events/squid-game.webp","credit":"Netflix","license":"Public domain"},"eruption-of-mount-tambora":{"name":"Tambora erupts","country":"ID","kind":"disaster","year":1815,"description":"The largest volcanic eruption in recorded history blew the top off Tambora and was heard across the archipelago. Its ash veiled the sun worldwide — the following 'Year Without a Summer' brought June snow and failed harvests.","image":"/events/eruption-of-mount-tambora.webp","credit":"myself","license":"CC BY-SA 3.0"},"united-kingdom-of-portugal-brazil-and-the-algarves":{"name":"Brazil is raised to a kingdom","country":"BR","kind":"nation","year":1815,"description":"With Lisbon lost to Napoleon's armies, the Portuguese court had fled to Rio de Janeiro — and now raised Brazil from colony to co-equal kingdom, a European empire ruled from its own colony.","image":"/events/united-kingdom-of-portugal-brazil-and-the-algarves.webp","credit":"117-M-I-K-E","license":"CC BY-SA 4.0"},"traffic-light":{"name":"The first traffic light is lit","country":"GB","kind":"engineering","year":1868,"description":"A gas-lit signal with semaphore arms went up outside the Houses of Parliament to tame horse-drawn traffic — the first traffic light. It exploded within weeks; the idea returned electrified half a century later.","image":"/events/traffic-light.webp","credit":"User:Wazouille","license":"Public domain"},"battle-of-tsushima":{"name":"The Russian fleet is destroyed at Tsushima","country":"JP","kind":"conflict","year":1905,"description":"Admiral Tōgō annihilated a Russian fleet that had sailed halfway around the world to meet him in the Tsushima Strait. The first great naval defeat of a European power by an Asian one stunned the world's chancelleries.","image":"/events/battle-of-tsushima.webp","credit":"Tōjō Shōtarō","license":"Public domain"},"potemkin-uprising":{"name":"Mutiny on the battleship Potemkin","country":"RU","kind":"revolution","year":1905,"description":"Sailors on the battleship Potemkin killed their officers over maggoty meat and ran up the red flag off Odessa. The mutiny became a symbol of revolution — and one of cinema's most famous films.","image":"/events/potemkin-uprising.webp","credit":"William Frederick Mitchell","license":"Public domain"},"first-battle-of-the-marne":{"name":"The taxis of the Marne save Paris","country":"FR","kind":"conflict","year":1914,"description":"French and British armies turned the German drive on Paris at the Marne — Parisian taxis famously ferried reserves to the front. The war of movement died there, and the trenches began.","image":"/events/first-battle-of-the-marne.webp","license":"Public domain"},"christmas-truce":{"name":"Carols between the trenches","country":"BE","kind":"conflict","year":1914,"description":"Along stretches of the Western Front, German and British soldiers climbed out of their trenches on Christmas Eve to sing carols, swap tobacco and bury their dead — a spontaneous peace their generals made sure never happened again.","image":"/events/christmas-truce.webp","credit":"Unknown","license":"Public domain"},"transatlantic-flight-of-alcock-and-brown":{"name":"Alcock and Brown fly the Atlantic","country":"GB","kind":"science","year":1919,"description":"Alcock and Brown flew a converted bomber nonstop from Newfoundland to Ireland in sixteen hours, landing nose-first in an Irish bog. The Atlantic had been crossed by air, eight years before Lindbergh flew it alone.","image":"/events/transatlantic-flight-of-alcock-and-brown.webp","credit":"Uwe Dedering","license":"CC BY-SA 3.0"},"bauhaus":{"name":"The Bauhaus opens in Weimar","country":"DE","kind":"culture","year":1919,"description":"Walter Gropius opened a school in Weimar that fused art, craft and industry. Closed by the Nazis within fourteen years, its clean-lined ideas escaped into exile and built the look of the modern world.","image":"/events/bauhaus.webp","credit":"A.Savin","license":"FAL"},"ipod":{"name":"A thousand songs in your pocket","country":"US","kind":"culture","year":2001,"description":"Apple's white brick with a scroll wheel arrived weeks after the dot-com crash and rebuilt the music industry around itself — paving the way for the phone that followed.","image":"/events/ipod.webp","credit":"User:House","license":"CC BY-SA 3.0"},"enron-scandal":{"name":"Enron collapses","country":"US","kind":"politics","year":2001,"description":"America's seventh-largest company collapsed in weeks when its profits proved to be accounting fiction. The scandal took the auditor Arthur Andersen down with it and rewrote the rules of corporate bookkeeping.","image":"/events/enron-scandal.webp","credit":"Alex","license":"CC BY 2.0"},"chatgpt":{"name":"ChatGPT is released","country":"US","kind":"science","year":2022,"description":"OpenAI released a chatbot as a low-key research preview; it reached a hundred million users faster than any consumer product before it and pushed artificial intelligence into everyday life.","image":"/events/chatgpt.webp","credit":"Gio Antonio","license":"Public domain"},"artemis-1":{"name":"Artemis flies back toward the Moon","country":"US","kind":"science","year":2022,"description":"Half a century after the last Apollo crew left the Moon, NASA's giant new rocket finally flew, sending an empty capsule around the far side and home — the first step of the programme meant to take people back.","image":"/events/artemis-1.webp","credit":"Kim Shiflett","license":"Public domain"},"great-chicago-fire":{"name":"Chicago burns","country":"US","kind":"disaster","year":1871,"description":"Fire leapt through a city built of wood until a third of Chicago lay in ashes and a hundred thousand people were homeless. The rebuilding that followed raised some of the world's first skyscrapers.","image":"/events/great-chicago-fire.webp","credit":"John R. Chapin, died 1907","license":"Public domain"},"royal-albert-hall":{"name":"The Royal Albert Hall opens","country":"GB","kind":"culture","year":1871,"description":"Queen Victoria opened the great domed hall raised in memory of her husband Albert. Its echo was notorious — the joke ran that it was the only place a British composer could hear their work twice.","image":"/events/royal-albert-hall.webp","credit":"Diliff","license":"CC BY-SA 3.0"},"battle-of-castillon":{"name":"The Hundred Years' War ends at Castillon","country":"FR","kind":"conflict","year":1453,"description":"French cannon shattered an English army at Castillon in Gascony — the last battle of the Hundred Years' War. England kept only Calais, and gunpowder had announced the end of the knight.","image":"/events/battle-of-castillon.webp","credit":"Charles-Philippe Larivière","license":"Public domain"},"wars-of-the-roses":{"name":"The Wars of the Roses begin","country":"GB","kind":"conflict","year":1455,"description":"The houses of Lancaster and York first drew blood at St Albans, opening three decades of dynastic civil war for England's crown — the feud of the red rose and the white that the Tudors would end.","image":"/events/wars-of-the-roses.webp","credit":"Ghent master","license":"Public domain"},"diet-of-worms":{"name":"Luther stands at Worms","country":"DE","kind":"politics","year":1521,"description":"\"Here I stand\" — summoned before the young emperor Charles V, Luther refused to recant his writings and left Worms an outlaw. Smuggled into hiding at the Wartburg, he set about translating the Bible into German.","image":"/events/diet-of-worms.webp","credit":"Anton von Werner","license":"Public domain"},"de-humani-corporis-fabrica":{"name":"Vesalius maps the human body","country":"BE","kind":"science","year":1543,"description":"In the same year Copernicus moved the Earth, the anatomist Vesalius published his lavishly illustrated atlas of the human body, built on dissections he performed himself — and toppled thirteen centuries of received wisdom.","image":"/events/de-humani-corporis-fabrica.webp","license":"Public domain"},"honno-ji-incident":{"name":"Nobunaga betrayed at Honnō-ji","country":"JP","kind":"politics","year":1582,"description":"Japan's great unifier Oda Nobunaga, betrayed by his own general, died in a burning Kyoto temple within reach of mastering the whole country. His avenger Hideyoshi finished the work within a decade.","image":"/events/honno-ji-incident.webp","credit":"Nobukazu Yōsai","license":"Public domain"},"manila":{"name":"Manila is founded","country":"PH","kind":"nation","year":1571,"description":"Legazpi founded Manila as the capital of the Spanish Philippines, and the galleons soon ran yearly to Acapulco — silver east, silk west — the first sustained trade route to span the Pacific.","image":"/events/manila.webp","credit":"Mike Gonzalez (TheCoffee)","license":"CC BY-SA 3.0"},"novum-organum":{"name":"Bacon proposes the scientific method","country":"GB","kind":"science","year":1620,"description":"Francis Bacon published his 'new instrument' for knowledge: stop deducing from ancient authority, start observing and experimenting. The method he argued for became the scientific one.","image":"/events/novum-organum.webp","credit":"Francis Bacon","license":"Public domain"},"discourse-on-the-method":{"name":"\"I think, therefore I am\"","country":"FR","kind":"science","year":1637,"description":"Descartes published the little book that made doubt itself the starting point of knowledge — and tucked into its appendices the coordinate geometry every graph still uses.","image":"/events/discourse-on-the-method.webp","credit":"Ian Maire","license":"Public domain"},"east-india-company":{"name":"The East India Company is chartered","country":"GB","kind":"politics","year":1600,"description":"Queen Elizabeth granted a company of London merchants a monopoly on trade east of the Cape. The venture would end up ruling a subcontinent with its own army before the Crown took India from it.","image":"/events/east-india-company.webp","credit":"Moll, Herman, -1732","license":"CC0"},"bodleian-library":{"name":"The Bodleian opens its doors","country":"GB","kind":"culture","year":1602,"description":"Thomas Bodley reopened Oxford's plundered university library, soon striking a deal that a copy of every book printed in England be deposited there. Readers still swear an oath not to kindle flame within.","image":"/events/bodleian-library.webp","credit":"Remi Mathis","license":"CC BY-SA 3.0"},"the-wealth-of-nations":{"name":"Adam Smith publishes The Wealth of Nations","country":"GB","kind":"culture","year":1776,"description":"In the same year America declared independence, the Scottish professor Adam Smith published his inquiry into why nations prosper — the invisible hand, the division of labour — and founded modern economics.","image":"/events/the-wealth-of-nations.webp","credit":"Gerhard Streminger","license":"Public domain"},"mutiny-on-the-bounty":{"name":"Mutiny on the Bounty","country":"GB","kind":"conflict","year":1789,"description":"Fletcher Christian set Captain Bligh adrift in the South Pacific with eighteen loyalists; Bligh sailed the open boat four thousand miles to safety, while the mutineers vanished to Pitcairn Island, where their descendants live still.","image":"/events/mutiny-on-the-bounty.webp","credit":"Robert Dodd","license":"Public domain"},"coup-of-18-brumaire":{"name":"Bonaparte seizes power","country":"FR","kind":"politics","year":1799,"description":"General Bonaparte returned from Egypt and overthrew the Directory in a near-bloodless coup, ending the French Revolution's decade of turmoil. The republic's First Consul would soon crown himself emperor.","image":"/events/coup-of-18-brumaire.webp","credit":"François Bouchot","license":"Public domain"},"boston-massacre":{"name":"Redcoats fire on a Boston crowd","country":"US","kind":"politics","year":1770,"description":"British soldiers fired into a jeering Boston crowd, killing five — Crispus Attucks among them, often called the first casualty of the Revolution. Paul Revere's engraving of the scene became the age's most effective propaganda.","image":"/events/boston-massacre.webp","license":"Public domain"},"the-magic-flute":{"name":"The Magic Flute premieres","country":"AT","kind":"culture","year":1791,"description":"Mozart's fairy-tale opera premiered in a popular Vienna theatre, its Queen of the Night aria a vocal Everest ever since. He died just weeks into its triumphant run, at thirty-five.","image":"/events/the-magic-flute.webp","license":"Public domain"},"alhambra-decree":{"name":"Spain expels its Jews","country":"ES","kind":"politics","year":1492,"description":"Months after Granada fell, Ferdinand and Isabella ordered Spain's Jews to convert or leave. Tens of thousands of Sephardim scattered across the Mediterranean, carrying a Spanish they speak to this day.","image":"/events/alhambra-decree.webp","credit":"Emilio Sala","license":"Public domain"},"airbus-a380":{"name":"The A380 takes flight","country":"FR","kind":"engineering","year":2005,"description":"The double-decked giant — the largest passenger aircraft ever built — lifted off from Toulouse on its maiden flight, watched live by tens of thousands. Airports rebuilt gates and runways to receive it.","image":"/events/airbus-a380.webp","credit":"Maarten Visser from Capelle aan den IJssel, Nederland","license":"CC BY-SA 2.0"},"beijing-olympics":{"name":"The Beijing Olympics open","country":"CN","kind":"culture","year":2008,"description":"China announced itself with the most spectacular Games ever staged, opening in the Bird's Nest with a drummed ceremony watched by a billion people. Michael Phelps swam to eight golds in a single Games.","image":"/events/beijing-olympics.webp","credit":"Original author: Pierre de Coubertin (1863-1937)","license":"Public domain"},"instagram":{"name":"Instagram launches","country":"US","kind":"culture","year":2010,"description":"Two Stanford graduates launched a photo app with retro filters; it gained a million users in under three months and sold to Facebook for a billion dollars before it was two years old.","image":"/events/instagram.webp","credit":"Santeri Viinamäki (both photo and screenshot)","license":"CC BY-SA 4.0"},"killing-of-osama-bin-laden":{"name":"Bin Laden found in Abbottabad","country":"PK","kind":"conflict","year":2011,"description":"US Navy SEALs flew by night into a compound in Abbottabad and killed the man behind the September 11 attacks, a decade after them. He had been living within a mile of Pakistan's military academy.","image":"/events/killing-of-osama-bin-laden.webp","credit":"Sajjad Ali Qureshi","license":"CC BY 2.0"},"battle-of-salamis":{"name":"The Greek fleet turns the tide at Salamis","country":"GR","kind":"conflict","year":-480,"description":"Themistocles lured the vast Persian fleet into the narrow strait off Salamis, where numbers counted for nothing, and broke it while Xerxes watched from a throne ashore. The same year the pass fell at Thermopylae.","image":"/events/battle-of-salamis.webp","credit":"Wilhelm von Kaulbach (painting); Burkhard Mücke (photo)","license":"CC BY-SA 4.0"},"malaysia-airlines-flight-370":{"name":"MH370 vanishes","country":"MY","kind":"disaster","year":2014,"description":"A red-eye to Beijing with 239 people aboard turned off course and vanished; years of the largest search in aviation history found only fragments washed ashore. Where it rests remains unknown.","image":"/events/malaysia-airlines-flight-370.webp","credit":"Kentaro Iemoto from Tokyo, Japan","license":"CC BY-SA 2.0"},"panama-papers":{"name":"The Panama Papers leak","country":"PA","kind":"politics","year":2016,"description":"Eleven million leaked files from a Panama City law firm exposed the offshore holdings of presidents, oligarchs and celebrities. Iceland's prime minister fell within days, and 'shell company' entered dinner-table vocabulary.","image":"/events/panama-papers.webp","credit":"JayCoop","license":"CC BY-SA 4.0"},"falcon-heavy-test-flight":{"name":"A sports car flies past Mars orbit","country":"US","kind":"science","year":2018,"description":"SpaceX's triple-core rocket thundered up from the old Apollo pad carrying its founder's cherry-red roadster, a spacesuited mannequin at the wheel — then landed two of its boosters side by side like choreography.","image":"/events/falcon-heavy-test-flight.webp","credit":"SpaceX","license":"CC0"},"battle-of-stamford-bridge":{"name":"The last Viking invasion breaks","country":"GB","kind":"conflict","year":1066,"description":"King Harold destroyed a Viking invasion at Stamford Bridge, ending the age of Norse kings in England — then force-marched his exhausted army south to meet William at Hastings, nineteen days later.","image":"/events/battle-of-stamford-bridge.webp","credit":"Peter Nicolai Arbo","license":"Public domain"},"crab-nebula-supernova":{"name":"A new star blazes in daylight","country":"CN","kind":"science","year":1054,"description":"Chinese astronomers recorded a 'guest star' in Taurus bright enough to see in daylight for weeks. Its shredded remains glow on as the Crab Nebula — the sky's most studied wreck of an exploded star.","image":"/events/crab-nebula-supernova.webp","credit":"NASA, ESA, J. Hester and A. Loll (Arizona State University)","license":"Public domain"},"fourth-council-of-the-lateran":{"name":"The great council of the Middle Ages","country":"VA","kind":"politics","year":1215,"description":"Innocent III summoned the greatest church council of the Middle Ages: hundreds of bishops set doctrine — transubstantiation among it — and rules that governed Catholic life for centuries.","image":"/events/fourth-council-of-the-lateran.webp","credit":"Jean-François Capdet","license":"CC BY 3.0"},"delhi-sultanate":{"name":"A slave-general takes Delhi's throne","country":"IN","kind":"nation","year":1206,"description":"Qutb ud-Din Aibak, a former slave risen to general, made himself Sultan of Delhi — founding the sultanate that would rule northern India for three centuries and raise the Qutb Minar over the city.","image":"/events/delhi-sultanate.webp","credit":"Javierfv1212","license":"CC BY-SA 3.0"},"battle-of-las-navas-de-tolosa":{"name":"The Reconquista turns at Las Navas","country":"ES","kind":"conflict","year":1212,"description":"Three Christian kings together broke the Almohad army in the Sierra Morena — the turning point of the Reconquista. Within a generation, Muslim rule in Iberia had shrunk to Granada alone.","image":"/events/battle-of-las-navas-de-tolosa.webp","credit":"Francisco de Paula Van Halen","license":"Public domain"},"children-s-crusade":{"name":"The Children's Crusade sets out","country":"FR","kind":"culture","year":1212,"description":"Thousands of children and poor folk marched for the Holy Land behind boy preachers, believing the sea would part for them. It didn't; most turned back, and legend says some were sold into slavery.","image":"/events/children-s-crusade.webp","credit":"Gustave Doré","license":"Public domain"},"fall-of-acre":{"name":"The Crusades end at Acre","country":"IL","kind":"conflict","year":1291,"description":"The Mamluks stormed the last Crusader capital on the Levantine coast, two centuries after the First Crusade took Jerusalem. The military orders sailed for Cyprus, and the Crusades in the Holy Land were over.","image":"/events/fall-of-acre.webp","credit":"Eloi-Firmin Féron","license":"Public domain"},"swiss-federal-charter":{"name":"Three cantons swear the oath","country":"CH","kind":"nation","year":1291,"description":"Three forest cantons around Lake Lucerne swore mutual defence in a parchment pact — the founding legend of Switzerland, later wrapped in the tale of William Tell. The confederacy has never since been conquered.","image":"/events/swiss-federal-charter.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"first-inauguration-of-george-washington":{"name":"Washington takes the first oath","country":"US","kind":"politics","year":1789,"description":"On a Wall Street balcony, Washington swore the oath as first President of the United States, inventing the office as he went — including the two-term habit that held for a century and a half.","image":"/events/first-inauguration-of-george-washington.webp","credit":"Internet Archive Book Images","license":"No restrictions"},"paris-metro":{"name":"Paris goes underground","country":"FR","kind":"engineering","year":1900,"description":"Paris opened its first Métro line beneath the Exposition crowds, its entrances dressed in Guimard's swirling Art Nouveau ironwork — canopies so loved they became the emblem of the city underground.","image":"/events/paris-metro.webp","credit":"Finvd","license":"CC BY-SA 4.0"},"the-football-association":{"name":"Football writes its rulebook","country":"GB","kind":"culture","year":1863,"description":"A dozen London clubs met in a tavern to write one shared rulebook for football — handling the ball was out, and the world's most popular game had its birth certificate.","image":"/events/the-football-association.webp","credit":"Di (they-them)","license":"CC BY-SA 4.0"},"coca-cola":{"name":"Coca-Cola is first served","country":"US","kind":"culture","year":1886,"description":"An Atlanta pharmacist first sold his caramel-coloured nerve tonic at a drugstore soda fountain for five cents a glass. The recipe stayed secret; the drink went on to outsell every other on Earth.","image":"/events/coca-cola.webp","credit":"The original uploader was Autiger at English Wikipedia.","license":"Public domain"},"tunguska-event":{"name":"Something explodes over Siberia","country":"RU","kind":"disaster","year":1908,"description":"Something detonated over the Siberian taiga with the force of a thousand Hiroshimas, flattening eighty million trees — yet leaving no crater. A comet or asteroid airburst remains the verdict.","image":"/events/tunguska-event.webp","credit":"Leonid Kulik, the expedition to the Tunguska event","license":"Public domain"},"peruvian-declaration-of-independence":{"name":"San Martín proclaims Peru free","country":"PE","kind":"nation","year":1821,"description":"San Martín proclaimed Peru's independence in Lima's main square after landing his army by sea from Chile. The last Spanish viceroyalty in the Americas was falling — Bolívar would finish the job at Ayacucho.","image":"/events/peruvian-declaration-of-independence.webp","credit":"Juan Lepiani","license":"Public domain"},"haitian-declaration-of-independence":{"name":"Haiti declares the first Black republic","country":"HT","kind":"nation","year":1804,"description":"Dessalines proclaimed Haiti independent at Gonaïves — the first Black republic, born of the only slave revolt in history to found a state. France exacted a crushing indemnity that Haiti paid off for over a century.","image":"/events/haitian-declaration-of-independence.webp","credit":"Unknown authorUnknown author","license":"Public domain"},"cry-of-dolores":{"name":"The cry that woke Mexico","country":"MX","kind":"revolution","year":1810,"description":"Before dawn, the priest Miguel Hidalgo rang his church bell in the town of Dolores and called the crowd to rise against Spanish rule. Every year at midnight, Mexico's president re-enacts the cry from the National Palace balcony.","image":"/events/cry-of-dolores.webp","credit":"Paigemorrison at English Wikipedia","license":"CC BY-SA 2.5"},"may-revolution":{"name":"Buenos Aires deposes the viceroy","country":"AR","kind":"revolution","year":1810,"description":"With Napoleon holding Spain's king captive, Buenos Aires deposed the Spanish viceroy and installed its own junta — a week of rain-soaked crowds that began Argentina's road to independence.","image":"/events/may-revolution.webp","credit":"Pedro Subercaseaux","license":"Public domain"},"siege-of-baghdad":{"name":"The Mongols sack Baghdad","country":"IQ","kind":"conflict","year":1258,"description":"Hulagu's Mongols razed the Abbasid capital, killed the last caliph and threw the House of Wisdom's books into the Tigris — the river was said to run black with ink. The golden age of the Islamic world's greatest city was over.","image":"/events/siege-of-baghdad.webp","credit":"Sayf al-vâhidî et al.","license":"Public domain"},"tenochtitlan":{"name":"An eagle on a cactus — Tenochtitlan is founded","country":"MX","kind":"nation","year":1325,"description":"On an island in Lake Texcoco — where, the legend says, an eagle perched on a cactus devouring a snake — the Mexica founded Tenochtitlan. The city grew into one of the largest on Earth; its symbol is on Mexico's flag.","image":"/events/tenochtitlan.webp","credit":"thomas kole","license":"CC BY 4.0"},"mali-empire":{"name":"Sundiata founds the Mali Empire","country":"ML","kind":"nation","year":1235,"description":"After victory at Kirina, Sundiata Keita united the Mande peoples into the Mali Empire — West Africa's golden-age power, whose wealth in gold and salt would stun the world when Mansa Musa later rode to Mecca.","image":"/events/mali-empire.webp","credit":"attributed to Abraham Cresques","license":"Public domain"},"taj-mahal":{"name":"The Taj Mahal is begun","country":"IN","kind":"engineering","year":1632,"description":"Shah Jahan began a white-marble tomb for his wife Mumtaz Mahal, who had died bearing their fourteenth child. Twenty thousand craftsmen worked two decades on what became the world's most famous monument to grief.","image":"/events/taj-mahal.webp","license":"CC BY-SA 3.0"},"organisation-of-african-unity":{"name":"Africa unites at Addis Ababa","country":"ET","kind":"politics","year":1963,"description":"Three dozen newly independent states signed the founding charter of the Organisation of African Unity in Addis Ababa, vowing to finish decolonisation. Its successor, the African Union, still keeps its seat there.","image":"/events/organisation-of-african-unity.webp"},"battle-of-isandlwana":{"name":"The Zulu destroy a British army","country":"ZA","kind":"conflict","year":1879,"description":"A Zulu army with spears and cowhide shields destroyed a modern British column at the foot of Isandlwana hill — the worst defeat Victorian Britain ever suffered against an African foe. The empire's shock was total.","image":"/events/battle-of-isandlwana.webp","credit":"After John Charles Dollman","license":"Public domain"},"hunminjeongeum":{"name":"King Sejong gives Korea an alphabet","country":"KR","kind":"culture","year":1446,"description":"King Sejong promulgated an alphabet so simple 'a wise man can learn it before morning is over', designed so Koreans need not write their language in Chinese characters. Hangul remains the only major script with a known birthday.","image":"/events/hunminjeongeum.webp","credit":"Kbarends at English Wikipedia","license":"Public domain"},"battle-of-talas":{"name":"Arab and Chinese empires collide at Talas","country":"KG","kind":"conflict","year":751,"description":"Abbasid and Tang armies met on the Talas river in Central Asia — the only battle ever fought between Arab and Chinese empires. Among the prisoners marched west were papermakers, and paper followed them into the Islamic world.","image":"/events/battle-of-talas.webp","credit":"SY","license":"CC BY-SA 4.0"},"gobekli-tepe":{"name":"The first temple rises","country":"TR","kind":"engineering","year":-9500,"description":"Hunter-gatherers raised rings of carved stone pillars on an Anatolian hilltop millennia before farming, pottery or the wheel — the oldest known monumental sanctuary on Earth, deliberately buried by its own builders.","image":"/events/gobekli-tepe.webp","credit":"Teomancimit","license":"CC BY-SA 3.0"},"domestication-of-the-horse":{"name":"The horse is tamed","country":"KZ","kind":"culture","year":-3500,"description":"On the steppes of Central Asia, people first bridled and milked the horse. Everything moved faster afterwards — herds, trade, languages and armies — and it stayed the engine of war until living memory.","image":"/events/domestication-of-the-horse.webp","credit":"Nataliya Shestakova","license":"CC BY-SA 4.0"},"cuneiform":{"name":"Writing is invented","country":"IQ","kind":"culture","year":-3200,"description":"In the cities of Sumer, temple accountants pressing reed styluses into wet clay invented writing — first for tallies of grain and sheep, only later for kings, laws and stories.","image":"/events/cuneiform.webp","credit":"Unknown artistUnknown artist","license":"Public domain"},"great-pyramid-of-giza":{"name":"The Great Pyramid is raised","country":"EG","kind":"engineering","year":-2560,"description":"Khufu's tomb rose in millions of quarried blocks to become the tallest structure humans had ever built — and stayed so for nearly four thousand years. It is the last of the ancient wonders still standing.","image":"/events/great-pyramid-of-giza.webp","credit":"Nina","license":"CC BY 2.5"},"code-of-hammurabi":{"name":"Hammurabi writes down the law","country":"IQ","kind":"politics","year":-1755,"description":"The Babylonian king had nearly three hundred laws carved on a black stone stele — 'an eye for an eye' among them — one of the oldest law codes ever found, now standing in the Louvre.","image":"/events/code-of-hammurabi.webp","credit":"Mbzt","license":"CC BY 3.0"},"the-tale-of-genji":{"name":"The first novel is written","country":"JP","kind":"culture","year":1010,"description":"At the Heian court, the lady-in-waiting Murasaki Shikibu completed her vast chronicle of Prince Genji's loves — often called the world's first novel, written a millennium ago by a woman whose real name is lost.","image":"/events/the-tale-of-genji.webp","credit":"Imperial Palace Kyoto","license":"Public domain"},"ancient-olympic-games":{"name":"The first Olympic Games","country":"GR","kind":"culture","year":-776,"description":"Runners raced a single sprint at Olympia in honour of Zeus — the traditional first Games. Held every four years for a millennium, they were sacred enough that warring city-states paused to compete.","image":"/events/ancient-olympic-games.webp","credit":"Walter Crane","license":"Public domain"},"founding-of-rome":{"name":"Romulus ploughs the first furrow","country":"IT","kind":"nation","year":-753,"description":"Legend set the day Romulus founded the city — and killed his twin Remus over its wall. From that hilltop village grew the empire whose languages, laws and calendars Europe still lives inside.","image":"/events/founding-of-rome.webp","license":"CC0"},"confucius":{"name":"Confucius teaches in a warring age","country":"CN","kind":"culture","year":-551,"description":"Born into a China splintering into warring states, a minor official taught that order begins with personal virtue and respect between people. His recorded sayings shaped East Asian thought for millennia."},"library-of-alexandria":{"name":"Alexandria gathers all the world's books","country":"EG","kind":"culture","year":-300,"description":"The Ptolemies set out to collect a copy of every book on Earth, seizing scrolls from ships in the harbour to be copied. Its scholars measured the planet and catalogued the stars before it was lost.","image":"/events/library-of-alexandria.webp","credit":"O. Von Corven","license":"Public domain"},"great-wall-of-china":{"name":"The Great Wall goes up","country":"CN","kind":"engineering","year":-700,"description":"Rival Chinese states began walling their northern frontiers against the steppe horsemen; later dynasties joined and rebuilt the ramparts for two thousand years into the longest structure ever built.","image":"/events/great-wall-of-china.webp","credit":"Severin.stalder","license":"CC BY-SA 3.0"},"julian-calendar":{"name":"Caesar fixes the calendar","country":"IT","kind":"science","year":-45,"description":"Rome's calendar had drifted three months from the seasons, so Caesar imposed a solar year of 365 days with a leap day every fourth. Europe kept his reckoning, barely altered, for sixteen centuries.","image":"/events/julian-calendar.webp","credit":"Ángel M. Felicísimo from Mérida, España","license":"Public domain"},"antikythera-mechanism":{"name":"A geared computer sails the Aegean","country":"GR","kind":"science","year":-100,"description":"A shoebox of bronze gears aboard a Greek ship predicted eclipses and the movements of the planets. Nothing of comparable complexity is known for the next fourteen centuries.","image":"/events/antikythera-mechanism.webp","license":"CC BY 2.5"},"nazca-lines":{"name":"Vast figures are drawn in the desert","country":"PE","kind":"culture","year":-200,"description":"The Nazca cleared dark stones from the desert floor to trace a hummingbird, a monkey and a spider hundreds of metres across — shapes best read from the sky, made by people who never saw them whole.","image":"/events/nazca-lines.webp","credit":"Diego Delso","license":"CC BY-SA 4.0"},"kingdom-of-aksum":{"name":"Aksum rises on the Red Sea","country":"ET","kind":"nation","year":-400,"description":"The Aksumite kingdom grew rich on the trade between Rome and India, minted its own gold coin and raised granite obelisks taller than any single stone the world had yet stood upright.","image":"/events/kingdom-of-aksum.webp","credit":"A.Savin","license":"FAL"},"brahmasphutasiddhanta":{"name":"Brahmagupta gives zero its rules","country":"IN","kind":"science","year":628,"description":"The astronomer Brahmagupta wrote down what happens when you add, subtract and multiply with zero and with negative numbers — treating nothing as a number. Arithmetic has run on his rules ever since."},"great-oxidation-event":{"name":"The air turns to poison, then to breath","country":"AU","kind":"disaster","year":-2450000000,"description":"Cyanobacteria began exhaling oxygen into an atmosphere that had none, rusting the oceans and wiping out most life on Earth. Everything that breathes today descends from what survived that poisoning.","image":"/events/great-oxidation-event.webp","credit":"Sciencia58","license":"CC0"},"cambrian-explosion":{"name":"Life invents almost every animal","country":"CA","kind":"science","year":-543000000,"description":"In a geological eyeblink, seas that had held little but microbes filled with eyes, shells, legs and jaws. Nearly every animal body plan alive today first appears in the rocks of that burst."},"permian-triassic-extinction-event":{"name":"The Great Dying","country":"RU","kind":"disaster","year":-251900000,"description":"Siberian volcanoes erupted for a million years and cooked the planet, killing roughly nine in ten marine species — the worst catastrophe life has ever survived. Recovery took some ten million years."},"cretaceous-paleogene-extinction-event":{"name":"The asteroid that ended the dinosaurs","country":"MX","kind":"disaster","year":-66000000,"description":"A rock the size of a city struck what is now the Yucatán at tens of kilometres a second, throwing up a shroud that darkened the world. The non-bird dinosaurs died; small furry survivors inherited the Earth."},"last-glacial-maximum":{"name":"The ice reaches its furthest","country":"CA","kind":"disaster","year":-19000,"description":"Ice sheets kilometres thick buried northern Europe and America, and so much water was locked up that seas lay a hundred metres lower — opening the land bridges that people walked into the Americas.","image":"/events/last-glacial-maximum.webp","license":"CC BY-SA 3.0"},"tet-offensive":{"name":"Tet shatters the war narrative","country":"VN","kind":"conflict","year":1968,"description":"North Vietnamese and Viet Cong forces struck a hundred towns at once during the lunar new year truce, reaching the US embassy grounds in Saigon. Militarily it failed; on American television it broke the war.","image":"/events/tet-offensive.webp","credit":"West Point","license":"Public domain"},"may-68":{"name":"Paris rises — beneath the paving stones, the beach","country":"FR","kind":"revolution","year":1968,"description":"Student barricades in the Latin Quarter set off the largest general strike in French history: ten million workers stopped, de Gaulle briefly fled the country, and the old social order never quite recovered.","image":"/events/may-68.webp","credit":"Robert Schediwy","license":"CC BY-SA 3.0"},"assassination-of-robert-f-kennedy":{"name":"A second Kennedy is shot","country":"US","kind":"politics","year":1968,"description":"Minutes after winning the California primary, the senator was shot in a hotel kitchen in Los Angeles — two months after Martin Luther King's murder, in a year that felt like it was coming apart."},"resignation-of-richard-nixon":{"name":"A president resigns","country":"US","kind":"politics","year":1974,"description":"With the Oval Office tapes released and impeachment certain, Nixon told the country he would leave office — the only US president ever to resign — and flew out of Washington by helicopter the next morning.","image":"/events/resignation-of-richard-nixon.webp","credit":"Oliver Atkins","license":"Public domain"},"the-rumble-in-the-jungle":{"name":"Ali beats Foreman in Kinshasa","country":"CD","kind":"culture","year":1974,"description":"Written off at thirty-two, Muhammad Ali leaned on the ropes and let George Foreman punch himself out before flooring him — staged in Zaire before sixty thousand people chanting his name."},"ethiopian-revolution":{"name":"The last emperor is deposed","country":"ET","kind":"revolution","year":1974,"description":"A creeping mutiny of soldiers ended three thousand years of Ethiopian monarchy, deposing Haile Selassie and installing the Derg. Famine had been hidden, and the hiding is what finally broke the throne.","image":"/events/ethiopian-revolution.webp","credit":"Unknown authorUnknown author","license":"Public domain"}}
